QString stabilization_cache_root_path() {
  const auto override_path =
      qEnvironmentVariable("PHOTO_EDITOR_TIMELINE_STABILIZATION_CACHE").trimmed();
  if (!override_path.isEmpty()) {
    return QDir::cleanPath(override_path);
  }
  return QDir(QStandardPaths::writableLocation(QStandardPaths::CacheLocation))
      .filePath(QStringLiteral("timeline-stabilization"));
}

std::optional<photo_editor::pipeline::VideoInputTransformProfile>
video_input_transform_profile(const QString& value) {
  using photo_editor::pipeline::VideoInputTransformProfile;
  const auto normalized = value.trimmed().toLower();
  if (normalized == QStringLiteral("slog2-sgamut")) {
    return VideoInputTransformProfile::SonySLog2SGamut;
  }
  if (normalized == QStringLiteral("slog3-sgamut3")) {
    return VideoInputTransformProfile::SonySLog3SGamut3;
  }
  if (normalized == QStringLiteral("slog3-sgamut3-cine")) {
    return VideoInputTransformProfile::SonySLog3SGamut3Cine;
  }
  return std::nullopt;
}

struct TimelineGradeWheelParameter final {
  QString key;
  QString zone;
  QString channel;
  double minimum = 0.0;
  double maximum = 100.0;
};

QList<TimelineGradeWheelParameter> timeline_grade_wheel_parameters() {
  return {
      {QStringLiteral("gradingShadowsHue"), QStringLiteral("shadows"),
       QStringLiteral("hue"), 0.0, 1.0},
      {QStringLiteral("gradingShadowsSaturation"), QStringLiteral("shadows"),
       QStringLiteral("saturation"), 0.0, 100.0},
      {QStringLiteral("gradingShadowsLuminance"), QStringLiteral("shadows"),
       QStringLiteral("luminance"), -100.0, 100.0},
      {QStringLiteral("gradingMidtonesHue"), QStringLiteral("midtones"),
       QStringLiteral("hue"), 0.0, 1.0},
      {QStringLiteral("gradingMidtonesSaturation"), QStringLiteral("midtones"),
       QStringLiteral("saturation"), 0.0, 100.0},
      {QStringLiteral("gradingMidtonesLuminance"), QStringLiteral("midtones"),
       QStringLiteral("luminance"), -100.0, 100.0},
      {QStringLiteral("gradingHighlightsHue"), QStringLiteral("highlights"),
       QStringLiteral("hue"), 0.0, 1.0},
      {QStringLiteral("gradingHighlightsSaturation"), QStringLiteral("highlights"),
       QStringLiteral("saturation"), 0.0, 100.0},
      {QStringLiteral("gradingHighlightsLuminance"), QStringLiteral("highlights"),
       QStringLiteral("luminance"), -100.0, 100.0},
  };
}

std::optional<TimelineGradeWheelParameter> timeline_grade_wheel_parameter(
    const QString& key) {
  const auto parameters = timeline_grade_wheel_parameters();
  const auto found = std::find_if(
      parameters.cbegin(), parameters.cend(), [&key](const auto& parameter) {
        return parameter.key == key;
      });
  return found == parameters.cend()
             ? std::nullopt
             : std::optional<TimelineGradeWheelParameter>(*found);
}

QString normalized_timeline_grade_automation_parameter(const QString& key) {
  const auto trimmed = key.trimmed();
  if (trimmed.startsWith(QStringLiteral("layer:"), Qt::CaseInsensitive)) {
    const auto suffix = trimmed.mid(6);
    const auto separator = suffix.indexOf(QLatin1Char(':'));
    if (separator <= 0 || separator >= suffix.size() - 1) {
      return {};
    }
    const auto layer_id = suffix.left(separator).trimmed();
    const auto raw_parameter = suffix.mid(separator + 1).trimmed();
    const auto parameter =
        raw_parameter.compare(QStringLiteral("opacity"), Qt::CaseInsensitive) == 0
            ? QStringLiteral("opacity")
            : normalized_timeline_grade_automation_parameter(raw_parameter);
    if (layer_id.isEmpty() || parameter.isEmpty() || parameter.startsWith(QStringLiteral("layer:"))) {
      return {};
    }
    return QStringLiteral("layer:%1:%2").arg(layer_id, parameter);
  }
  const auto global_parameters = QStringList{
      QStringLiteral("exposure"), QStringLiteral("contrast"),
      QStringLiteral("highlights"), QStringLiteral("shadows"),
      QStringLiteral("whites"), QStringLiteral("blacks"),
      QStringLiteral("temperature"), QStringLiteral("tint"),
      QStringLiteral("vibrance"), QStringLiteral("saturation")};
  for (const auto& parameter : global_parameters) {
    if (trimmed.compare(parameter, Qt::CaseInsensitive) == 0) {
      return parameter;
    }
  }
  for (const auto& parameter : timeline_grade_wheel_parameters()) {
    if (trimmed.compare(parameter.key, Qt::CaseInsensitive) == 0) {
      return parameter.key;
    }
  }
  return {};
}

std::optional<QPair<double, double>> timeline_grade_automation_bounds(
    const QString& parameter) {
  if (parameter.startsWith(QStringLiteral("layer:"), Qt::CaseInsensitive)) {
    const auto suffix = parameter.mid(6);
    const auto separator = suffix.indexOf(QLatin1Char(':'));
    if (separator <= 0 || separator >= suffix.size() - 1) {
      return std::nullopt;
    }
    const auto layer_parameter = suffix.mid(separator + 1);
    if (layer_parameter == QStringLiteral("opacity")) {
      return QPair<double, double>{0.0, 1.0};
    }
    return timeline_grade_automation_bounds(layer_parameter);
  }
  if (parameter == QStringLiteral("exposure")) {
    return QPair<double, double>{-5.0, 5.0};
  }
  if (const auto wheel = timeline_grade_wheel_parameter(parameter);
      wheel.has_value()) {
    return QPair<double, double>{wheel->minimum, wheel->maximum};
  }
  const auto global_parameters = QStringList{
      QStringLiteral("contrast"), QStringLiteral("highlights"),
      QStringLiteral("shadows"), QStringLiteral("whites"),
      QStringLiteral("blacks"), QStringLiteral("temperature"),
      QStringLiteral("tint"), QStringLiteral("vibrance"),
      QStringLiteral("saturation")};
  if (global_parameters.contains(parameter)) {
    return QPair<double, double>{-100.0, 100.0};
  }
  return std::nullopt;
}

double timeline_grade_recipe_parameter_value(
    const QString& recipe_json,
    const QString& parameter) {
  const auto document = QJsonDocument::fromJson(recipe_json.toUtf8());
  if (!document.isObject()) {
    return 0.0;
  }
  const auto recipe = document.object();
  if (parameter.startsWith(QStringLiteral("layer:"), Qt::CaseInsensitive)) {
    const auto suffix = parameter.mid(6);
    const auto separator = suffix.indexOf(QLatin1Char(':'));
    if (separator <= 0 || separator >= suffix.size() - 1) {
      return 0.0;
    }
    const auto layer_id = suffix.left(separator).trimmed();
    const auto layer_parameter = suffix.mid(separator + 1);
    for (const auto& value : recipe.value(QStringLiteral("photoLayers")).toArray()) {
      const auto layer = value.toObject();
      if (layer.value(QStringLiteral("id")).toString().trimmed() != layer_id) {
        continue;
      }
      if (layer_parameter == QStringLiteral("opacity")) {
        return layer.value(QStringLiteral("opacity")).toDouble(1.0);
      }
      if (const auto wheel = timeline_grade_wheel_parameter(layer_parameter);
          wheel.has_value()) {
        return layer.value(QStringLiteral("colorGrading"))
            .toObject()
            .value(wheel->zone)
            .toObject()
            .value(wheel->channel)
            .toDouble();
      }
      return layer.value(layer_parameter).toDouble(
          layer.value(QStringLiteral("adjustments"))
              .toObject()
              .value(layer_parameter)
              .toDouble());
    }
    return 0.0;
  }
  if (const auto wheel = timeline_grade_wheel_parameter(parameter);
      wheel.has_value()) {
    return recipe.value(QStringLiteral("colorGrading"))
        .toObject()
        .value(wheel->zone)
        .toObject()
        .value(wheel->channel)
        .toDouble();
  }
  return recipe.value(QStringLiteral("globalAdjustments"))
      .toObject()
      .value(parameter)
      .toDouble();
}

bool timeline_grade_recipe_contains_layer(
    const QString& recipe_json,
    const QString& layer_id) {
  const auto document = QJsonDocument::fromJson(recipe_json.toUtf8());
  if (!document.isObject() || layer_id.trimmed().isEmpty()) {
    return false;
  }
  for (const auto& value : document.object()
                               .value(QStringLiteral("photoLayers"))
                               .toArray()) {
    if (value.toObject().value(QStringLiteral("id")).toString().trimmed() ==
        layer_id.trimmed()) {
      return true;
    }
  }
  return false;
}

QString timeline_grade_layer_id_from_keyframe_parameter(
    const QString& parameter) {
  const auto prefix = QStringLiteral("grade:layer:");
  if (!parameter.startsWith(prefix)) {
    return {};
  }
  const auto suffix = parameter.mid(prefix.size());
  const auto separator = suffix.indexOf(QLatin1Char(':'));
  return separator > 0 ? suffix.left(separator) : QString{};
}

void insert_timeline_grade_wheel_values(
    QVariantMap* output,
    const QJsonObject& grading) {
  if (output == nullptr) {
    return;
  }
  for (const auto& parameter : timeline_grade_wheel_parameters()) {
    const auto zone = grading.value(parameter.zone).toObject();
    output->insert(parameter.key, zone.value(parameter.channel).toDouble());
  }
}

void set_timeline_grade_wheel_value(
    QJsonObject* grading,
    const TimelineGradeWheelParameter& parameter,
    double value) {
  if (grading == nullptr) {
    return;
  }
  auto zone = grading->value(parameter.zone).toObject();
  zone.insert(parameter.channel,
              qBound(parameter.minimum, value, parameter.maximum));
  grading->insert(parameter.zone, zone);
}

struct VideoInputTransformCachePaths final {
  QString input_lut_path;
  QString output_curve_lut_path;
  QString rec709_lut_path;
  bool rec709_lut_attempted = false;
  QString error_message;

  [[nodiscard]] bool ok() const {
    return error_message.isEmpty() && !input_lut_path.isEmpty() &&
           !output_curve_lut_path.isEmpty();
  }
};

constexpr auto kVideoOetfShaperScale = 0.18;

VideoInputTransformCachePaths video_input_transform_cache_paths(
    const QString& profile_key,
    bool include_shared_rec709_lut = false) {
  using photo_editor::pipeline::VideoTransformLutSettings;
  using photo_editor::pipeline::build_sony_video_input_linear_rec709_lut;
  const auto profile = video_input_transform_profile(profile_key);
  if (!profile.has_value()) {
    return {.error_message = QStringLiteral("Unknown camera input transform.")};
  }
  const auto profile_stem = profile_key.trimmed().toLower();
  const auto cache_root = QDir(QStandardPaths::writableLocation(
                                   QStandardPaths::CacheLocation))
                              .filePath(QStringLiteral("timeline-video-color-luts-v5"));
  if (cache_root == QStringLiteral("timeline-video-color-luts-v5") ||
      !QDir().mkpath(cache_root)) {
    return {.error_message = QStringLiteral("Cannot create the video color LUT cache folder.")};
  }
  const auto input_lut_path = QDir(cache_root).filePath(
      QStringLiteral("%1-linear-rec709-input-hybrid-v5.cube").arg(profile_stem));
  const auto output_curve_lut_path = QDir(cache_root).filePath(
      QStringLiteral("%1-bt709-output-asinh-1d-v5.cube").arg(profile_stem));
  const auto rec709_lut_path = QDir(cache_root).filePath(
      QStringLiteral("%1-direct-rec709-65-v1.cube").arg(profile_stem));
  const auto cache_key = input_lut_path + QLatin1Char('|') + output_curve_lut_path +
                         QLatin1Char('|') + rec709_lut_path;

  static std::mutex cache_mutex;
  static QHash<QString, VideoInputTransformCachePaths> validated_paths;
  const std::lock_guard<std::mutex> lock(cache_mutex);
  const auto cached = validated_paths.constFind(cache_key);
  if (cached != validated_paths.cend() &&
      QFileInfo(cached->input_lut_path).isReadable() &&
      QFileInfo(cached->output_curve_lut_path).isReadable() &&
      (!include_shared_rec709_lut || cached->rec709_lut_attempted) &&
      (cached->rec709_lut_path.isEmpty() ||
       QFileInfo(cached->rec709_lut_path).isReadable())) {
    return *cached;
  }
  validated_paths.remove(cache_key);

  const auto expected_input = [&]() {
    if (*profile == photo_editor::pipeline::VideoInputTransformProfile::SonySLog2SGamut) {
      return std::string("Sony S-Gamut/S-Log2");
    }
    return *profile ==
                   photo_editor::pipeline::VideoInputTransformProfile::SonySLog3SGamut3
               ? std::string("Sony S-Gamut3/S-Log3")
               : std::string("Sony S-Gamut3.Cine/S-Log3");
  }();
  const auto ensure_shared_rec709_lut = [&]() {
    if (!include_shared_rec709_lut) {
      return QString{};
    }
    const auto validate_cached_lut = [&]() {
      const auto parsed = photo_editor::pipeline::load_cube_lut_file(
          rec709_lut_path.toStdString());
      return parsed.ok() && parsed.lut.size == 65 &&
             parsed.lut.shaper_size == 0 &&
             parsed.lut.input_color_space == expected_input &&
             parsed.lut.output_color_space == "Rec.709" &&
             parsed.lut.domain_min == std::array<double, 3>{0.0, 0.0, 0.0} &&
             parsed.lut.domain_max == std::array<double, 3>{1.0, 1.0, 1.0};
    };
    if (validate_cached_lut()) {
      return rec709_lut_path;
    }
    QFile::remove(rec709_lut_path);
    const auto& built =
        photo_editor::pipeline::cached_sony_video_input_rec709_lut(*profile);
    if (!built.ok()) {
      return QString{};
    }
    const auto partial_path = rec709_lut_path + QStringLiteral(".partial");
    QFile::remove(partial_path);
    std::string write_error;
    if (!photo_editor::pipeline::save_cube_lut_file(
            partial_path.toStdString(), built.lut,
            QStringLiteral("Validated Sony camera input to Rec.709").toStdString(),
            &write_error) ||
        !QFile::rename(partial_path, rec709_lut_path) ||
        !validate_cached_lut()) {
      QFile::remove(partial_path);
      QFile::remove(rec709_lut_path);
      return QString{};
    }
    return rec709_lut_path;
  };
  const auto validate_cached_pair = [&]() {
    const auto input_lut = photo_editor::pipeline::load_cube_lut_file(
        input_lut_path.toStdString());
    const auto output_lut = photo_editor::pipeline::load_cube_lut_file(
        output_curve_lut_path.toStdString());
    return input_lut.ok() && input_lut.lut.size == 2 &&
           input_lut.lut.shaper_size == 16385 &&
           input_lut.lut.input_color_space == expected_input &&
           input_lut.lut.output_color_space == "Linear Rec.709" &&
           output_lut.ok() && output_lut.lut.size == 0 &&
           output_lut.lut.shaper_size == 16385 &&
           std::isfinite(output_lut.lut.shaper_input_range[0]) &&
           std::isfinite(output_lut.lut.shaper_input_range[1]) &&
           output_lut.lut.shaper_input_range[1] >
               output_lut.lut.shaper_input_range[0] &&
           output_lut.lut.input_color_space == "Linear Rec.709" &&
           output_lut.lut.output_color_space == "Rec.709";
  };
  if (validate_cached_pair()) {
    const auto paths = VideoInputTransformCachePaths{
        .input_lut_path = input_lut_path,
        .output_curve_lut_path = output_curve_lut_path,
        .rec709_lut_path = ensure_shared_rec709_lut(),
        .rec709_lut_attempted = include_shared_rec709_lut,
    };
    validated_paths.insert(cache_key, paths);
    return paths;
  }
  QFile::remove(input_lut_path);
  QFile::remove(output_curve_lut_path);

  auto settings = VideoTransformLutSettings{};
  settings.cube_size = 2;
  const auto built = build_sony_video_input_linear_rec709_lut(*profile, settings);
  if (!built.ok()) {
    return {.error_message = QString::fromStdString(built.failure_reason)};
  }

  const auto shaper_range = std::array<double, 2>{
      std::asinh(built.linear_rec709_output_range[0] / kVideoOetfShaperScale),
      std::asinh(built.linear_rec709_output_range[1] / kVideoOetfShaperScale),
  };
  if (!std::isfinite(shaper_range[0]) || !std::isfinite(shaper_range[1]) ||
      shaper_range[1] <= shaper_range[0]) {
    return {.error_message = QStringLiteral("Cannot shape the BT.709 output curve range.")};
  }
  auto output_curve = photo_editor::pipeline::ColorLut3D{};
  output_curve.size = 0;
  output_curve.input_color_space = "Linear Rec.709";
  output_curve.output_color_space = "Rec.709";
  output_curve.shaper_size = 16385;
  output_curve.shaper_input_range = shaper_range;
  output_curve.shaper_table.reserve(16385U);
  for (int index = 0; index < output_curve.shaper_size; ++index) {
    const auto coordinate = static_cast<double>(index) /
                            static_cast<double>(output_curve.shaper_size - 1);
    const auto shaped_value = std::lerp(shaper_range[0], shaper_range[1], coordinate);
    const auto linear_value = kVideoOetfShaperScale * std::sinh(shaped_value);
    const auto encoded_value = static_cast<float>(
        photo_editor::pipeline::encode_rec709_oetf(linear_value));
    output_curve.shaper_table.push_back(photo_editor::pipeline::ColorPixel{
        .red = encoded_value,
        .green = encoded_value,
        .blue = encoded_value,
        .alpha = 1.0F,
    });
  }
  output_curve.valid = true;

  const auto input_partial_path = input_lut_path + QStringLiteral(".partial");
  const auto output_partial_path = output_curve_lut_path + QStringLiteral(".partial");
  QFile::remove(input_partial_path);
  QFile::remove(output_partial_path);
  std::string input_write_error;
  std::string output_write_error;
  if (!photo_editor::pipeline::save_cube_lut_file(
          input_partial_path.toStdString(),
          built.lut,
          QStringLiteral("Sony camera input transform to linear Rec.709 with shaper").toStdString(),
          &input_write_error) ||
      !photo_editor::pipeline::save_cube_lut_file(
          output_partial_path.toStdString(),
          output_curve,
          QStringLiteral("BT.709 output transfer with asinh shaper").toStdString(),
          &output_write_error)) {
    QFile::remove(input_partial_path);
    QFile::remove(output_partial_path);
    return {.error_message = QString::fromStdString(
                input_write_error.empty() ? output_write_error : input_write_error)};
  }
  QFile::remove(input_lut_path);
  QFile::remove(output_curve_lut_path);
  if (!QFile::rename(input_partial_path, input_lut_path) ||
      !QFile::rename(output_partial_path, output_curve_lut_path)) {
    QFile::remove(input_partial_path);
    QFile::remove(output_partial_path);
    QFile::remove(input_lut_path);
    QFile::remove(output_curve_lut_path);
    return {.error_message = QStringLiteral("Cannot publish the generated video color LUT stages.")};
  }

  const auto paths = VideoInputTransformCachePaths{
      .input_lut_path = input_lut_path,
      .output_curve_lut_path = output_curve_lut_path,
      .rec709_lut_path = ensure_shared_rec709_lut(),
      .rec709_lut_attempted = include_shared_rec709_lut,
  };
  validated_paths.insert(cache_key, paths);
  while (validated_paths.size() > 8) {
    validated_paths.erase(validated_paths.begin());
  }
  return paths;
}

struct TimelineCubeLutFilters final {
  QString one_d_path;
  QString three_d_path;
  QString input_color_adapter_path;
  QString output_color_adapter_path;
  std::array<double, 2> one_d_input_range{0.0, 1.0};
  QString error_message;

  [[nodiscard]] bool ok() const {
    return error_message.isEmpty() &&
           (!one_d_path.isEmpty() || !three_d_path.isEmpty());
  }
};

struct TimelineCubeColorAdapters final {
  QString input_path;
  QString output_path;
  QString error_message;

  [[nodiscard]] bool ok() const { return error_message.isEmpty(); }
};

[[nodiscard]] photo_editor::pipeline::ColorPixel apply_timeline_color_matrix(
    const photo_editor::pipeline::ColorPixel& pixel,
    const photo_editor::pipeline::ColorMatrix3& matrix) {
  const auto& m = matrix.values;
  return {
      .red = static_cast<float>(m[0] * pixel.red + m[1] * pixel.green + m[2] * pixel.blue),
      .green = static_cast<float>(m[3] * pixel.red + m[4] * pixel.green + m[5] * pixel.blue),
      .blue = static_cast<float>(m[6] * pixel.red + m[7] * pixel.green + m[8] * pixel.blue),
      .alpha = pixel.alpha,
  };
}

using TimelineColorPixel = photo_editor::pipeline::ColorPixel;
using TimelineRgbColorSpace = photo_editor::pipeline::RgbColorSpace;
using TimelineTransferFunction = photo_editor::pipeline::TransferFunction;

struct TimelineLutColorConversion final {
  TimelineTransferFunction source_transfer = TimelineTransferFunction::Unknown;
  TimelineTransferFunction destination_transfer = TimelineTransferFunction::Unknown;
  photo_editor::pipeline::ColorMatrix3 matrix;

  [[nodiscard]] TimelineColorPixel apply(const TimelineColorPixel& pixel) const {
    const auto decode = [transfer = source_transfer](float value) {
      return static_cast<float>(
          photo_editor::pipeline::decode_color_transfer_function(value, transfer));
    };
    const auto encode = [transfer = destination_transfer](float value) {
      return static_cast<float>(
          photo_editor::pipeline::encode_color_transfer_function(value, transfer));
    };
    auto linear = TimelineColorPixel{
        .red = decode(pixel.red),
        .green = decode(pixel.green),
        .blue = decode(pixel.blue),
        .alpha = pixel.alpha,
    };
    linear = apply_timeline_color_matrix(linear, matrix);
    return {
        .red = encode(linear.red),
        .green = encode(linear.green),
        .blue = encode(linear.blue),
        .alpha = pixel.alpha,
    };
  }
};

[[nodiscard]] TimelineLutColorConversion compile_timeline_lut_color_conversion(
    const TimelineRgbColorSpace& source,
    const TimelineRgbColorSpace& destination) {
  auto linear_source = source;
  linear_source.transfer_function = TimelineTransferFunction::Linear;
  linear_source.scene_referred = true;
  auto linear_destination = destination;
  linear_destination.transfer_function = TimelineTransferFunction::Linear;
  linear_destination.scene_referred = true;
  return {
      .source_transfer = source.transfer_function,
      .destination_transfer = destination.transfer_function,
      .matrix = photo_editor::pipeline::compile_builtin_color_transform(
                    linear_source, linear_destination)
                    .matrix,
  };
}

[[nodiscard]] bool timeline_rec709_signal_space(
    const TimelineRgbColorSpace& color_space) {
  return color_space.primaries == photo_editor::pipeline::ColorPrimaries::Rec709 &&
         color_space.transfer_function == TimelineTransferFunction::Bt709 &&
         color_space.white_point == photo_editor::pipeline::WhitePoint::D65;
}

[[nodiscard]] QString timeline_user_cube_lut_cache_root() {
  const auto cache_location =
      QStandardPaths::writableLocation(QStandardPaths::CacheLocation);
  if (!cache_location.trimmed().isEmpty()) {
    const auto cache_root = QDir(cache_location).filePath(
        QStringLiteral("timeline-user-cube-luts-v1"));
    if (QDir().mkpath(cache_root) && QFileInfo(cache_root).isWritable()) {
      return QDir::cleanPath(cache_root);
    }
  }

  const auto temporary_root = QDir(QDir::tempPath()).filePath(
      QStringLiteral("photo-editor/timeline-user-cube-luts-v1"));
  if (QDir().mkpath(temporary_root)) {
    return QDir::cleanPath(temporary_root);
  }
  return {};
}

[[nodiscard]] TimelineCubeColorAdapters timeline_cube_color_adapters(
    const photo_editor::pipeline::ColorLut3D& lut,
    const QString& cache_root,
    const QString& cache_identity) {
  const auto input_space = photo_editor::pipeline::resolve_builtin_rgb_color_space(
      lut.input_color_space);
  const auto output_space = photo_editor::pipeline::resolve_builtin_rgb_color_space(
      lut.output_color_space);
  if (!input_space.has_value() || !output_space.has_value()) {
    return {.error_message = QStringLiteral(
                "The CUBE LUT declares a color space that the shared photo engine cannot transform.")};
  }

  auto adapters = TimelineCubeColorAdapters{};
  const auto input_is_rec709 = timeline_rec709_signal_space(*input_space);
  const auto output_is_rec709 = timeline_rec709_signal_space(*output_space);
  if (input_is_rec709 && output_is_rec709) {
    return adapters;
  }
  if (!QDir().mkpath(cache_root)) {
    return {.error_message = QStringLiteral("Cannot create the tagged CUBE adapter cache folder.")};
  }

  const auto input_path = QDir(cache_root).filePath(
      cache_identity + QStringLiteral("-to-declared-input.cube"));
  const auto output_path = QDir(cache_root).filePath(
      cache_identity + QStringLiteral("-from-declared-output.cube"));

  const auto build_adapter = [](
                                 const QString& path,
                                 const TimelineRgbColorSpace& source,
                                 const TimelineRgbColorSpace& destination,
                                 const std::array<double, 3>& domain_min,
                                 const std::array<double, 3>& domain_max,
                                 const QString& title) -> QString {
    constexpr auto maximum_size = 65;
    constexpr auto p99_error_limit = 0.0015;
    constexpr auto maximum_error_limit = 0.005;
    const auto conversion = compile_timeline_lut_color_conversion(source, destination);
    const auto cached = photo_editor::pipeline::load_cube_lut_file(path.toStdString());
    if (cached.ok() && cached.lut.size >= 2 &&
        cached.lut.domain_min == domain_min && cached.lut.domain_max == domain_max &&
        cached.lut.input_color_space == source.name &&
        cached.lut.output_color_space == destination.name) {
      return {};
    }
    QFile::remove(path);
    auto chosen = photo_editor::pipeline::ColorLut3D{};
    auto passed = false;
    for (const auto size : {33, 49, maximum_size}) {
      const auto cube_size = static_cast<std::size_t>(size);
      chosen = photo_editor::pipeline::ColorLut3D{};
      chosen.size = size;
      chosen.domain_min = domain_min;
      chosen.domain_max = domain_max;
      chosen.input_color_space = source.name;
      chosen.output_color_space = destination.name;
      chosen.table.resize(cube_size * cube_size * cube_size);
      const auto coordinate = [size](int index, int channel,
                                     const std::array<double, 3>& minimum,
                                     const std::array<double, 3>& maximum) {
        const auto fraction = static_cast<double>(index) /
                              static_cast<double>(size - 1);
        return std::lerp(minimum[static_cast<std::size_t>(channel)],
                         maximum[static_cast<std::size_t>(channel)], fraction);
      };
      for (int red = 0; red < size; ++red) {
        for (int green = 0; green < size; ++green) {
          for (int blue = 0; blue < size; ++blue) {
            const auto input = TimelineColorPixel{
                .red = static_cast<float>(coordinate(red, 0, domain_min, domain_max)),
                .green = static_cast<float>(coordinate(green, 1, domain_min, domain_max)),
                .blue = static_cast<float>(coordinate(blue, 2, domain_min, domain_max)),
                .alpha = 1.0F,
            };
            const auto index = static_cast<std::size_t>(red) * cube_size * cube_size +
                               static_cast<std::size_t>(green) * cube_size +
                               static_cast<std::size_t>(blue);
            chosen.table[index] = conversion.apply(input);
          }
        }
      }
      chosen.valid = true;
      std::vector<double> errors;
      constexpr auto validation_grid_size = 19;
      errors.reserve(validation_grid_size * validation_grid_size * validation_grid_size);
      auto maximum_error = 0.0;
      const auto sample_coordinate = [](
                                          int index,
                                          int channel,
                                          const std::array<double, 3>& minimum,
                                          const std::array<double, 3>& maximum) {
        const auto fraction = static_cast<double>(index) /
                              static_cast<double>(validation_grid_size - 1);
        return std::lerp(minimum[static_cast<std::size_t>(channel)],
                         maximum[static_cast<std::size_t>(channel)], fraction);
      };
      for (int red = 0; red < validation_grid_size; ++red) {
        for (int green = 0; green < validation_grid_size; ++green) {
          for (int blue = 0; blue < validation_grid_size; ++blue) {
            const auto sample = TimelineColorPixel{
                .red = static_cast<float>(sample_coordinate(red, 0, domain_min, domain_max)),
                .green = static_cast<float>(sample_coordinate(green, 1, domain_min, domain_max)),
                .blue = static_cast<float>(sample_coordinate(blue, 2, domain_min, domain_max)),
                .alpha = 1.0F,
            };
            const auto expected = conversion.apply(sample);
            const auto actual = photo_editor::pipeline::apply_lut(chosen, sample);
            const auto error = std::max({
                std::abs(static_cast<double>(expected.red) - actual.red),
                std::abs(static_cast<double>(expected.green) - actual.green),
                std::abs(static_cast<double>(expected.blue) - actual.blue),
            });
            errors.push_back(error);
            maximum_error = std::max(maximum_error, error);
          }
        }
      }
      const auto p99_index = static_cast<std::size_t>(
          std::ceil(static_cast<double>(errors.size()) * 0.99) - 1.0);
      std::nth_element(errors.begin(), errors.begin() +
                           static_cast<std::ptrdiff_t>(p99_index), errors.end());
      if (errors[p99_index] <= p99_error_limit &&
          maximum_error <= maximum_error_limit) {
        passed = true;
        break;
      }
    }
    if (!passed) {
      return QStringLiteral(
          "A tagged CUBE color adapter did not meet the shared engine's export accuracy limits.");
    }
    const auto partial_path = path + QStringLiteral(".partial");
    QFile::remove(partial_path);
    std::string write_error;
    if (!photo_editor::pipeline::save_cube_lut_file(
            partial_path.toStdString(), chosen, title.toStdString(), &write_error)) {
      QFile::remove(partial_path);
      return QString::fromStdString(write_error);
    }
    if (!QFile::rename(partial_path, path)) {
      QFile::remove(partial_path);
      return QStringLiteral("Cannot publish a tagged CUBE color adapter.");
    }
    return {};
  };

  const auto rec709_signal = photo_editor::pipeline::make_rec709_color_space();
  if (!input_is_rec709) {
    const auto error = build_adapter(
        input_path, rec709_signal, *input_space,
        {0.0, 0.0, 0.0}, {1.0, 1.0, 1.0},
        QStringLiteral("Rec.709 to declared CUBE input"));
    if (!error.isEmpty()) {
      return {.error_message = error};
    }
    adapters.input_path = input_path;
  }
  if (!output_is_rec709) {
    auto output_min = std::array<double, 3>{
        std::numeric_limits<double>::infinity(),
        std::numeric_limits<double>::infinity(),
        std::numeric_limits<double>::infinity()};
    auto output_max = std::array<double, 3>{
        -std::numeric_limits<double>::infinity(),
        -std::numeric_limits<double>::infinity(),
        -std::numeric_limits<double>::infinity()};
    const auto& output_table = lut.size > 0 ? lut.table : lut.shaper_table;
    if (output_table.empty()) {
      return {.error_message = QStringLiteral("The CUBE LUT has no output samples for color conversion.")};
    }
    for (const auto& sample : output_table) {
      const auto channels = std::array<double, 3>{sample.red, sample.green, sample.blue};
      for (std::size_t channel = 0; channel < channels.size(); ++channel) {
        if (!std::isfinite(channels[channel])) {
          return {.error_message = QStringLiteral("The CUBE LUT contains non-finite output values.")};
        }
        output_min[channel] = std::min(output_min[channel], channels[channel]);
        output_max[channel] = std::max(output_max[channel], channels[channel]);
      }
    }
    for (std::size_t channel = 0; channel < output_min.size(); ++channel) {
      if (output_max[channel] - output_min[channel] < 1.0e-8) {
        const auto extent = std::max(1.0e-6, std::abs(output_min[channel]) * 1.0e-6);
        output_min[channel] -= extent;
        output_max[channel] += extent;
      }
    }
    const auto error = build_adapter(
        output_path, *output_space, rec709_signal,
        output_min, output_max,
        QStringLiteral("Declared CUBE output to Rec.709"));
    if (!error.isEmpty()) {
      return {.error_message = error};
    }
    adapters.output_path = output_path;
  }
  return adapters;
}

[[nodiscard]] QString validate_timeline_cube_export_adapters(
    const photo_editor::pipeline::ColorLut3D& lut,
    const TimelineCubeLutFilters& filters) {
  if (filters.input_color_adapter_path.isEmpty() &&
      filters.output_color_adapter_path.isEmpty()) {
    return {};
  }
  auto lut_state = photo_editor::pipeline::ColorAdjustmentState{};
  // The photo engine's linear sRGB working space shares Rec.709 primaries
  // and D65 white, while its profile selector has no separate linear Rec.709
  // entry. Use the canonical supported profile rather than falling back to
  // Linear ProPhoto RGB for an unrecognized name.
  lut_state.color_pipeline.working_profile =
      photo_editor::pipeline::working_color_profile_from_name("Linear sRGB");
  lut_state.lut_enabled = true;
  lut_state.lut_strength = 100.0;
  lut_state.lut_size = lut.size;
  lut_state.lut_domain_min = lut.domain_min;
  lut_state.lut_domain_max = lut.domain_max;
  lut_state.lut_input_color_space = lut.input_color_space;
  lut_state.lut_output_color_space = lut.output_color_space;
  lut_state.lut_table = lut.table;
  lut_state.lut_shaper_table = lut.shaper_table;
  lut_state.lut_shaper_size = lut.shaper_size;
  lut_state.lut_shaper_input_range = lut.shaper_input_range;
  const auto program = photo_editor::pipeline::compile_user_lut_stage_program(lut_state);
  if (!program.ready()) {
    return QStringLiteral("The shared photo engine could not compile the tagged CUBE LUT for export parity checks.");
  }
  photo_editor::pipeline::ColorLut3D input_adapter;
  photo_editor::pipeline::ColorLut3D output_adapter;
  if (!filters.input_color_adapter_path.isEmpty()) {
    auto parsed = photo_editor::pipeline::load_cube_lut_file(
        filters.input_color_adapter_path.toStdString());
    if (!parsed.ok()) {
      return QStringLiteral("The cached CUBE input adapter is invalid.");
    }
    input_adapter = std::move(parsed.lut);
  }
  if (!filters.output_color_adapter_path.isEmpty()) {
    auto parsed = photo_editor::pipeline::load_cube_lut_file(
        filters.output_color_adapter_path.toStdString());
    if (!parsed.ok()) {
      return QStringLiteral("The cached CUBE output adapter is invalid.");
    }
    output_adapter = std::move(parsed.lut);
  }

  constexpr auto validation_grid_size = 19;
  constexpr auto p99_error_limit = 0.0015;
  constexpr auto maximum_error_limit = 0.005;
  std::vector<double> errors;
  errors.reserve(validation_grid_size * validation_grid_size * validation_grid_size);
  auto maximum_error = 0.0;
  auto worst_input = TimelineColorPixel{};
  auto worst_lut_input = TimelineColorPixel{};
  auto worst_lut_output = TimelineColorPixel{};
  auto worst_expected = TimelineColorPixel{};
  auto worst_actual = TimelineColorPixel{};
  const auto sample_channel = [](int index) {
    return static_cast<float>(static_cast<double>(index) /
                              static_cast<double>(validation_grid_size - 1));
  };
  for (int red = 0; red < validation_grid_size; ++red) {
    for (int green = 0; green < validation_grid_size; ++green) {
      for (int blue = 0; blue < validation_grid_size; ++blue) {
        const auto encoded_input = TimelineColorPixel{
            .red = sample_channel(red),
            .green = sample_channel(green),
            .blue = sample_channel(blue),
            .alpha = 1.0F,
        };
        const auto linear_input = TimelineColorPixel{
            .red = static_cast<float>(photo_editor::pipeline::decode_color_transfer_function(
                encoded_input.red, TimelineTransferFunction::Bt709)),
            .green = static_cast<float>(photo_editor::pipeline::decode_color_transfer_function(
                encoded_input.green, TimelineTransferFunction::Bt709)),
            .blue = static_cast<float>(photo_editor::pipeline::decode_color_transfer_function(
                encoded_input.blue, TimelineTransferFunction::Bt709)),
            .alpha = 1.0F,
        };
        const auto exact_working =
            photo_editor::pipeline::apply_compiled_user_lut_stage_program(
                program, linear_input);
        const auto expected = TimelineColorPixel{
            .red = static_cast<float>(photo_editor::pipeline::encode_color_transfer_function(
                exact_working.red, TimelineTransferFunction::Bt709)),
            .green = static_cast<float>(photo_editor::pipeline::encode_color_transfer_function(
                exact_working.green, TimelineTransferFunction::Bt709)),
            .blue = static_cast<float>(photo_editor::pipeline::encode_color_transfer_function(
                exact_working.blue, TimelineTransferFunction::Bt709)),
            .alpha = 1.0F,
        };
        auto actual = encoded_input;
        if (!filters.input_color_adapter_path.isEmpty()) {
          actual = photo_editor::pipeline::apply_lut(input_adapter, actual);
        }
        const auto lut_input = actual;
        const auto lut_output = photo_editor::pipeline::apply_lut(lut, lut_input);
        actual = lut_output;
        if (!filters.output_color_adapter_path.isEmpty()) {
          actual = photo_editor::pipeline::apply_lut(output_adapter, actual);
        }
        const auto error = std::max({
            std::abs(static_cast<double>(expected.red) - actual.red),
            std::abs(static_cast<double>(expected.green) - actual.green),
            std::abs(static_cast<double>(expected.blue) - actual.blue),
        });
        errors.push_back(error);
        if (error > maximum_error) {
          maximum_error = error;
          worst_input = encoded_input;
          worst_lut_input = lut_input;
          worst_lut_output = lut_output;
          worst_expected = expected;
          worst_actual = actual;
        }
      }
    }
  }
  const auto p99_index = static_cast<std::size_t>(
      std::ceil(static_cast<double>(errors.size()) * 0.99) - 1.0);
  std::nth_element(errors.begin(), errors.begin() +
                       static_cast<std::ptrdiff_t>(p99_index), errors.end());
  if (errors[p99_index] > p99_error_limit || maximum_error > maximum_error_limit) {
    return QStringLiteral(
        "The tagged CUBE export path exceeds the shared engine's p99 0.0015 or maximum 0.005 color error limit (p99=%1, max=%2 at input %3,%4,%5: LUT input=%6,%7,%8 output=%9,%10,%11 expected=%12,%13,%14 got=%15,%16,%17).")
        .arg(errors[p99_index], 0, 'g', 6)
        .arg(maximum_error, 0, 'g', 6)
        .arg(worst_input.red, 0, 'g', 6)
        .arg(worst_input.green, 0, 'g', 6)
        .arg(worst_input.blue, 0, 'g', 6)
        .arg(worst_lut_input.red, 0, 'g', 6)
        .arg(worst_lut_input.green, 0, 'g', 6)
        .arg(worst_lut_input.blue, 0, 'g', 6)
        .arg(worst_lut_output.red, 0, 'g', 6)
        .arg(worst_lut_output.green, 0, 'g', 6)
        .arg(worst_lut_output.blue, 0, 'g', 6)
        .arg(worst_expected.red, 0, 'g', 6)
        .arg(worst_expected.green, 0, 'g', 6)
        .arg(worst_expected.blue, 0, 'g', 6)
        .arg(worst_actual.red, 0, 'g', 6)
        .arg(worst_actual.green, 0, 'g', 6)
        .arg(worst_actual.blue, 0, 'g', 6);
  }
  return {};
}

TimelineCubeLutFilters timeline_cube_lut_filters(
    const QString& source_path,
    photo_editor::pipeline::CubeLutParseResult* parsed_override = nullptr,
    bool compile_color_space_adapters = false) {
  const QFileInfo source_info(source_path);
  if (!source_info.isFile() || !source_info.isReadable()) {
    return {.error_message = QStringLiteral("The selected CUBE LUT is not readable.")};
  }
  const auto normalized_source_path = QDir::cleanPath(source_info.absoluteFilePath());
  const auto source_key = QStringLiteral("%1|%2|%3")
                              .arg(normalized_source_path)
                              .arg(source_info.size())
                              .arg(source_info.lastModified().toMSecsSinceEpoch());
  const auto filters_key = compile_color_space_adapters
                               ? source_key + QStringLiteral("|declared-color-spaces-v2")
                               : source_key;
  static std::mutex cache_mutex;
  static QHash<QString, TimelineCubeLutFilters> cached_filters;
  const std::lock_guard<std::mutex> lock(cache_mutex);
  const auto remember_filters = [](
                                   const QString& key,
                                   const TimelineCubeLutFilters& filters) {
    cached_filters.insert(key, filters);
    while (cached_filters.size() > 128) {
      cached_filters.erase(cached_filters.begin());
    }
  };
  const auto cached = cached_filters.constFind(filters_key);
  if (cached != cached_filters.cend() &&
      (cached->one_d_path.isEmpty() || QFileInfo(cached->one_d_path).isReadable()) &&
      (cached->three_d_path.isEmpty() || QFileInfo(cached->three_d_path).isReadable()) &&
      (cached->input_color_adapter_path.isEmpty() ||
       QFileInfo(cached->input_color_adapter_path).isReadable()) &&
      (cached->output_color_adapter_path.isEmpty() ||
       QFileInfo(cached->output_color_adapter_path).isReadable())) {
    return *cached;
  }

  auto parsed = parsed_override != nullptr
                    ? std::move(*parsed_override)
                    : photo_editor::pipeline::load_cube_lut_file(
                          normalized_source_path.toStdString());
  if (!parsed.ok()) {
    return {.error_message = QStringLiteral("The selected CUBE LUT is invalid: %1")
                                 .arg(QString::fromStdString(parsed.error_message))};
  }
  auto filters = TimelineCubeLutFilters{};
  if (compile_color_space_adapters) {
    const auto adapter_identity = QString::fromLatin1(
        QCryptographicHash::hash(
            (source_key + QStringLiteral("|timeline-cube-tag-adapter-v2")).toUtf8(),
            QCryptographicHash::Sha256)
            .toHex());
    const auto cache_root = timeline_user_cube_lut_cache_root();
    if (cache_root.isEmpty()) {
      return {.error_message = QStringLiteral("Cannot locate the tagged CUBE adapter cache folder.")};
    }
    const auto adapters = timeline_cube_color_adapters(
        parsed.lut, cache_root, adapter_identity);
    if (!adapters.ok()) {
      return {.error_message = adapters.error_message};
    }
    filters.input_color_adapter_path = adapters.input_path;
    filters.output_color_adapter_path = adapters.output_path;
    const auto parity_error = validate_timeline_cube_export_adapters(
        parsed.lut, filters);
    if (!parity_error.isEmpty()) {
      return {.error_message = parity_error};
    }
  }
  if (parsed.lut.shaper_size == 0 && parsed.lut.size > 0) {
    filters.three_d_path = normalized_source_path;
    remember_filters(filters_key, filters);
    return filters;
  }

  const auto cache_root = timeline_user_cube_lut_cache_root();
  if (cache_root.isEmpty()) {
    return {.error_message = QStringLiteral("Cannot create the split CUBE LUT cache folder.")};
  }
  const auto cache_identity = QString::fromLatin1(
      QCryptographicHash::hash(source_key.toUtf8(), QCryptographicHash::Sha256).toHex());
  const auto one_d_path = QDir(cache_root).filePath(
      cache_identity + QStringLiteral("-shaper.cube"));
  const auto three_d_path = QDir(cache_root).filePath(
      cache_identity + QStringLiteral("-cube.cube"));
  const auto has_shaper = parsed.lut.shaper_size > 0;
  const auto has_three_d = parsed.lut.size > 0;
  const auto normalized_shaper_range = std::array<double, 2>{0.0, 1.0};
  const auto valid_cached_stage = [&parsed](const QString& path, bool shaper) {
    if (!QFileInfo(path).isReadable()) {
      return false;
    }
    const auto cached_lut = photo_editor::pipeline::load_cube_lut_file(
        path.toStdString());
    return cached_lut.ok() &&
           (shaper ? cached_lut.lut.shaper_size == parsed.lut.shaper_size &&
                         cached_lut.lut.size == 0 &&
                         cached_lut.lut.shaper_input_range ==
                             std::array<double, 2>{0.0, 1.0}
                   : cached_lut.lut.shaper_size == 0 &&
                         cached_lut.lut.size == parsed.lut.size);
  };
  const auto shaper_cache_valid =
      !has_shaper || valid_cached_stage(one_d_path, true);
  const auto three_d_cache_valid =
      !has_three_d || !has_shaper || valid_cached_stage(three_d_path, false);
  if (!shaper_cache_valid || !three_d_cache_valid) {
    QFile::remove(one_d_path);
    QFile::remove(three_d_path);
    auto shaper_lut = photo_editor::pipeline::ColorLut3D{};
    shaper_lut.size = 0;
    shaper_lut.domain_min = parsed.lut.domain_min;
    shaper_lut.domain_max = parsed.lut.domain_max;
    shaper_lut.input_color_space = parsed.lut.input_color_space;
    shaper_lut.output_color_space = parsed.lut.output_color_space;
    shaper_lut.shaper_table = std::move(parsed.lut.shaper_table);
    shaper_lut.shaper_size = parsed.lut.shaper_size;
    shaper_lut.shaper_input_range = normalized_shaper_range;
    shaper_lut.valid = true;
    auto three_d_lut = photo_editor::pipeline::ColorLut3D{};
    three_d_lut.table = std::move(parsed.lut.table);
    three_d_lut.size = parsed.lut.size;
    three_d_lut.domain_min = parsed.lut.domain_min;
    three_d_lut.domain_max = parsed.lut.domain_max;
    three_d_lut.input_color_space = parsed.lut.input_color_space;
    three_d_lut.output_color_space = parsed.lut.output_color_space;
    three_d_lut.valid = true;

    const auto publish_stage = [](const QString& path,
                                  const photo_editor::pipeline::ColorLut3D& lut,
                                  const QString& title,
                                  QString* error_message) {
      const auto partial_path = path + QStringLiteral(".partial");
      QFile::remove(partial_path);
      std::string write_error;
      if (!photo_editor::pipeline::save_cube_lut_file(
              partial_path.toStdString(), lut, title.toStdString(), &write_error)) {
        QFile::remove(partial_path);
        *error_message = QString::fromStdString(write_error);
        return false;
      }
      if (!QFile::rename(partial_path, path)) {
        QFile::remove(partial_path);
        *error_message = QStringLiteral("Cannot publish a split CUBE LUT stage.");
        return false;
      }
      return true;
    };
    QString publish_error;
    if ((has_shaper &&
         !publish_stage(one_d_path, shaper_lut, QStringLiteral("CUBE 1D shaper"), &publish_error)) ||
        (has_three_d && has_shaper &&
         !publish_stage(three_d_path, three_d_lut, QStringLiteral("CUBE 3D table"), &publish_error))) {
      QFile::remove(one_d_path);
      QFile::remove(three_d_path);
      return {.error_message = publish_error};
    }
  }

  filters.one_d_path = has_shaper ? one_d_path : QString{};
  filters.three_d_path = has_three_d
                             ? (has_shaper ? three_d_path : normalized_source_path)
                             : QString{};
  filters.one_d_input_range = parsed.lut.shaper_input_range;
  remember_filters(filters_key, filters);
  return filters;
}

QVariantMap normalized_smart_collection_rules(const QVariantMap& input) {
  QVariantMap rules;
  const auto copy_enum = [&input, &rules](
                             const QString& key,
                             const QSet<QString>& allowed) {
    const auto value = input.value(key).toString().simplified().toLower();
    if (!value.isEmpty() && value != QStringLiteral("any") && allowed.contains(value)) {
      rules.insert(key, value);
    }
  };
  copy_enum(
      QStringLiteral("mediaType"),
      {QStringLiteral("photo"), QStringLiteral("video"), QStringLiteral("audio")});
  copy_enum(
      QStringLiteral("colorLabel"),
      {QStringLiteral("none"), QStringLiteral("red"), QStringLiteral("orange"),
       QStringLiteral("yellow"), QStringLiteral("green"), QStringLiteral("blue"),
       QStringLiteral("purple")});
  copy_enum(
      QStringLiteral("orientation"),
      {QStringLiteral("landscape"), QStringLiteral("portrait"), QStringLiteral("square")});
  copy_enum(
      QStringLiteral("onlineState"),
      {QStringLiteral("online"), QStringLiteral("offline")});
  copy_enum(
      QStringLiteral("usage"),
      {QStringLiteral("used"), QStringLiteral("unused")});

  const auto minimum_rating = qBound(0, input.value(QStringLiteral("minimumRating")).toInt(), 5);
  if (minimum_rating > 0) {
    rules.insert(QStringLiteral("minimumRating"), minimum_rating);
  }
  const auto tag = input.value(QStringLiteral("tag")).toString().simplified().left(32);
  if (!tag.isEmpty()) {
    rules.insert(QStringLiteral("tag"), tag);
  }
  const auto custom_field =
      input.value(QStringLiteral("customField")).toString().simplified().left(48);
  const auto custom_value =
      input.value(QStringLiteral("customValue")).toString().simplified().left(200);
  if (!custom_field.isEmpty() && !custom_value.isEmpty()) {
    rules.insert(QStringLiteral("customField"), custom_field);
    rules.insert(QStringLiteral("customValue"), custom_value);
  }
  const auto date_from = QDate::fromString(
      input.value(QStringLiteral("dateFrom")).toString().trimmed(), Qt::ISODate);
  const auto date_to = QDate::fromString(
      input.value(QStringLiteral("dateTo")).toString().trimmed(), Qt::ISODate);
  if (date_from.isValid()) {
    rules.insert(QStringLiteral("dateFrom"), date_from.toString(Qt::ISODate));
  }
  if (date_to.isValid()) {
    rules.insert(QStringLiteral("dateTo"), date_to.toString(Qt::ISODate));
  }
  const auto minimum_duration =
      qMax(0.0, input.value(QStringLiteral("minimumDuration")).toDouble());
  const auto maximum_duration =
      qMax(0.0, input.value(QStringLiteral("maximumDuration")).toDouble());
  if (minimum_duration > 0.0) {
    rules.insert(QStringLiteral("minimumDuration"), minimum_duration);
  }
  if (maximum_duration > 0.0) {
    rules.insert(QStringLiteral("maximumDuration"), maximum_duration);
  }
  return rules;
}

double cubic_bezier_coordinate(
    double p0,
    double p1,
    double p2,
    double p3,
    double parameter) {
  const auto inverse = 1.0 - parameter;
  return inverse * inverse * inverse * p0 +
         3.0 * inverse * inverse * parameter * p1 +
         3.0 * inverse * parameter * parameter * p2 +
         parameter * parameter * parameter * p3;
}

double cubic_bezier_value_for_progress(
    double progress,
    double x1,
    double value0,
    double value1,
    double x2,
    double value2,
    double value3) {
  const auto target = qBound(0.0, progress, 1.0);
  auto lower = 0.0;
  auto upper = 1.0;
  for (auto iteration = 0; iteration < 24; ++iteration) {
    const auto midpoint = (lower + upper) * 0.5;
    const auto x = cubic_bezier_coordinate(0.0, x1, x2, 1.0, midpoint);
    if (x < target) {
      lower = midpoint;
    } else {
      upper = midpoint;
    }
  }
  return cubic_bezier_coordinate(
      value0, value1, value2, value3, (lower + upper) * 0.5);
}

QString ffmpeg_cubic_bezier_segment_expression(
    const QString& progress_expression,
    double x1,
    double value0,
    double value1,
    double x2,
    double value2,
    double value3) {
  const auto number = [](double value) { return QString::number(value, 'f', 8); };
  auto expression = number(value3);
  for (auto sample = kBezierExportSamplesPerSegment - 1; sample >= 0; --sample) {
    const auto start_progress =
        static_cast<double>(sample) / kBezierExportSamplesPerSegment;
    const auto end_progress =
        static_cast<double>(sample + 1) / kBezierExportSamplesPerSegment;
    const auto start_value = cubic_bezier_value_for_progress(
        start_progress, x1, value0, value1, x2, value2, value3);
    const auto end_value = cubic_bezier_value_for_progress(
        end_progress, x1, value0, value1, x2, value2, value3);
    const auto local_progress =
        QStringLiteral("((%1-%2)/%3)")
            .arg(progress_expression)
            .arg(number(start_progress))
            .arg(number(end_progress - start_progress));
    const auto sample_expression =
        QStringLiteral("(%1+(%2-%1)*%3)")
            .arg(number(start_value))
            .arg(number(end_value))
            .arg(local_progress);
    expression = QStringLiteral("if(lt(%1,%2),%3,%4)")
                     .arg(progress_expression)
                     .arg(number(end_progress))
                     .arg(sample_expression)
                     .arg(expression);
  }
  return expression;
}

QVariantMap diarize_transcription_words_locally(
    const QString& source_path,
    const QVariantList& input_words,
    const std::shared_ptr<std::atomic_bool>& cancel_token) {
  QVariantList words = input_words;
  QSet<QString> provider_speakers;
  for (const auto& value : words) {
    const auto speaker = value.toMap().value(QStringLiteral("speaker")).toString().simplified();
    if (!speaker.isEmpty()) {
      provider_speakers.insert(speaker);
    }
  }
  if (!provider_speakers.isEmpty()) {
    auto previous_speaker = provider_speakers.size() == 1
                                ? *provider_speakers.cbegin()
                                : QStringLiteral("Speaker 1");
    for (auto& value : words) {
      auto word = value.toMap();
      const auto speaker = word.value(QStringLiteral("speaker")).toString().simplified();
      if (!speaker.isEmpty()) {
        previous_speaker = speaker;
      } else {
        word.insert(QStringLiteral("speaker"), previous_speaker);
        value = word;
      }
    }
    return QVariantMap{
        {QStringLiteral("success"), true},
        {QStringLiteral("providerTagsPreserved"), true},
        {QStringLiteral("speakerCount"), provider_speakers.size()},
        {QStringLiteral("words"), words},
    };
  }

  const auto ffmpeg = QStandardPaths::findExecutable(QStringLiteral("ffmpeg"));
  if (ffmpeg.isEmpty() || words.isEmpty()) {
    return QVariantMap{
        {QStringLiteral("success"), false},
        {QStringLiteral("errorMessage"), QStringLiteral("Local speaker identification requires FFmpeg.")},
        {QStringLiteral("words"), words},
    };
  }

  struct Utterance final {
    QVector<int> word_indices;
    double start_seconds = 0.0;
    double end_seconds = 0.0;
    QVector<double> features;
    int cluster = 0;
  };
  QVector<Utterance> utterances;
  for (int index = 0; index < words.size(); ++index) {
    const auto word = words.at(index).toMap();
    const auto start = qMax(0.0, word.value(QStringLiteral("startSeconds")).toDouble());
    const auto end = qMax(
        start + 0.05,
        word.value(QStringLiteral("endSeconds"), start + 0.10).toDouble());
    if (utterances.isEmpty() || start - utterances.last().end_seconds > 0.55 ||
        end - utterances.last().start_seconds > 8.0 ||
        utterances.last().word_indices.size() >= 20) {
      utterances.push_back(Utterance{{index}, start, end, {}, 0});
    } else {
      utterances.last().word_indices.push_back(index);
      utterances.last().end_seconds = end;
    }
  }

  constexpr int kSampleRate = 8000;
  constexpr double kChunkSeconds = 300.0;
  const auto feature_for_window = [](const QByteArray& pcm,
                                     int first_sample,
                                     int last_sample) {
    QVector<double> result;
    const auto sample_count = static_cast<int>(qMin<qsizetype>(
        pcm.size() / static_cast<int>(sizeof(qint16)),
        std::numeric_limits<int>::max()));
    first_sample = qBound(0, first_sample, sample_count);
    last_sample = qBound(first_sample, last_sample, sample_count);
    const auto count = last_sample - first_sample;
    if (count < 320) {
      return result;
    }
    QVector<double> samples;
    samples.reserve(count);
    auto mean = 0.0;
    for (int index = first_sample; index < last_sample; ++index) {
      const auto value = qFromLittleEndian<qint16>(
          reinterpret_cast<const uchar*>(pcm.constData() + index * 2));
      mean += static_cast<double>(value) / 32768.0;
    }
    mean /= static_cast<double>(count);
    auto energy = 0.0;
    auto zero_crossings = 0;
    auto previous = 0.0;
    for (int index = first_sample; index < last_sample; ++index) {
      const auto value = qFromLittleEndian<qint16>(
          reinterpret_cast<const uchar*>(pcm.constData() + index * 2));
      const auto sample = static_cast<double>(value) / 32768.0 - mean;
      samples.push_back(sample);
      energy += sample * sample;
      if (!samples.isEmpty() && ((sample >= 0.0) != (previous >= 0.0))) {
        ++zero_crossings;
      }
      previous = sample;
    }
    const auto rms = std::sqrt(energy / static_cast<double>(count));
    if (rms < 0.0005) {
      return result;
    }

    auto best_pitch_correlation = 0.0;
    auto best_pitch_hz = 0.0;
    for (int lag = 23; lag <= 114; ++lag) {
      auto numerator = 0.0;
      auto left_energy = 0.0;
      auto right_energy = 0.0;
      for (int index = lag; index < samples.size(); index += 2) {
        const auto left = samples.at(index);
        const auto right = samples.at(index - lag);
        numerator += left * right;
        left_energy += left * left;
        right_energy += right * right;
      }
      const auto correlation = numerator /
          std::sqrt(qMax(1.0e-12, left_energy * right_energy));
      if (correlation > best_pitch_correlation) {
        best_pitch_correlation = correlation;
        best_pitch_hz = static_cast<double>(kSampleRate) / static_cast<double>(lag);
      }
    }

    result.push_back(std::log(rms + 1.0e-9));
    result.push_back(static_cast<double>(zero_crossings) / static_cast<double>(count));
    result.push_back(std::log(qMax(60.0, best_pitch_hz)));
    result.push_back(best_pitch_correlation);
    const QVector<double> band_centers{120.0, 250.0, 500.0, 1000.0, 2000.0, 3200.0};
    for (const auto frequency : band_centers) {
      const auto omega = 2.0 * std::numbers::pi * frequency /
                         static_cast<double>(kSampleRate);
      const auto coefficient = 2.0 * std::cos(omega);
      auto previous_one = 0.0;
      auto previous_two = 0.0;
      for (const auto sample : samples) {
        const auto current = sample + coefficient * previous_one - previous_two;
        previous_two = previous_one;
        previous_one = current;
      }
      const auto power = qMax(
          1.0e-12,
          previous_one * previous_one + previous_two * previous_two -
              coefficient * previous_one * previous_two);
      result.push_back(std::log(power / qMax(1.0e-12, energy) + 1.0e-12));
    }
    return result;
  };

  auto utterance_index = 0;
  while (utterance_index < utterances.size()) {
    if (cancel_token && cancel_token->load()) {
      return {{QStringLiteral("cancelled"), true}};
    }
    const auto chunk_start = qMax(0.0, utterances.at(utterance_index).start_seconds - 0.10);
    auto chunk_end = chunk_start + kChunkSeconds;
    auto end_index = utterance_index;
    while (end_index + 1 < utterances.size() &&
           utterances.at(end_index + 1).start_seconds < chunk_end - 0.10) {
      ++end_index;
    }
    chunk_end = qMax(chunk_end, utterances.at(end_index).end_seconds + 0.10);
    QProcess process;
    process.start(
        ffmpeg,
        {QStringLiteral("-v"), QStringLiteral("error"),
         QStringLiteral("-ss"), QString::number(chunk_start, 'f', 6),
         QStringLiteral("-i"), source_path,
         QStringLiteral("-t"), QString::number(chunk_end - chunk_start, 'f', 6),
         QStringLiteral("-vn"), QStringLiteral("-ac"), QStringLiteral("1"),
         QStringLiteral("-ar"), QString::number(kSampleRate),
         QStringLiteral("-f"), QStringLiteral("s16le"), QStringLiteral("pipe:1")});
    if (!cancellable_process_succeeded(&process, [cancel_token]() { return cancel_token && cancel_token->load(); })) {
      return QVariantMap{
          {QStringLiteral("cancelled"), cancel_token && cancel_token->load()},
          {QStringLiteral("success"), false},
          {QStringLiteral("errorMessage"), QStringLiteral("Unable to decode bounded PCM for local speaker identification.")},
          {QStringLiteral("words"), words},
      };
    }
    const auto pcm = process.readAllStandardOutput();
    for (int index = utterance_index; index <= end_index; ++index) {
      const auto first_sample = static_cast<int>(std::floor(
          qMax(0.0, utterances.at(index).start_seconds - 0.05 - chunk_start) * kSampleRate));
      const auto last_sample = static_cast<int>(std::ceil(
          qMax(0.0, utterances.at(index).end_seconds + 0.05 - chunk_start) * kSampleRate));
      utterances[index].features = feature_for_window(pcm, first_sample, last_sample);
    }
    utterance_index = end_index + 1;
  }

  QVector<int> valid_indices;
  for (int index = 0; index < utterances.size(); ++index) {
    if (!utterances.at(index).features.isEmpty()) {
      valid_indices.push_back(index);
    }
  }
  if (valid_indices.size() < 4) {
    for (auto& word_value : words) {
      auto word = word_value.toMap();
      word.insert(QStringLiteral("speaker"), QStringLiteral("Speaker 1"));
      word_value = word;
    }
    return QVariantMap{
        {QStringLiteral("success"), true},
        {QStringLiteral("speakerCount"), 1},
        {QStringLiteral("words"), words},
    };
  }

  const auto feature_count = utterances.at(valid_indices.first()).features.size();
  QVector<double> means(feature_count, 0.0);
  QVector<double> deviations(feature_count, 0.0);
  for (const auto index : valid_indices) {
    for (int feature = 0; feature < feature_count; ++feature) {
      means[feature] += utterances.at(index).features.at(feature);
    }
  }
  for (auto& mean : means) {
    mean /= static_cast<double>(valid_indices.size());
  }
  for (const auto index : valid_indices) {
    for (int feature = 0; feature < feature_count; ++feature) {
      const auto delta = utterances.at(index).features.at(feature) - means.at(feature);
      deviations[feature] += delta * delta;
    }
  }
  for (auto& deviation : deviations) {
    deviation = std::sqrt(deviation / static_cast<double>(valid_indices.size()));
    deviation = qMax(1.0e-6, deviation);
  }
  QVector<QVector<double>> points;
  points.reserve(valid_indices.size());
  for (const auto index : valid_indices) {
    QVector<double> point;
    point.reserve(feature_count);
    for (int feature = 0; feature < feature_count; ++feature) {
      point.push_back(
          (utterances.at(index).features.at(feature) - means.at(feature)) /
          deviations.at(feature));
    }
    points.push_back(point);
  }
  const auto distance_squared = [](const QVector<double>& left, const QVector<double>& right) {
    auto distance = 0.0;
    for (int feature = 0; feature < left.size(); ++feature) {
      const auto delta = left.at(feature) - right.at(feature);
      distance += delta * delta;
    }
    return distance;
  };
  struct ClusterResult final {
    QVector<int> labels;
    QVector<int> counts;
    double silhouette = -1.0;
    bool valid = false;
  };
  const auto fit_clusters = [&points, &distance_squared](int cluster_count) {
    ClusterResult result;
    QVector<QVector<double>> centers;
    centers.push_back(points.first());
    while (centers.size() < cluster_count) {
      auto farthest_index = -1;
      auto farthest_distance = -1.0;
      for (int index = 0; index < points.size(); ++index) {
        auto nearest = std::numeric_limits<double>::max();
        for (const auto& center : centers) {
          nearest = qMin(nearest, distance_squared(points.at(index), center));
        }
        if (nearest > farthest_distance + 1.0e-9) {
          farthest_distance = nearest;
          farthest_index = index;
        }
      }
      if (farthest_index < 0 || farthest_distance <= 1.0e-9) {
        return result;
      }
      centers.push_back(points.at(farthest_index));
    }
    result.labels.fill(0, points.size());
    for (auto iteration = 0; iteration < 24; ++iteration) {
      auto changed = false;
      result.counts.fill(0, cluster_count);
      QVector<QVector<double>> sums(
          cluster_count, QVector<double>(points.first().size(), 0.0));
      for (int index = 0; index < points.size(); ++index) {
        auto best_cluster = 0;
        auto best_distance = std::numeric_limits<double>::max();
        for (int cluster = 0; cluster < cluster_count; ++cluster) {
          const auto distance = distance_squared(points.at(index), centers.at(cluster));
          if (distance < best_distance) {
            best_distance = distance;
            best_cluster = cluster;
          }
        }
        changed = changed || result.labels.at(index) != best_cluster;
        result.labels[index] = best_cluster;
        ++result.counts[best_cluster];
        for (int feature = 0; feature < points.at(index).size(); ++feature) {
          sums[best_cluster][feature] += points.at(index).at(feature);
        }
      }
      if (std::any_of(result.counts.cbegin(), result.counts.cend(),
                      [](int count) { return count < 2; })) {
        return ClusterResult{};
      }
      for (int cluster = 0; cluster < cluster_count; ++cluster) {
        for (int feature = 0; feature < centers.at(cluster).size(); ++feature) {
          centers[cluster][feature] = sums.at(cluster).at(feature) /
                                      static_cast<double>(result.counts.at(cluster));
        }
      }
      if (!changed && iteration > 0) {
        break;
      }
    }
    auto silhouette_sum = 0.0;
    for (int index = 0; index < points.size(); ++index) {
      QVector<double> distance_sums(cluster_count, 0.0);
      QVector<int> distance_counts(cluster_count, 0);
      for (int other = 0; other < points.size(); ++other) {
        if (other == index) {
          continue;
        }
        const auto cluster = result.labels.at(other);
        distance_sums[cluster] += std::sqrt(distance_squared(points.at(index), points.at(other)));
        ++distance_counts[cluster];
      }
      const auto own_cluster = result.labels.at(index);
      const auto within = distance_sums.at(own_cluster) /
                          qMax(1, distance_counts.at(own_cluster));
      auto nearest_other = std::numeric_limits<double>::max();
      for (int cluster = 0; cluster < cluster_count; ++cluster) {
        if (cluster == own_cluster || distance_counts.at(cluster) == 0) {
          continue;
        }
        nearest_other = qMin(
            nearest_other,
            distance_sums.at(cluster) / static_cast<double>(distance_counts.at(cluster)));
      }
      silhouette_sum += (nearest_other - within) / qMax(nearest_other, within);
    }
    result.silhouette = silhouette_sum / static_cast<double>(points.size());
    result.valid = true;
    return result;
  };

  auto selected_count = 1;
  ClusterResult selected;
  const auto maximum_clusters = qMin(4, valid_indices.size() / 2);
  for (auto count = 2; count <= maximum_clusters; ++count) {
    const auto candidate = fit_clusters(count);
    // Short, codec-compressed utterances rarely reach textbook clustering
    // scores. Requiring two utterances per identity plus a positive 0.20
    // silhouette rejects singleton/outlier speakers while retaining repeated
    // acoustic identities in short social-video interviews.
    if (!candidate.valid || candidate.silhouette < 0.20) {
      continue;
    }
    if (selected_count == 1 || candidate.silhouette > selected.silhouette + 0.05) {
      selected_count = count;
      selected = candidate;
    }
  }
  if (selected_count > 1) {
    QHash<int, int> stable_labels;
    auto next_label = 0;
    for (int point_index = 0; point_index < valid_indices.size(); ++point_index) {
      const auto raw_label = selected.labels.at(point_index);
      if (!stable_labels.contains(raw_label)) {
        stable_labels.insert(raw_label, next_label++);
      }
      utterances[valid_indices.at(point_index)].cluster = stable_labels.value(raw_label);
    }
  }
  auto previous_cluster = 0;
  for (auto& utterance : utterances) {
    if (utterance.features.isEmpty()) {
      utterance.cluster = previous_cluster;
    } else {
      previous_cluster = utterance.cluster;
    }
    const auto speaker = QStringLiteral("Speaker %1").arg(utterance.cluster + 1);
    for (const auto word_index : utterance.word_indices) {
      auto word = words.at(word_index).toMap();
      word.insert(QStringLiteral("speaker"), speaker);
      words[word_index] = word;
    }
  }
  return QVariantMap{
      {QStringLiteral("success"), true},
      {QStringLiteral("speakerCount"), selected_count},
      {QStringLiteral("words"), words},
  };
}

struct AutoReframeSubjectBounds final {
  double center_x = 0.5;
  double center_y = 0.5;
  double width = 0.0;
  double height = 0.0;
  double confidence = 0.0;
  bool valid = false;
};

AutoReframeSubjectBounds subject_bounds_from_mask(const SegmentationResult& mask) {
  AutoReframeSubjectBounds bounds;
  if (!mask.success || mask.width <= 0 || mask.height <= 0 ||
      mask.mask_data.size() < mask.width * mask.height) {
    return bounds;
  }
  auto minimum_x = mask.width;
  auto minimum_y = mask.height;
  auto maximum_x = -1;
  auto maximum_y = -1;
  auto weighted_x = 0.0;
  auto weighted_y = 0.0;
  auto total_weight = 0.0;
  for (auto y = 0; y < mask.height; ++y) {
    for (auto x = 0; x < mask.width; ++x) {
      const auto alpha = static_cast<unsigned char>(mask.mask_data.at(y * mask.width + x));
      if (alpha < 48) {
        continue;
      }
      const auto weight = static_cast<double>(alpha) / 255.0;
      minimum_x = qMin(minimum_x, x);
      minimum_y = qMin(minimum_y, y);
      maximum_x = qMax(maximum_x, x);
      maximum_y = qMax(maximum_y, y);
      weighted_x += (static_cast<double>(x) + 0.5) * weight;
      weighted_y += (static_cast<double>(y) + 0.5) * weight;
      total_weight += weight;
    }
  }
  if (maximum_x < minimum_x || maximum_y < minimum_y || total_weight <= 0.0) {
    return bounds;
  }
  bounds.center_x = qBound(0.0, weighted_x / total_weight / mask.width, 1.0);
  bounds.center_y = qBound(0.0, weighted_y / total_weight / mask.height, 1.0);
  bounds.width = qBound(
      0.01, static_cast<double>(maximum_x - minimum_x + 1) / mask.width, 1.0);
  bounds.height = qBound(
      0.01, static_cast<double>(maximum_y - minimum_y + 1) / mask.height, 1.0);
  const auto coverage = total_weight / static_cast<double>(mask.width * mask.height);
  bounds.confidence = qBound(0.15, 0.45 + qMin(0.5, coverage * 2.0), 0.95);
  bounds.valid = true;
  return bounds;
}

AutoReframeSubjectBounds luminance_subject_bounds(const QImage& source) {
  AutoReframeSubjectBounds bounds;
  if (source.isNull() || source.width() < 8 || source.height() < 8) {
    return bounds;
  }
  const auto image = source.convertToFormat(QImage::Format_RGB32);
  auto border_red = 0.0;
  auto border_green = 0.0;
  auto border_blue = 0.0;
  auto border_count = 0.0;
  for (auto x = 0; x < image.width(); x += qMax(1, image.width() / 64)) {
    for (const auto y : {0, image.height() - 1}) {
      const auto pixel = image.pixel(x, y);
      border_red += qRed(pixel);
      border_green += qGreen(pixel);
      border_blue += qBlue(pixel);
      border_count += 1.0;
    }
  }
  for (auto y = 0; y < image.height(); y += qMax(1, image.height() / 64)) {
    for (const auto x : {0, image.width() - 1}) {
      const auto pixel = image.pixel(x, y);
      border_red += qRed(pixel);
      border_green += qGreen(pixel);
      border_blue += qBlue(pixel);
      border_count += 1.0;
    }
  }
  if (border_count <= 0.0) {
    return bounds;
  }
  border_red /= border_count;
  border_green /= border_count;
  border_blue /= border_count;
  auto minimum_x = image.width();
  auto minimum_y = image.height();
  auto maximum_x = -1;
  auto maximum_y = -1;
  auto weighted_x = 0.0;
  auto weighted_y = 0.0;
  auto total_weight = 0.0;
  for (auto y = 0; y < image.height(); ++y) {
    const auto* row = reinterpret_cast<const QRgb*>(image.constScanLine(y));
    for (auto x = 0; x < image.width(); ++x) {
      const auto pixel = row[x];
      const auto red_delta = static_cast<double>(qRed(pixel)) - border_red;
      const auto green_delta = static_cast<double>(qGreen(pixel)) - border_green;
      const auto blue_delta = static_cast<double>(qBlue(pixel)) - border_blue;
      const auto distance = std::sqrt(
          red_delta * red_delta + green_delta * green_delta + blue_delta * blue_delta);
      if (distance < 64.0) {
        continue;
      }
      const auto weight = qMin(1.0, (distance - 48.0) / 160.0);
      minimum_x = qMin(minimum_x, x);
      minimum_y = qMin(minimum_y, y);
      maximum_x = qMax(maximum_x, x);
      maximum_y = qMax(maximum_y, y);
      weighted_x += (static_cast<double>(x) + 0.5) * weight;
      weighted_y += (static_cast<double>(y) + 0.5) * weight;
      total_weight += weight;
    }
  }
  if (maximum_x < minimum_x || maximum_y < minimum_y || total_weight <= 4.0) {
    return bounds;
  }
  bounds.center_x = weighted_x / total_weight / image.width();
  bounds.center_y = weighted_y / total_weight / image.height();
  bounds.width = static_cast<double>(maximum_x - minimum_x + 1) / image.width();
  bounds.height = static_cast<double>(maximum_y - minimum_y + 1) / image.height();
  bounds.confidence = qBound(
      0.2, 0.35 + total_weight / static_cast<double>(image.width() * image.height()), 0.8);
  bounds.valid = true;
  return bounds;
}

QImage decode_auto_reframe_frame(
    const QString& ffmpeg,
    const QString& file_path,
    double source_seconds,
    const std::shared_ptr<std::atomic_bool>& cancel_token) {
  if (cancel_token && cancel_token->load()) {
    return {};
  }
  QProcess process;
  process.start(
      ffmpeg,
      {QStringLiteral("-v"), QStringLiteral("error"),
       QStringLiteral("-ss"), QString::number(qMax(0.0, source_seconds), 'f', 6),
       QStringLiteral("-i"), file_path,
       QStringLiteral("-frames:v"), QStringLiteral("1"),
       QStringLiteral("-vf"),
       QStringLiteral("scale='min(640,iw)':-2:flags=lanczos"),
       QStringLiteral("-f"), QStringLiteral("image2pipe"),
       QStringLiteral("-vcodec"), QStringLiteral("png"), QStringLiteral("pipe:1")});
  if (!bounded_process_succeeded(&process, 15000) ||
      (cancel_token && cancel_token->load())) {
    return {};
  }
  return QImage::fromData(process.readAllStandardOutput(), "PNG");
}

QImage decode_color_scope_frame(
    const QString& ffmpeg,
    const QString& file_path,
    double source_seconds,
    QString filters) {
  QProcess process;
  if (filters.endsWith(QLatin1Char(','))) {
    filters.chop(1);
  }
  if (!filters.isEmpty()) {
    filters += QLatin1Char(',');
  }
  filters += QStringLiteral("scale='min(640,iw)':-2:flags=lanczos");
  process.start(
      ffmpeg,
      {QStringLiteral("-v"), QStringLiteral("error"),
       QStringLiteral("-ss"), QString::number(qMax(0.0, source_seconds), 'f', 6),
       QStringLiteral("-i"), file_path,
       QStringLiteral("-frames:v"), QStringLiteral("1"),
       QStringLiteral("-vf"), filters,
       QStringLiteral("-f"), QStringLiteral("image2pipe"),
       QStringLiteral("-vcodec"), QStringLiteral("png"), QStringLiteral("pipe:1")});
  if (!bounded_process_succeeded(&process, 15000)) {
    return {};
  }
  return QImage::fromData(process.readAllStandardOutput(), "PNG");
}

QString escaped_ffmpeg_filter_path(const QString& source_path) {
  auto escaped = QDir::toNativeSeparators(source_path);
  escaped.replace(QLatin1Char('\\'), QStringLiteral("\\\\"));
  escaped.replace(QLatin1Char(':'), QStringLiteral("\\:"));
  escaped.replace(QLatin1Char('\''), QStringLiteral("\\'"));
  escaped.replace(QLatin1Char(','), QStringLiteral("\\,"));
  return escaped;
}

QVector<double> image_channel_means(const QImage& source) {
  if (source.isNull()) {
    return {};
  }
  const auto image = source.convertToFormat(QImage::Format_RGB32);
  double red = 0.0;
  double green = 0.0;
  double blue = 0.0;
  qint64 count = 0;
  const auto x_step = qMax(1, image.width() / 320);
  const auto y_step = qMax(1, image.height() / 180);
  for (auto y = 0; y < image.height(); y += y_step) {
    const auto* row = reinterpret_cast<const QRgb*>(image.constScanLine(y));
    for (auto x = 0; x < image.width(); x += x_step) {
      red += qRed(row[x]) / 255.0;
      green += qGreen(row[x]) / 255.0;
      blue += qBlue(row[x]) / 255.0;
      ++count;
    }
  }
  if (count <= 0) {
    return {};
  }
  return {red / count, green / count, blue / count};
}

QVariantMap image_color_scopes(const QImage& source) {
  if (source.isNull()) {
    return {};
  }
  constexpr auto bin_count = 64;
  QVector<int> red(bin_count);
  QVector<int> green(bin_count);
  QVector<int> blue(bin_count);
  QVector<int> luma(bin_count);
  QVector<int> luma_waveform(bin_count * bin_count);
  QVector<int> vectorscope(bin_count * bin_count);
  const auto image = source.convertToFormat(QImage::Format_RGB32);
  const auto x_step = qMax(1, image.width() / 640);
  const auto y_step = qMax(1, image.height() / 360);
  auto sample_count = 0;
  for (auto y = 0; y < image.height(); y += y_step) {
    const auto* row = reinterpret_cast<const QRgb*>(image.constScanLine(y));
    for (auto x = 0; x < image.width(); x += x_step) {
      const auto pixel = row[x];
      const auto red_value = qRed(pixel);
      const auto green_value = qGreen(pixel);
      const auto blue_value = qBlue(pixel);
      ++red[qMin(bin_count - 1, red_value * bin_count / 256)];
      ++green[qMin(bin_count - 1, green_value * bin_count / 256)];
      ++blue[qMin(bin_count - 1, blue_value * bin_count / 256)];
      const auto luma_value = qBound(
          0, qRound(0.2126 * red_value + 0.7152 * green_value + 0.0722 * blue_value), 255);
      ++luma[qMin(bin_count - 1, luma_value * bin_count / 256)];
      const auto waveform_x = qMin(bin_count - 1, x * bin_count / qMax(1, image.width()));
      const auto waveform_y = qMin(bin_count - 1, luma_value * bin_count / 256);
      ++luma_waveform[waveform_y * bin_count + waveform_x];
      const auto cb = qBound(
          0.0, 0.5 + (-0.1146 * red_value - 0.3854 * green_value + 0.5 * blue_value) / 255.0,
          1.0);
      const auto cr = qBound(
          0.0, 0.5 + (0.5 * red_value - 0.4542 * green_value - 0.0458 * blue_value) / 255.0,
          1.0);
      const auto vector_x = qMin(bin_count - 1, qRound(cb * (bin_count - 1)));
      const auto vector_y = qMin(bin_count - 1, qRound(cr * (bin_count - 1)));
      ++vectorscope[vector_y * bin_count + vector_x];
      ++sample_count;
    }
  }
  const auto variant_bins = [](const QVector<int>& bins) {
    QVariantList values;
    values.reserve(bins.size());
    const auto maximum = *std::max_element(bins.cbegin(), bins.cend());
    for (const auto value : bins) {
      values.push_back(maximum > 0 ? static_cast<double>(value) / maximum : 0.0);
    }
    return values;
  };
  const auto means = image_channel_means(image);
  return {
      {QStringLiteral("red"), variant_bins(red)},
      {QStringLiteral("green"), variant_bins(green)},
      {QStringLiteral("blue"), variant_bins(blue)},
      {QStringLiteral("luma"), variant_bins(luma)},
      {QStringLiteral("lumaWaveform"), variant_bins(luma_waveform)},
      {QStringLiteral("vectorscope"), variant_bins(vectorscope)},
      {QStringLiteral("scopeResolution"), bin_count},
      {QStringLiteral("sampleCount"), sample_count},
      {QStringLiteral("averageRed"), means.value(0)},
      {QStringLiteral("averageGreen"), means.value(1)},
      {QStringLiteral("averageBlue"), means.value(2)},
  };
}

QStringList audio_tempo_filters(double playback_rate) {
  QStringList filters;
  auto remaining = qBound(0.25, playback_rate, 4.0);
  while (remaining > 2.0 + kBoundaryEpsilon) {
    filters.push_back(QStringLiteral("atempo=2.0"));
    remaining /= 2.0;
  }
  while (remaining < 0.5 - kBoundaryEpsilon) {
    filters.push_back(QStringLiteral("atempo=0.5"));
    remaining /= 0.5;
  }
  if (qAbs(remaining - 1.0) > kBoundaryEpsilon) {
    filters.push_back(
        QStringLiteral("atempo=%1").arg(QString::number(remaining, 'f', 6)));
  }
  return filters;
}

QString normalized_audio_bus(const QString& value) {
  const auto normalized = value.trimmed().toLower();
  return normalized == QStringLiteral("dialogue") ||
                 normalized == QStringLiteral("music") ||
                 normalized == QStringLiteral("sfx")
             ? normalized
             : QStringLiteral("main");
}

QString normalized_audio_role(const QString& value) {
  const auto normalized = value.trimmed().toLower();
  return normalized == QStringLiteral("music") ||
                 normalized == QStringLiteral("ambience") ||
                 normalized == QStringLiteral("effects") ||
                 normalized == QStringLiteral("voiceover") ||
                 normalized == QStringLiteral("commentary")
             ? normalized
             : QStringLiteral("dialogue");
}

QString default_bus_for_audio_role(const QString& role) {
  const auto normalized = normalized_audio_role(role);
  if (normalized == QStringLiteral("music")) {
    return QStringLiteral("music");
  }
  if (normalized == QStringLiteral("ambience") ||
      normalized == QStringLiteral("effects")) {
    return QStringLiteral("sfx");
  }
  return QStringLiteral("dialogue");
}

bool is_audio_processor_automation_parameter(const QString& parameter) {
  return parameter == QStringLiteral("audioEqLowDb") ||
         parameter == QStringLiteral("audioEqMidDb") ||
         parameter == QStringLiteral("audioEqHighDb") ||
         parameter == QStringLiteral("audioCompressorThresholdDb") ||
         parameter == QStringLiteral("audioCompressorRatio") ||
         parameter == QStringLiteral("audioCompressorMakeupDb") ||
         parameter == QStringLiteral("audioLimiterCeilingDb") ||
         parameter == QStringLiteral("audioGateThresholdDb") ||
         parameter == QStringLiteral("audioDeEsserAmount") ||
         parameter == QStringLiteral("audioHighPassHz") ||
         parameter == QStringLiteral("audioLowPassHz");
}

bool is_audio_track_automation_parameter(const QString& parameter) {
  return parameter == QStringLiteral("audioGainDb") ||
         parameter == QStringLiteral("audioPan") ||
         is_audio_processor_automation_parameter(parameter);
}

double bounded_track_automation_value(const QString& parameter, double value) {
  if (parameter == QStringLiteral("opacity")) {
    return qBound(0.0, value, 1.0);
  }
  if (parameter == QStringLiteral("audioPan")) {
    return qBound(-1.0, value, 1.0);
  }
  if (parameter == QStringLiteral("audioEqLowDb") ||
      parameter == QStringLiteral("audioEqMidDb") ||
      parameter == QStringLiteral("audioEqHighDb")) {
    return qBound(-12.0, value, 12.0);
  }
  if (parameter == QStringLiteral("audioCompressorThresholdDb")) {
    return qBound(-48.0, value, -1.0);
  }
  if (parameter == QStringLiteral("audioCompressorRatio")) {
    return qBound(1.0, value, 20.0);
  }
  if (parameter == QStringLiteral("audioCompressorMakeupDb")) {
    return qBound(0.0, value, 18.0);
  }
  if (parameter == QStringLiteral("audioLimiterCeilingDb")) {
    return qBound(-12.0, value, 0.0);
  }
  if (parameter == QStringLiteral("audioGateThresholdDb")) {
    return qBound(-80.0, value, -10.0);
  }
  if (parameter == QStringLiteral("audioDeEsserAmount")) {
    return qBound(0.0, value, 1.0);
  }
  if (parameter == QStringLiteral("audioHighPassHz")) {
    return qBound(20.0, value, 1000.0);
  }
  if (parameter == QStringLiteral("audioLowPassHz")) {
    return qBound(1000.0, value, 20000.0);
  }
  return qBound(-36.0, value, 0.0);
}

std::optional<double> parsed_timecode_seconds(const QString& value, double frames_per_second) {
  const QRegularExpression expression(
      QStringLiteral("^(\\d{1,2}):(\\d{2}):(\\d{2})[:;](\\d{2})$"));
  const auto match = expression.match(value.trimmed());
  if (!match.hasMatch() || frames_per_second <= 0.0) {
    return std::nullopt;
  }
  const auto hours = match.captured(1).toInt();
  const auto minutes = match.captured(2).toInt();
  const auto seconds = match.captured(3).toInt();
  const auto frames = match.captured(4).toInt();
  if (minutes >= 60 || seconds >= 60 || frames >= qCeil(frames_per_second)) {
    return std::nullopt;
  }
  return hours * 3600.0 + minutes * 60.0 + seconds +
         frames / frames_per_second;
}

std::optional<double> parsed_editor_timecode_seconds(
    const QString& value,
    double frames_per_second) {
  const auto normalized = value.trimmed();
  if (const auto full = parsed_timecode_seconds(normalized, frames_per_second);
      full.has_value()) {
    return full;
  }

  const QRegularExpression shortened(
      QStringLiteral("^(\\d{1,2}):(\\d{2})[:;](\\d{2})$"));
  const auto shortened_match = shortened.match(normalized);
  if (shortened_match.hasMatch() && frames_per_second > 0.0) {
    const auto minutes = shortened_match.captured(1).toInt();
    const auto seconds = shortened_match.captured(2).toInt();
    const auto frames = shortened_match.captured(3).toInt();
    if (seconds < 60 && frames < qCeil(frames_per_second)) {
      return minutes * 60.0 + seconds + frames / frames_per_second;
    }
  }

  bool seconds_ok = false;
  const auto seconds = normalized.toDouble(&seconds_ok);
  return seconds_ok && seconds >= 0.0
             ? std::optional<double>(seconds)
             : std::nullopt;
}

std::optional<double> probe_source_timecode_seconds(
    const QString& file_path,
    double frames_per_second) {
  const auto ffprobe = QStandardPaths::findExecutable(QStringLiteral("ffprobe"));
  if (ffprobe.isEmpty() || !QFileInfo::exists(file_path)) {
    return std::nullopt;
  }
  QProcess process;
  process.start(
      ffprobe,
      {
          QStringLiteral("-v"), QStringLiteral("error"),
          QStringLiteral("-show_entries"),
          QStringLiteral("format_tags=timecode,time_reference:stream=sample_rate:stream_tags=timecode"),
          QStringLiteral("-of"), QStringLiteral("json"),
          file_path,
      });
  if (!bounded_process_succeeded(&process, 5000)) {
    return std::nullopt;
  }
  const auto object = QJsonDocument::fromJson(process.readAllStandardOutput()).object();
  for (const auto& value : object.value(QStringLiteral("streams")).toArray()) {
    const auto timecode = value.toObject()
                              .value(QStringLiteral("tags"))
                              .toObject()
                              .value(QStringLiteral("timecode"))
                              .toString();
    if (const auto parsed = parsed_timecode_seconds(timecode, frames_per_second);
        parsed.has_value()) {
      return parsed;
    }
  }
  if (const auto conventional = parsed_timecode_seconds(
      object.value(QStringLiteral("format"))
          .toObject()
          .value(QStringLiteral("tags"))
          .toObject()
          .value(QStringLiteral("timecode"))
          .toString(),
      frames_per_second); conventional.has_value()) {
    return conventional;
  }

  // Broadcast Wave stores its source timecode as an absolute sample count in
  // the BEXT time_reference tag. Resolve it against the audio stream's sample
  // rate so audio-only production recordings can align without a video stream.
  const auto format_tags = object.value(QStringLiteral("format"))
                               .toObject()
                               .value(QStringLiteral("tags"))
                               .toObject();
  bool sample_count_ok = false;
  const auto sample_count = format_tags.value(QStringLiteral("time_reference"))
                                .toString()
                                .toLongLong(&sample_count_ok);
  for (const auto& value : object.value(QStringLiteral("streams")).toArray()) {
    bool sample_rate_ok = false;
    const auto sample_rate = value.toObject()
                                 .value(QStringLiteral("sample_rate"))
                                 .toString()
                                 .toDouble(&sample_rate_ok);
    if (sample_count_ok && sample_count >= 0 && sample_rate_ok && sample_rate > 0.0) {
      return static_cast<double>(sample_count) / sample_rate;
    }
  }
  return std::nullopt;
}

std::optional<QVector<double>> decoded_audio_envelope(const QString& file_path) {
  const auto ffmpeg = QStandardPaths::findExecutable(QStringLiteral("ffmpeg"));
  if (ffmpeg.isEmpty() || !QFileInfo::exists(file_path)) {
    return std::nullopt;
  }
  QProcess process;
  process.start(
      ffmpeg,
      {
          QStringLiteral("-v"), QStringLiteral("error"),
          QStringLiteral("-i"), file_path,
          QStringLiteral("-vn"),
          QStringLiteral("-t"), QStringLiteral("60"),
          QStringLiteral("-ac"), QStringLiteral("1"),
          QStringLiteral("-ar"), QStringLiteral("8000"),
          QStringLiteral("-f"), QStringLiteral("f32le"),
          QStringLiteral("pipe:1"),
      });
  if (!bounded_process_succeeded(&process, 20000)) {
    return std::nullopt;
  }
  const auto bytes = process.readAllStandardOutput();
  constexpr auto kSamplesPerEnvelopePoint = 160;
  constexpr auto kBytesPerSample = static_cast<int>(sizeof(float));
  const auto sample_count = bytes.size() / kBytesPerSample;
  if (sample_count < kSamplesPerEnvelopePoint * 10) {
    return std::nullopt;
  }
  QVector<double> envelope;
  envelope.reserve(sample_count / kSamplesPerEnvelopePoint);
  for (auto start = 0; start + kSamplesPerEnvelopePoint <= sample_count;
       start += kSamplesPerEnvelopePoint) {
    auto energy = 0.0;
    for (auto offset = 0; offset < kSamplesPerEnvelopePoint; ++offset) {
      float sample = 0.0F;
      std::memcpy(
          &sample,
          bytes.constData() + (start + offset) * kBytesPerSample,
          sizeof(float));
      if (std::isfinite(sample)) {
        energy += qAbs(static_cast<double>(sample));
      }
    }
    envelope.push_back(energy / kSamplesPerEnvelopePoint);
  }
  const auto mean = std::accumulate(envelope.cbegin(), envelope.cend(), 0.0) /
                    static_cast<double>(envelope.size());
  for (auto& value : envelope) {
    value -= mean;
  }
  return envelope;
}

struct WaveformAlignment final {
  double lag_seconds = 0.0;
  double confidence = 0.0;
  double correlation = 0.0;
};

std::optional<WaveformAlignment> waveform_alignment(
    const QVector<double>& reference,
    const QVector<double>& candidate) {
  constexpr auto kEnvelopePointsPerSecond = 50;
  const auto maximum_lag = static_cast<int>(qMin<qsizetype>(
      30 * kEnvelopePointsPerSecond,
      qMax(reference.size(), candidate.size()) - 1));
  auto best_score = -1.0;
  auto second_best_score = -1.0;
  auto best_lag = 0;
  for (auto lag = -maximum_lag; lag <= maximum_lag; ++lag) {
    const auto reference_start = qMax(0, -lag);
    const auto candidate_start = qMax(0, lag);
    const auto overlap = qMin(
        reference.size() - reference_start,
        candidate.size() - candidate_start);
    if (overlap < kEnvelopePointsPerSecond) {
      continue;
    }
    auto cross = 0.0;
    auto reference_energy = 0.0;
    auto candidate_energy = 0.0;
    for (auto index = 0; index < overlap; ++index) {
      const auto left = reference.at(reference_start + index);
      const auto right = candidate.at(candidate_start + index);
      cross += left * right;
      reference_energy += left * left;
      candidate_energy += right * right;
    }
    const auto denominator = qSqrt(reference_energy * candidate_energy);
    const auto score = denominator > 1.0e-12 ? cross / denominator : -1.0;
    if (score > best_score) {
      second_best_score = best_score;
      best_score = score;
      best_lag = lag;
    } else if (score > second_best_score && qAbs(lag - best_lag) > 5) {
      second_best_score = score;
    }
  }
  if (best_score < 0.18) {
    return std::nullopt;
  }
  const auto separation = qMax(0.0, best_score - qMax(0.0, second_best_score));
  const auto strength = qBound(0.0, (best_score - 0.18) / 0.82, 1.0);
  const auto uniqueness = qBound(0.0, separation / 0.12, 1.0);
  return WaveformAlignment{
      static_cast<double>(best_lag) / kEnvelopePointsPerSecond,
      qBound(0.0, (strength * 0.72 + uniqueness * 0.28) * 100.0, 100.0),
      best_score,
  };
}

std::optional<double> waveform_alignment_lag_seconds(
    const QVector<double>& reference,
    const QVector<double>& candidate) {
  const auto alignment = waveform_alignment(reference, candidate);
  return alignment.has_value()
             ? std::optional<double>(alignment->lag_seconds)
             : std::nullopt;
}

QVector<double> detect_audio_beats(const QByteArray& pcm_bytes, int sample_rate) {
  constexpr int kBytesPerSample = static_cast<int>(sizeof(float));
  const auto sample_count = pcm_bytes.size() / kBytesPerSample;
  if (sample_rate <= 0 || sample_count < sample_rate / 2) {
    return {};
  }

  QVector<double> samples(sample_count);
  for (int index = 0; index < sample_count; ++index) {
    float value = 0.0F;
    std::memcpy(
        &value,
        pcm_bytes.constData() + index * kBytesPerSample,
        sizeof(float));
    samples[index] = std::isfinite(value) ? static_cast<double>(value) : 0.0;
  }

  const auto hop_size = qMax(1, sample_rate / 100);   // 10 ms
  const auto window_size = qMax(hop_size, sample_rate / 50);  // 20 ms
  const auto frame_count = qMax(0, (sample_count - window_size) / hop_size + 1);
  if (frame_count < 20) {
    return {};
  }
  QVector<double> energy(frame_count, 0.0);
  for (int frame = 0; frame < frame_count; ++frame) {
    const auto start = frame * hop_size;
    auto sum = 0.0;
    for (int offset = 0; offset < window_size; ++offset) {
      const auto value = samples.at(start + offset);
      sum += value * value;
    }
    energy[frame] = std::sqrt(sum / static_cast<double>(window_size));
  }

  QVector<double> onset(frame_count, 0.0);
  for (int frame = 1; frame < frame_count; ++frame) {
    const auto history_start = qMax(0, frame - 8);
    auto history_sum = 0.0;
    for (int history = history_start; history < frame; ++history) {
      history_sum += energy.at(history);
    }
    const auto history_count = qMax(1, frame - history_start);
    onset[frame] = qMax(
        0.0,
        energy.at(frame) - history_sum / static_cast<double>(history_count));
  }

  struct BeatCandidate final {
    int frame = 0;
    double strength = 0.0;
  };
  QVector<BeatCandidate> candidates;
  constexpr int kLocalPeakRadiusFrames = 4;
  constexpr int kThresholdRadiusFrames = 50;
  for (int frame = kLocalPeakRadiusFrames;
       frame < frame_count - kLocalPeakRadiusFrames;
       ++frame) {
    const auto local_start = qMax(0, frame - kThresholdRadiusFrames);
    const auto local_end = qMin(frame_count, frame + kThresholdRadiusFrames + 1);
    auto local_sum = 0.0;
    for (int local = local_start; local < local_end; ++local) {
      local_sum += onset.at(local);
    }
    const auto local_mean = local_sum / static_cast<double>(qMax(1, local_end - local_start));
    const auto strength = onset.at(frame);
    if (strength < qMax(0.004, local_mean * 2.4) || energy.at(frame) < 0.012) {
      continue;
    }
    auto local_maximum = true;
    for (int neighbour = frame - kLocalPeakRadiusFrames;
         neighbour <= frame + kLocalPeakRadiusFrames;
         ++neighbour) {
      if (onset.at(neighbour) > strength + 1.0e-9) {
        local_maximum = false;
        break;
      }
    }
    if (local_maximum) {
      candidates.push_back({frame, strength});
    }
  }

  constexpr int kMinimumBeatGapFrames = 22;  // 220 ms, up to roughly 270 BPM.
  QVector<BeatCandidate> accepted;
  for (const auto& candidate : candidates) {
    if (accepted.isEmpty() ||
        candidate.frame - accepted.last().frame >= kMinimumBeatGapFrames) {
      accepted.push_back(candidate);
      continue;
    }
    if (candidate.strength > accepted.last().strength) {
      accepted.last() = candidate;
    }
  }

  QVector<double> beat_seconds;
  beat_seconds.reserve(accepted.size());
  for (const auto& candidate : accepted) {
    beat_seconds.push_back(
        static_cast<double>(candidate.frame * hop_size) /
        static_cast<double>(sample_rate));
  }
  return beat_seconds;
}

