struct AudioWaveformCachePaths final {
  QString compact;
  QString standard;
  QString detail;
};

QString waveform_revision_seed(const QString& file_path, const QString& cache_key) {
  const QFileInfo source_info(file_path);
  const auto source_revision = QStringLiteral("%1:%2:%3")
                                   .arg(source_info.absoluteFilePath())
                                   .arg(source_info.size())
                                   .arg(source_info.lastModified().toMSecsSinceEpoch());
  return cache_key.isEmpty()
             ? QStringLiteral("timeline-waveform-v2:%1").arg(source_revision)
             : QStringLiteral("timeline-waveform-v2:%1:%2").arg(cache_key, source_revision);
}

AudioWaveformCachePaths audio_waveform_cache_paths(
    const QString& file_path,
    const QString& cache_key) {
  const auto digest = QCryptographicHash::hash(
                          waveform_revision_seed(file_path, cache_key).toUtf8(),
                          QCryptographicHash::Sha1)
                          .toHex();
  const auto stem = QDir(waveform_cache_root()).filePath(QString::fromLatin1(digest));
  return {
      stem + QStringLiteral("-compact.png"),
      stem + QStringLiteral("-standard.png"),
      stem + QStringLiteral("-detail.png"),
  };
}

bool waveform_cache_file_is_current(const QString& path) {
  const QFileInfo cache_info(path);
  return cache_info.exists() && cache_info.isReadable();
}

void prune_waveform_cache_files(const QSet<QString>& protected_paths) {
  QDir directory(waveform_cache_root());
  const auto files = directory.entryInfoList(
      {QStringLiteral("*.png")},
      QDir::Files | QDir::Readable,
      QDir::Time);
  auto total_bytes = 0LL;
  for (const auto& file : files) {
    total_bytes += file.size();
  }
  auto retained_files = files.size();
  for (auto index = files.size() - 1;
       index >= 0 &&
       (retained_files > kWaveformCacheMaximumFiles || total_bytes > kWaveformCacheMaximumBytes);
       --index) {
    const auto& file = files.at(index);
    if (protected_paths.contains(file.absoluteFilePath())) {
      continue;
    }
    const auto file_size = file.size();
    if (remove_artifact_and_integrity(file.absoluteFilePath())) {
      --retained_files;
      total_bytes -= file_size;
    }
  }
}

