int TimelineDocumentController::captionCount() const {
  auto count = 0;
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (clip.media_type == QStringLiteral("caption")) {
        ++count;
      }
    }
  }
  return count;
}

QVariantList TimelineDocumentController::transcriptSegments() const {
  const auto cache_key = QStringLiteral("%1:%2:%3")
                             .arg(timeline_id_)
                             .arg(document_edit_revision_)
                             .arg(transcript_analysis_revision_);
  if (cache_key == transcript_segments_cache_key_) {
    return transcript_segments_cache_;
  }
  struct TranscriptSegment final {
    const Clip* clip = nullptr;
  };
  QVector<TranscriptSegment> segments;
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (clip.media_type == QStringLiteral("caption") && !clip.title_text.simplified().isEmpty()) {
        segments.push_back({&clip});
      }
    }
  }
  std::sort(segments.begin(), segments.end(), [](const auto& left, const auto& right) {
    return left.clip->start_seconds < right.clip->start_seconds;
  });

  QVariantList values;
  values.reserve(segments.size());
  for (int segment_index = 0; segment_index < segments.size(); ++segment_index) {
    const auto& clip = *segments.at(segment_index).clip;
    QVariantList words;
    words.reserve(clip.caption_words.size());
    for (int word_index = 0; word_index < clip.caption_words.size(); ++word_index) {
      const auto& word = clip.caption_words.at(word_index);
      QVariantMap word_value;
      word_value.insert(QStringLiteral("index"), word_index);
      word_value.insert(QStringLiteral("text"), word.text);
      word_value.insert(QStringLiteral("startSeconds"), clip.start_seconds + word.start_seconds);
      word_value.insert(QStringLiteral("endSeconds"), clip.start_seconds + word.end_seconds);
      word_value.insert(QStringLiteral("speaker"), word.speaker);
      word_value.insert(QStringLiteral("confidence"), word.confidence);
      words.push_back(word_value);
    }
    QVariantMap segment;
    segment.insert(QStringLiteral("segmentId"), clip.clip_id);
    segment.insert(QStringLiteral("index"), segment_index);
    segment.insert(QStringLiteral("text"), clip.title_text.simplified());
    segment.insert(QStringLiteral("startSeconds"), clip.start_seconds);
    segment.insert(QStringLiteral("endSeconds"), clipEndSeconds(clip));
    segment.insert(QStringLiteral("startTimecode"), formatDurationText(clip.start_seconds));
    segment.insert(QStringLiteral("endTimecode"), formatDurationText(clipEndSeconds(clip)));
    segment.insert(QStringLiteral("wordCount"), clip.caption_words.size());
    QStringList speakers;
    auto confidence_sum = 0.0;
    for (const auto& word : clip.caption_words) {
      if (!word.speaker.isEmpty() && !speakers.contains(word.speaker)) {
        speakers.push_back(word.speaker);
      }
      confidence_sum += word.confidence;
    }
    segment.insert(
        QStringLiteral("speaker"),
        speakers.isEmpty()
            ? QStringLiteral("Speaker")
            : speakers.size() == 1 ? speakers.constFirst()
                                   : QStringLiteral("Multiple speakers"));
    segment.insert(
        QStringLiteral("confidence"),
        clip.caption_words.isEmpty()
            ? 1.0
            : confidence_sum / static_cast<double>(clip.caption_words.size()));
    segment.insert(QStringLiteral("words"), words);
    values.push_back(segment);
  }
  transcript_segments_cache_key_ = cache_key;
  transcript_segments_cache_ = values;
  return transcript_segments_cache_;
}

QVariantList TimelineDocumentController::transcriptCleanupSuggestions() const {
  const auto cache_key = QStringLiteral("%1:%2:%3")
                             .arg(timeline_id_)
                             .arg(document_edit_revision_)
                             .arg(transcript_analysis_revision_);
  if (cache_key == transcript_cleanup_suggestions_cache_key_) {
    return transcript_cleanup_suggestions_cache_;
  }
  struct TimedTranscriptWord final {
    QString clip_id;
    int word_index = 0;
    QString text;
    QString normalized_text;
    double start_seconds = 0.0;
    double end_seconds = 0.0;
  };
  QVector<TimedTranscriptWord> words;
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (clip.media_type != QStringLiteral("caption")) {
        continue;
      }
      for (int word_index = 0; word_index < clip.caption_words.size(); ++word_index) {
        const auto& word = clip.caption_words.at(word_index);
        QString normalized;
        for (const auto character : word.text.toLower()) {
          if (character.isLetter() || character == QLatin1Char('\'')) {
            normalized.append(character);
          }
        }
        words.push_back({
            clip.clip_id,
            word_index,
            word.text,
            normalized,
            clip.start_seconds + word.start_seconds,
            clip.start_seconds + word.end_seconds,
        });
      }
    }
  }
  std::sort(words.begin(), words.end(), [](const auto& left, const auto& right) {
    if (qAbs(left.start_seconds - right.start_seconds) > kBoundaryEpsilon) {
      return left.start_seconds < right.start_seconds;
    }
    return left.end_seconds < right.end_seconds;
  });

  const QSet<QString> filler_words = {
      QStringLiteral("um"),
      QStringLiteral("uh"),
      QStringLiteral("erm"),
      QStringLiteral("hmm"),
  };
  QVariantList suggestions;
  constexpr double kFillerEditHandleSeconds = 0.04;
  for (int index = 0; index < words.size(); ++index) {
    const auto& word = words.at(index);
    if (!filler_words.contains(word.normalized_text)) {
      continue;
    }
    const auto previous_end = index > 0 ? words.at(index - 1).end_seconds : 0.0;
    const auto next_start = index + 1 < words.size()
                                ? words.at(index + 1).start_seconds
                                : totalDurationSeconds();
    const auto edit_start = qMax(previous_end, word.start_seconds - kFillerEditHandleSeconds);
    const auto edit_end = qMin(next_start, word.end_seconds + kFillerEditHandleSeconds);
    if (edit_end <= edit_start + 0.05) {
      continue;
    }
    QVariantMap suggestion;
    suggestion.insert(
        QStringLiteral("suggestionId"),
        QStringLiteral("filler:%1:%2").arg(word.clip_id).arg(word.word_index));
    suggestion.insert(QStringLiteral("kind"), QStringLiteral("filler"));
    suggestion.insert(QStringLiteral("label"), QStringLiteral("Remove “%1”").arg(word.text));
    suggestion.insert(QStringLiteral("detail"), QStringLiteral("Filler word · review before applying"));
    suggestion.insert(QStringLiteral("startSeconds"), edit_start);
    suggestion.insert(QStringLiteral("endSeconds"), edit_end);
    suggestion.insert(QStringLiteral("durationSeconds"), edit_end - edit_start);
    suggestion.insert(QStringLiteral("timecode"), formatDurationText(edit_start));
    suggestion.insert(QStringLiteral("source"), QStringLiteral("transcript-word"));
    suggestions.push_back(suggestion);
  }

  constexpr double kAudioSilenceSuggestionSeconds = 0.55;
  constexpr double kAudioSilencePreservedHandleSeconds = 0.09;
  QVector<QPair<double, double>> audio_suggestion_ranges;
  for (const auto& track : tracks_) {
    if (track.kind != TrackKind::Video || track.role == QStringLiteral("caption")) {
      continue;
    }
    for (const auto& clip : track.clips) {
      for (int range_index = 0; range_index < clip.audio_silence_ranges.size(); ++range_index) {
        const auto& range = clip.audio_silence_ranges.at(range_index);
        const auto source_start = qMax(clip.trim_start_seconds, range.source_start_seconds);
        const auto source_end = qMin(clip.trim_end_seconds, range.source_end_seconds);
        const auto mapped_start = clip.start_seconds +
                                  clipTimelineSecondsForSourceTime(clip, source_start);
        const auto mapped_end = clip.start_seconds +
                                clipTimelineSecondsForSourceTime(clip, source_end);
        const auto silence_start = qMin(mapped_start, mapped_end);
        const auto silence_end = qMax(mapped_start, mapped_end);
        const auto silence_duration = silence_end - silence_start;
        if (silence_duration < kAudioSilenceSuggestionSeconds) {
          continue;
        }
        const auto edit_start = silence_start + kAudioSilencePreservedHandleSeconds;
        const auto edit_end = silence_end - kAudioSilencePreservedHandleSeconds;
        if (edit_end <= edit_start + 0.05) {
          continue;
        }
        QVariantMap suggestion;
        suggestion.insert(
            QStringLiteral("suggestionId"),
            QStringLiteral("silence:%1:%2").arg(clip.clip_id).arg(range_index));
        suggestion.insert(QStringLiteral("kind"), QStringLiteral("audio-silence"));
        suggestion.insert(
            QStringLiteral("label"),
            QStringLiteral("Shorten %1 detected silence").arg(formatDurationText(silence_duration)));
        suggestion.insert(
            QStringLiteral("detail"),
            QStringLiteral("Audio analysis · keeps 180 ms of natural room"));
        suggestion.insert(QStringLiteral("startSeconds"), edit_start);
        suggestion.insert(QStringLiteral("endSeconds"), edit_end);
        suggestion.insert(QStringLiteral("durationSeconds"), edit_end - edit_start);
        suggestion.insert(QStringLiteral("timecode"), formatDurationText(edit_start));
        suggestion.insert(QStringLiteral("source"), QStringLiteral("audio-analysis"));
        suggestions.push_back(suggestion);
        audio_suggestion_ranges.push_back({edit_start, edit_end});
      }
    }
  }

  constexpr double kSpeechGapSuggestionSeconds = 0.55;
  constexpr double kSpeechGapPreservedHandleSeconds = 0.09;
  for (int index = 1; index < words.size(); ++index) {
    const auto& previous = words.at(index - 1);
    const auto& current = words.at(index);
    const auto gap_seconds = current.start_seconds - previous.end_seconds;
    if (gap_seconds < kSpeechGapSuggestionSeconds) {
      continue;
    }
    const auto remove_start = previous.end_seconds + kSpeechGapPreservedHandleSeconds;
    const auto remove_end = current.start_seconds - kSpeechGapPreservedHandleSeconds;
    if (remove_end <= remove_start + 0.05) {
      continue;
    }
    auto overlaps_audio_suggestion = false;
    for (const auto& audio_range : audio_suggestion_ranges) {
      if (audio_range.second > remove_start + kBoundaryEpsilon &&
          audio_range.first < remove_end - kBoundaryEpsilon) {
        overlaps_audio_suggestion = true;
        break;
      }
    }
    if (overlaps_audio_suggestion) {
      continue;
    }
    QVariantMap suggestion;
    suggestion.insert(
        QStringLiteral("suggestionId"),
        QStringLiteral("gap:%1:%2:%3:%4")
            .arg(previous.clip_id)
            .arg(previous.word_index)
            .arg(current.clip_id)
            .arg(current.word_index));
    suggestion.insert(QStringLiteral("kind"), QStringLiteral("speech-gap"));
    suggestion.insert(QStringLiteral("label"), QStringLiteral("Shorten %1 pause").arg(formatDurationText(gap_seconds)));
    suggestion.insert(
        QStringLiteral("detail"),
        QStringLiteral("Keeps 180 ms of breathing room between “%1” and “%2”")
            .arg(previous.text, current.text));
    suggestion.insert(QStringLiteral("startSeconds"), remove_start);
    suggestion.insert(QStringLiteral("endSeconds"), remove_end);
    suggestion.insert(QStringLiteral("durationSeconds"), remove_end - remove_start);
    suggestion.insert(QStringLiteral("timecode"), formatDurationText(remove_start));
    suggestion.insert(QStringLiteral("source"), QStringLiteral("transcript-gap"));
    suggestions.push_back(suggestion);
  }
  std::sort(suggestions.begin(), suggestions.end(), [](const QVariant& left, const QVariant& right) {
    return left.toMap().value(QStringLiteral("startSeconds")).toDouble() <
           right.toMap().value(QStringLiteral("startSeconds")).toDouble();
  });
  transcript_cleanup_suggestions_cache_key_ = cache_key;
  transcript_cleanup_suggestions_cache_ = suggestions;
  return transcript_cleanup_suggestions_cache_;
}

QVariantList TimelineDocumentController::pendingTextBasedEdits() const {
  QVariantList values;
  values.reserve(pending_text_based_edits_.size());
  for (int index = 0; index < pending_text_based_edits_.size(); ++index) {
    const auto& operation = pending_text_based_edits_.at(index);
    const auto duration = qMax(0.0, operation.end_seconds - operation.start_seconds);
    QVariantMap value{
        {QStringLiteral("operationId"), operation.operation_id},
        {QStringLiteral("index"), index},
        {QStringLiteral("kind"), operation.kind},
        {QStringLiteral("startSeconds"), operation.start_seconds},
        {QStringLiteral("endSeconds"), operation.end_seconds},
        {QStringLiteral("durationSeconds"), duration},
        {QStringLiteral("destinationSeconds"), operation.destination_seconds},
        {QStringLiteral("startTimecode"), formatDurationText(operation.start_seconds)},
        {QStringLiteral("endTimecode"), formatDurationText(operation.end_seconds)},
    };
    if (operation.kind == QStringLiteral("delete")) {
      value.insert(QStringLiteral("label"), QStringLiteral("Delete %1").arg(formatDurationText(duration)));
      value.insert(QStringLiteral("detail"), QStringLiteral("Ripple range %1–%2 on commit")
                       .arg(formatDurationText(operation.start_seconds),
                            formatDurationText(operation.end_seconds)));
    } else {
      value.insert(QStringLiteral("label"), QStringLiteral("Rearrange %1").arg(formatDurationText(duration)));
      value.insert(QStringLiteral("detail"), QStringLiteral("Move %1–%2 to %3 on commit")
                       .arg(formatDurationText(operation.start_seconds),
                            formatDurationText(operation.end_seconds),
                            formatDurationText(operation.destination_seconds)));
    }
    values.push_back(value);
  }
  return values;
}

TimelineDocumentController::TextBasedEditPlan
TimelineDocumentController::buildTextBasedEditPlan(
    const QVector<TextBasedEditOperation>& operations) const {
  TextBasedEditPlan plan;
  plan.original_duration_seconds = totalDurationSeconds();
  if (!has_active_timeline_ || operations.isEmpty() ||
      plan.original_duration_seconds <= kBoundaryEpsilon) {
    plan.reason = operations.isEmpty()
                      ? QStringLiteral("Stage a transcript edit to build a review plan.")
                      : QStringLiteral("The active sequence has no editable duration.");
    return plan;
  }

  plan.boundaries = {0.0, plan.original_duration_seconds};
  QVector<QPair<double, double>> source_ranges;
  source_ranges.reserve(operations.size());
  for (const auto& operation : operations) {
    if (operation.kind != QStringLiteral("delete") &&
        operation.kind != QStringLiteral("move")) {
      plan.reason = QStringLiteral("The edit plan contains an unsupported operation.");
      return plan;
    }
    const auto start_seconds = qBound(
        0.0,
        qMin(operation.start_seconds, operation.end_seconds),
        plan.original_duration_seconds);
    const auto end_seconds = qBound(
        start_seconds,
        qMax(operation.start_seconds, operation.end_seconds),
        plan.original_duration_seconds);
    if (end_seconds <= start_seconds + kBoundaryEpsilon) {
      plan.reason = QStringLiteral("Every staged edit must contain at least one timed word.");
      return plan;
    }
    for (const auto& source_range : source_ranges) {
      if (source_range.second > start_seconds + kBoundaryEpsilon &&
          source_range.first < end_seconds - kBoundaryEpsilon) {
        plan.reason = QStringLiteral("Staged source ranges cannot overlap. Restore one edit and try again.");
        return plan;
      }
    }
    source_ranges.push_back({start_seconds, end_seconds});
    plan.boundaries.push_back(start_seconds);
    plan.boundaries.push_back(end_seconds);
    if (operation.kind == QStringLiteral("move")) {
      const auto destination_seconds = qBound(
          0.0, operation.destination_seconds, plan.original_duration_seconds);
      if (destination_seconds > start_seconds + kBoundaryEpsilon &&
          destination_seconds < end_seconds - kBoundaryEpsilon) {
        plan.reason = QStringLiteral("A rearranged range cannot be inserted inside itself.");
        return plan;
      }
      plan.boundaries.push_back(destination_seconds);
    }
  }
  std::sort(plan.boundaries.begin(), plan.boundaries.end());
  plan.boundaries.erase(
      std::unique(
          plan.boundaries.begin(),
          plan.boundaries.end(),
          [](double left, double right) {
            return qAbs(left - right) <= kBoundaryEpsilon;
          }),
      plan.boundaries.end());
  for (int index = 0; index + 1 < plan.boundaries.size(); ++index) {
    const auto start_seconds = plan.boundaries.at(index);
    const auto end_seconds = plan.boundaries.at(index + 1);
    if (end_seconds > start_seconds + kBoundaryEpsilon) {
      plan.blocks.push_back({start_seconds, end_seconds, -1.0});
    }
  }
  plan.ordered_block_indices.resize(plan.blocks.size());
  std::iota(
      plan.ordered_block_indices.begin(),
      plan.ordered_block_indices.end(),
      0);

  for (const auto& operation : operations) {
    QVector<int> source_indices;
    for (int block_index = 0; block_index < plan.blocks.size(); ++block_index) {
      const auto& block = plan.blocks.at(block_index);
      if (block.original_start_seconds >= operation.start_seconds - kBoundaryEpsilon &&
          block.original_end_seconds <= operation.end_seconds + kBoundaryEpsilon) {
        source_indices.push_back(block_index);
      }
    }
    if (source_indices.isEmpty()) {
      plan.reason = QStringLiteral("A staged transcript range no longer resolves in the sequence.");
      return plan;
    }
    for (const auto source_index : source_indices) {
      if (!plan.ordered_block_indices.contains(source_index)) {
        plan.reason = QStringLiteral("A staged range was already removed by another edit.");
        return plan;
      }
    }
    plan.ordered_block_indices.erase(
        std::remove_if(
            plan.ordered_block_indices.begin(),
            plan.ordered_block_indices.end(),
            [&source_indices](int block_index) {
              return source_indices.contains(block_index);
            }),
        plan.ordered_block_indices.end());
    if (operation.kind == QStringLiteral("move")) {
      auto insertion = plan.ordered_block_indices.end();
      for (auto candidate = plan.ordered_block_indices.begin();
           candidate != plan.ordered_block_indices.end(); ++candidate) {
        if (plan.blocks.at(*candidate).original_start_seconds >=
            operation.destination_seconds - kBoundaryEpsilon) {
          insertion = candidate;
          break;
        }
      }
      auto insertion_index = static_cast<qsizetype>(
          std::distance(plan.ordered_block_indices.begin(), insertion));
      for (const auto source_index : source_indices) {
        plan.ordered_block_indices.insert(insertion_index, source_index);
        ++insertion_index;
      }
    }
  }

  auto next_start_seconds = 0.0;
  for (const auto block_index : plan.ordered_block_indices) {
    auto& block = plan.blocks[block_index];
    block.new_start_seconds = next_start_seconds;
    next_start_seconds += block.original_end_seconds - block.original_start_seconds;
  }
  plan.preview_duration_seconds = next_start_seconds;
  plan.deleted_duration_seconds = qMax(
      0.0, plan.original_duration_seconds - plan.preview_duration_seconds);
  plan.valid = true;
  return plan;
}

QVariantMap TimelineDocumentController::buildTextBasedEditPreview(
    const QVector<TextBasedEditOperation>& operations) const {
  const auto plan = buildTextBasedEditPlan(operations);
  QVariantList preview_words;
  struct PreviewWord final {
    QString text;
    QString speaker;
    double start_seconds = 0.0;
    double end_seconds = 0.0;
  };
  QVector<PreviewWord> mapped_words;
  if (plan.valid) {
    const auto block_for_seconds = [&plan](double seconds) -> const TextBasedEditBlock* {
      for (const auto& block : plan.blocks) {
        if (seconds >= block.original_start_seconds - kBoundaryEpsilon &&
            seconds < block.original_end_seconds - kBoundaryEpsilon) {
          return &block;
        }
      }
      return plan.blocks.isEmpty() ? nullptr : &plan.blocks.constLast();
    };
    for (const auto& track : tracks_) {
      for (const auto& clip : track.clips) {
        if (clip.media_type != QStringLiteral("caption")) {
          continue;
        }
        for (const auto& word : clip.caption_words) {
          const auto original_start = clip.start_seconds + word.start_seconds;
          const auto original_end = clip.start_seconds + word.end_seconds;
          const auto* block = block_for_seconds((original_start + original_end) / 2.0);
          if (block == nullptr || block->new_start_seconds < 0.0) {
            continue;
          }
          const auto offset = original_start - block->original_start_seconds;
          mapped_words.push_back({
              word.text,
              word.speaker,
              block->new_start_seconds + offset,
              block->new_start_seconds + offset + (original_end - original_start),
          });
        }
      }
    }
    std::sort(mapped_words.begin(), mapped_words.end(), [](const auto& left, const auto& right) {
      if (qAbs(left.start_seconds - right.start_seconds) > kBoundaryEpsilon) {
        return left.start_seconds < right.start_seconds;
      }
      return left.end_seconds < right.end_seconds;
    });
    preview_words.reserve(mapped_words.size());
    for (const auto& word : mapped_words) {
      preview_words.push_back(QVariantMap{
          {QStringLiteral("text"), word.text},
          {QStringLiteral("speaker"), word.speaker},
          {QStringLiteral("startSeconds"), word.start_seconds},
          {QStringLiteral("endSeconds"), word.end_seconds},
          {QStringLiteral("timecode"), formatDurationText(word.start_seconds)},
      });
    }
  }
  QStringList transcript_words;
  transcript_words.reserve(mapped_words.size());
  for (const auto& word : mapped_words) {
    transcript_words.push_back(word.text);
  }
  auto move_count = 0;
  auto delete_count = 0;
  for (const auto& operation : operations) {
    if (operation.kind == QStringLiteral("move")) {
      ++move_count;
    } else if (operation.kind == QStringLiteral("delete")) {
      ++delete_count;
    }
  }
  return QVariantMap{
      {QStringLiteral("schema"), QStringLiteral("timeline-text-edit-plan:v1")},
      {QStringLiteral("valid"), plan.valid},
      {QStringLiteral("reason"), plan.reason},
      {QStringLiteral("operationCount"), operations.size()},
      {QStringLiteral("deleteCount"), delete_count},
      {QStringLiteral("moveCount"), move_count},
      {QStringLiteral("originalDurationSeconds"), plan.original_duration_seconds},
      {QStringLiteral("previewDurationSeconds"), plan.preview_duration_seconds},
      {QStringLiteral("deletedDurationSeconds"), plan.deleted_duration_seconds},
      {QStringLiteral("previewWords"), preview_words},
      {QStringLiteral("previewTranscript"), transcript_words.join(QLatin1Char(' '))},
      {QStringLiteral("nonMutating"), true},
      {QStringLiteral("commitUndoSteps"), plan.valid ? 1 : 0},
  };
}

QVariantMap TimelineDocumentController::textBasedEditPreview() const {
  auto preview = buildTextBasedEditPreview(pending_text_based_edits_);
  const auto stale = !pending_text_based_edits_.isEmpty() &&
                     !pending_text_based_edit_document_hash_.isEmpty() &&
                     deterministicDocumentHash() != pending_text_based_edit_document_hash_;
  preview.insert(QStringLiteral("stale"), stale);
  if (stale) {
    preview.insert(QStringLiteral("valid"), false);
    preview.insert(
        QStringLiteral("reason"),
        QStringLiteral("The sequence changed after this review plan was staged. Clear it and review fresh ranges."));
  }
  return preview;
}

