QVariantMap TimelineDocumentController::loudnessAnalysisResult() const {
  constexpr double kTargetLufs = -14.0;
  constexpr double kTruePeakCeilingDbtp = -1.0;
  const auto recommended_gain = loudness_measured_
      ? qMin(kTargetLufs - loudness_integrated_lufs_,
             kTruePeakCeilingDbtp - loudness_true_peak_dbtp_)
      : 0.0;
  return QVariantMap{
      {QStringLiteral("measured"), loudness_measured_},
      {QStringLiteral("integratedLufs"), loudness_integrated_lufs_},
      {QStringLiteral("truePeakDbtp"), loudness_true_peak_dbtp_},
      {QStringLiteral("loudnessRangeLu"), loudness_range_lu_},
      {QStringLiteral("thresholdLufs"), loudness_threshold_lufs_},
      {QStringLiteral("targetOffsetDb"), loudness_target_offset_db_},
      {QStringLiteral("targetLufs"), kTargetLufs},
      {QStringLiteral("truePeakCeilingDbtp"), kTruePeakCeilingDbtp},
      {QStringLiteral("recommendedGainDb"), qBound(-24.0, recommended_gain, 24.0)},
      {QStringLiteral("withinLoudnessTarget"),
       loudness_measured_ && qAbs(loudness_integrated_lufs_ - kTargetLufs) <= 1.0},
      {QStringLiteral("truePeakPass"),
       loudness_measured_ && loudness_true_peak_dbtp_ <= kTruePeakCeilingDbtp + 0.01},
      {QStringLiteral("status"), loudness_analysis_status_},
  };
}

