QVariantList TimelineDocumentController::timelineSearchResults(
    const QString& query,
    const QString& kind,
    const QString& track_id,
    const QString& marker_status) const {
  const auto normalized_query = query.simplified();
  const auto normalized_kind = kind.trimmed().toLower();
  const auto normalized_marker_status = marker_status.trimmed().toLower();
  const auto scope_track_id = track_id.trimmed();
  const auto matches_query = [&normalized_query](const QStringList& values) {
    if (normalized_query.isEmpty()) {
      return true;
    }
    for (const auto& value : values) {
      if (value.contains(normalized_query, Qt::CaseInsensitive)) {
        return true;
      }
    }
    return false;
  };

  QVariantList results;
  QVector<int> clip_result_positions;
  if (scope_track_id.isEmpty() &&
      (normalized_kind.isEmpty() || normalized_kind == QStringLiteral("all") ||
       normalized_kind == QStringLiteral("markers"))) {
    for (const auto& marker : markers_) {
      const auto state = marker.completed ? QStringLiteral("completed") : marker.status;
      if (normalized_marker_status == QStringLiteral("open") && marker.completed) {
        continue;
      }
      if (!normalized_marker_status.isEmpty() &&
          normalized_marker_status != QStringLiteral("all") &&
          normalized_marker_status != QStringLiteral("open") &&
          marker.status.compare(normalized_marker_status, Qt::CaseInsensitive) != 0) {
        continue;
      }
      if (!matches_query({marker.label, marker.note, marker.status, state,
                          formatDurationText(marker.seconds)})) {
        continue;
      }
      QVariantMap result;
      result.insert(QStringLiteral("type"), QStringLiteral("marker"));
      result.insert(QStringLiteral("id"), marker.marker_id);
      result.insert(QStringLiteral("label"), marker.label);
      result.insert(
          QStringLiteral("detail"),
          marker.note.isEmpty() ? state : QStringLiteral("%1 · %2").arg(state, marker.note));
      result.insert(QStringLiteral("seconds"), marker.seconds);
      result.insert(QStringLiteral("timecode"), formatDurationText(marker.seconds));
      result.insert(QStringLiteral("trackId"), QString{});
      result.insert(QStringLiteral("mediaType"), QStringLiteral("marker"));
      result.insert(QStringLiteral("mediaOnline"), true);
      result.insert(QStringLiteral("effectCount"), 0);
      results.push_back(result);
    }
  }

  if (normalized_kind != QStringLiteral("markers")) {
    for (const auto& track : tracks_) {
      if (!scope_track_id.isEmpty() && track.track_id != scope_track_id) {
        continue;
      }
      for (const auto& clip : track.clips) {
        const auto online = clip.media_type == QStringLiteral("title") ||
                            clip.media_type == QStringLiteral("caption") ||
                            clip.media_type == QStringLiteral("adjustment") ||
                            QFileInfo::exists(clip.file_path);
        const auto is_audio = track.kind == TrackKind::Audio;
        const auto media_kind = is_audio ? QStringLiteral("audio") : clip.media_type;
        auto kind_matches = normalized_kind.isEmpty() || normalized_kind == QStringLiteral("all") ||
                            normalized_kind == QStringLiteral("clips");
        if (normalized_kind == QStringLiteral("video")) {
          kind_matches = !is_audio && clip.media_type == QStringLiteral("video");
        } else if (normalized_kind == QStringLiteral("audio")) {
          kind_matches = is_audio;
        } else if (normalized_kind == QStringLiteral("photo") ||
                   normalized_kind == QStringLiteral("title") ||
                   normalized_kind == QStringLiteral("caption")) {
          kind_matches = !is_audio && clip.media_type == normalized_kind;
        } else if (normalized_kind == QStringLiteral("offline")) {
          kind_matches = !online;
        } else if (normalized_kind == QStringLiteral("effects")) {
          kind_matches = !clip.effect_stack.isEmpty();
        }
        if (!kind_matches) {
          continue;
        }

        QStringList searchable{
            clip.display_label,
            track.display_label,
            media_kind,
            clip.media_type,
            clip.transition_in_name,
            clip.transition_out_name,
            formatDurationText(clip.start_seconds),
            QFileInfo(clip.file_path).fileName(),
            online ? QStringLiteral("online") : QStringLiteral("offline"),
        };
        searchable.append(clip.effect_stack);
        if (!matches_query(searchable)) {
          continue;
        }
        QVariantMap result;
        result.insert(QStringLiteral("type"), QStringLiteral("clip"));
        result.insert(QStringLiteral("id"), clip.clip_id);
        result.insert(QStringLiteral("label"), clip.display_label);
        result.insert(
            QStringLiteral("detail"),
            QStringLiteral("%1 · %2%3")
                .arg(track.display_label,
                     media_kind,
                     online ? QString{} : QStringLiteral(" · Offline")));
        result.insert(QStringLiteral("seconds"), clip.start_seconds);
        result.insert(QStringLiteral("timecode"), formatDurationText(clip.start_seconds));
        result.insert(QStringLiteral("trackId"), track.track_id);
        result.insert(QStringLiteral("trackLabel"), track.display_label);
        result.insert(QStringLiteral("mediaType"), media_kind);
        result.insert(QStringLiteral("mediaOnline"), online);
        result.insert(QStringLiteral("effectCount"), clip.effect_stack.size());
        clip_result_positions.push_back(static_cast<int>(results.size()));
        results.push_back(result);
      }
    }
  }

  // A one-hit query was already a single ordered-index lookup. Keep that
  // common case allocation-free; broad results share one sorted reference map.
  if (clip_result_positions.size() == 1) {
    const auto position = clip_result_positions.constFirst();
    auto result = results.at(position).toMap();
    result.insert(
        QStringLiteral("clipIndex"),
        flattenedIndexForClipId(result.value(QStringLiteral("id")).toString()));
    results[position] = result;
  } else if (clip_result_positions.size() > 1) {
    const auto ordered_refs = orderedSelectableClipRefs();
    QHash<QString, int> flattened_index_by_clip_id;
    flattened_index_by_clip_id.reserve(ordered_refs.size());
    for (int index = 0; index < ordered_refs.size(); ++index) {
      const auto* clip = clipAt(ordered_refs.at(index));
      if (clip != nullptr) {
        flattened_index_by_clip_id.insert(clip->clip_id, index);
      }
    }
    for (const auto position : clip_result_positions) {
      auto result = results.at(position).toMap();
      result.insert(
          QStringLiteral("clipIndex"),
          flattened_index_by_clip_id.value(result.value(QStringLiteral("id")).toString(), -1));
      results[position] = result;
    }
  }

  std::sort(
      results.begin(),
      results.end(),
      [](const QVariant& left_value, const QVariant& right_value) {
        const auto left = left_value.toMap();
        const auto right = right_value.toMap();
        const auto left_seconds = left.value(QStringLiteral("seconds")).toDouble();
        const auto right_seconds = right.value(QStringLiteral("seconds")).toDouble();
        if (qAbs(left_seconds - right_seconds) > kBoundaryEpsilon) {
          return left_seconds < right_seconds;
        }
        if (left.value(QStringLiteral("type")).toString() !=
            right.value(QStringLiteral("type")).toString()) {
          return left.value(QStringLiteral("type")).toString() == QStringLiteral("marker");
        }
        return left.value(QStringLiteral("label")).toString().localeAwareCompare(
                   right.value(QStringLiteral("label")).toString()) < 0;
      });
  return results;
}

QVariantList TimelineDocumentController::playbackPrefetchCandidates(
    double sequence_seconds,
    double direction,
    double loop_start_seconds,
    double loop_end_seconds,
    double likely_next_edit_seconds,
    int maximum_candidates) const {
  struct Candidate final {
    QString clip_id;
    QString source_url;
    QString reason;
    double sequence_seconds = 0.0;
    double source_seconds = 0.0;
    double score = 0.0;
  };

  const auto playhead = qBound(0.0, sequence_seconds, totalDurationSeconds());
  const auto signed_direction = direction < 0.0 ? -1.0 : 1.0;
  const auto current_ref = programClipRef();
  const auto* current_clip = clipAt(current_ref);
  const auto current_url = current_clip == nullptr
                               ? QString{}
                               : QUrl::fromLocalFile(playbackFilePath(*current_clip)).toString();
  QVector<Candidate> candidates;
  QSet<QString> candidate_identities;
  const auto append_clip = [&](const Clip& clip,
                               const QString& reason,
                               double target_sequence_seconds,
                               double score) {
    if (clip.media_type != QStringLiteral("video") || clip.file_path.isEmpty()) {
      return;
    }
    const auto source_url = QUrl::fromLocalFile(playbackFilePath(clip)).toString();
    const auto target = qBound(
        clip.start_seconds,
        target_sequence_seconds,
        qMax(clip.start_seconds, clipEndSeconds(clip) - kBoundaryEpsilon));
    const auto identity = source_url + QLatin1Char('|') +
                          QString::number(target, 'f', 3);
    if (source_url.isEmpty() || source_url == current_url ||
        candidate_identities.contains(identity)) {
      return;
    }
    candidate_identities.insert(identity);
    candidates.push_back(Candidate{
        clip.clip_id,
        source_url,
        reason,
        target,
        clipLocalSecondsForSequenceTime(clip, target),
        score,
    });
  };

  const auto visibility = trackVisibilityState();
  for (const auto& track : tracks_) {
    if (track.kind != TrackKind::Video || track.role == QStringLiteral("caption") ||
        !visibility.effective_by_track_id.value(track.track_id, track.visible)) {
      continue;
    }
    for (const auto& clip : track.clips) {
      const auto clip_start = clip.start_seconds;
      const auto clip_end = clipEndSeconds(clip);
      if (likely_next_edit_seconds >= 0.0 &&
          likely_next_edit_seconds + kBoundaryEpsilon >= clip_start &&
          likely_next_edit_seconds < clip_end - kBoundaryEpsilon) {
        append_clip(clip, QStringLiteral("likely-next-edit"), likely_next_edit_seconds, 0.0);
      }
      if (loop_start_seconds >= 0.0 && loop_end_seconds > loop_start_seconds &&
          loop_start_seconds + kBoundaryEpsilon >= clip_start &&
          loop_start_seconds < clip_end - kBoundaryEpsilon) {
        append_clip(clip, QStringLiteral("loop-start"), loop_start_seconds, 0.25);
      }
      if (loop_start_seconds >= 0.0 && loop_end_seconds > loop_start_seconds &&
          loop_end_seconds > clip_start + kBoundaryEpsilon &&
          loop_end_seconds <= clip_end + kBoundaryEpsilon) {
        append_clip(
            clip,
            QStringLiteral("loop-end"),
            qMax(clip_start, loop_end_seconds - 1.0 / framesPerSecond()),
            0.35);
      }
      if (signed_direction > 0.0 && clip_start > playhead + kBoundaryEpsilon) {
        append_clip(
            clip,
            QStringLiteral("forward-cut"),
            clip_start,
            1.0 + clip_start - playhead);
      } else if (signed_direction < 0.0 && clip_end < playhead - kBoundaryEpsilon) {
        append_clip(
            clip,
            QStringLiteral("reverse-cut"),
            qMax(clip_start, clip_end - 1.0 / framesPerSecond()),
            1.0 + playhead - clip_end);
      }
    }
  }

  for (const auto& task : expectedRenderCacheTasks()) {
    if (!QFileInfo::exists(task.output_path)) {
      continue;
    }
    const auto distance = signed_direction > 0.0
                              ? task.start_seconds - playhead
                              : playhead - task.end_seconds;
    if (distance < -kBoundaryEpsilon) {
      continue;
    }
    const auto source_url = QUrl::fromLocalFile(task.output_path).toString();
    if (source_url == current_url || candidate_identities.contains(source_url)) {
      continue;
    }
    candidate_identities.insert(source_url);
    candidates.push_back(Candidate{
        QString{},
        source_url,
        QStringLiteral("render-cache"),
        signed_direction > 0.0 ? task.start_seconds : task.end_seconds,
        0.0,
        0.75 + qMax(0.0, distance),
    });
  }

  std::sort(candidates.begin(), candidates.end(), [](const auto& left, const auto& right) {
    if (qAbs(left.score - right.score) > kBoundaryEpsilon) {
      return left.score < right.score;
    }
    if (qAbs(left.sequence_seconds - right.sequence_seconds) > kBoundaryEpsilon) {
      return left.sequence_seconds < right.sequence_seconds;
    }
    return left.clip_id < right.clip_id;
  });

  QVariantList result;
  const auto limit = qBound(1, maximum_candidates, 16);
  for (auto index = 0; index < candidates.size() && index < limit; ++index) {
    const auto& candidate = candidates.at(index);
    result.push_back(QVariantMap{
        {QStringLiteral("clipId"), candidate.clip_id},
        {QStringLiteral("sourceUrl"), candidate.source_url},
        {QStringLiteral("reason"), candidate.reason},
        {QStringLiteral("sequenceSeconds"), candidate.sequence_seconds},
        {QStringLiteral("sourceSeconds"), candidate.source_seconds},
        {QStringLiteral("direction"), signed_direction},
        {QStringLiteral("protectedSourceUrl"), current_url},
    });
  }
  return result;
}

bool TimelineDocumentController::activateTimelineSearchResult(
    const QString& result_type,
    const QString& result_id) {
  if (result_type == QStringLiteral("marker")) {
    for (const auto& marker : markers_) {
      if (marker.marker_id == result_id) {
        seekSequenceSeconds(marker.seconds);
        setStatus(QStringLiteral("Found marker '%1'.").arg(marker.label));
        return true;
      }
    }
    return false;
  }
  if (result_type != QStringLiteral("clip")) {
    return false;
  }
  const auto index = flattenedIndexForClipId(result_id);
  if (index < 0) {
    return false;
  }
  selectClip(index);
  if (const auto* clip = clipAt(selectedClipRef()); clip != nullptr) {
    setStatus(QStringLiteral("Found clip '%1'.").arg(clip->display_label));
  }
  return true;
}

