QVariantMap TimelineDocumentController::deliverySettings() const {
  const auto resolved_encoder = resolvedDeliveryEncoder();
  const auto alpha_master = export_alpha_;
  const auto effective_two_pass = export_two_pass_ && !alpha_master;
  QVariantMap map;
  map.insert(QStringLiteral("encoderMode"), export_encoder_mode_);
  map.insert(QStringLiteral("resolvedEncoder"), resolved_encoder);
  map.insert(QStringLiteral("twoPass"), export_two_pass_);
  map.insert(QStringLiteral("effectiveTwoPass"), effective_two_pass);
  map.insert(QStringLiteral("alpha"), alpha_master);
  map.insert(QStringLiteral("audioStems"), export_audio_stems_);
  map.insert(QStringLiteral("imageSequence"), export_image_sequence_);
  map.insert(QStringLiteral("masterFormat"), alpha_master ? QStringLiteral("ProRes 4444 · MOV")
                                                           : QStringLiteral("H.264 · MP4"));
  map.insert(QStringLiteral("stemCount"), deliveryAudioBuses().size());
  map.insert(QStringLiteral("packageArtifactCount"),
             1 + (export_audio_stems_ ? deliveryAudioBuses().size() : 0) +
                 (export_image_sequence_ ? 1 : 0));
  map.insert(QStringLiteral("hardwareFallback"),
             export_encoder_mode_ == QStringLiteral("hardware") &&
                 resolved_encoder != QStringLiteral("h264_videotoolbox"));
  return map;
}

QVariantMap TimelineDocumentController::deliveryCapabilities() const {
  const auto hardware_available = ffmpegEncoderAvailable(QStringLiteral("h264_videotoolbox"));
  return {
      {QStringLiteral("ffmpegAvailable"),
       !QStandardPaths::findExecutable(QStringLiteral("ffmpeg")).isEmpty()},
      {QStringLiteral("hardwareH264Available"), hardware_available},
      {QStringLiteral("hardwareEncoder"),
       hardware_available ? QStringLiteral("h264_videotoolbox") : QString()},
      {QStringLiteral("softwareEncoder"), QStringLiteral("libx264")},
      {QStringLiteral("alphaEncoder"), QStringLiteral("prores_ks")},
      {QStringLiteral("alphaPixelFormat"), QStringLiteral("yuva444p10le")},
      {QStringLiteral("imageSequenceFormat"), QStringLiteral("RGBA PNG")},
      {QStringLiteral("stemFormat"), QStringLiteral("24-bit PCM WAV")},
  };
}

QString TimelineDocumentController::activeOutputVariant() const {
  return active_output_variant_;
}

QVariantList TimelineDocumentController::outputVariants() const {
  QVariantList variants;
  variants.reserve(output_variant_definitions().size());
  for (const auto& definition : output_variant_definitions()) {
    auto override_count = 0;
    for (const auto& track : tracks_) {
      if (track.kind != TrackKind::Video) {
        continue;
      }
      for (const auto& clip : track.clips) {
        if (clip.output_variant_overrides.contains(definition.key) ||
            (definition.key == active_output_variant_ && !clip.clip_id.isEmpty())) {
          ++override_count;
        }
      }
    }
    QVariantMap variant;
    variant.insert(QStringLiteral("key"), definition.key);
    variant.insert(QStringLiteral("label"), definition.label);
    variant.insert(QStringLiteral("aspectRatio"), definition.aspect_ratio);
    variant.insert(QStringLiteral("width"), definition.size.width());
    variant.insert(QStringLiteral("height"), definition.size.height());
    variant.insert(QStringLiteral("active"), definition.key == active_output_variant_);
    variant.insert(QStringLiteral("overrideCount"), override_count);
    variants.push_back(variant);
  }
  return variants;
}

