void TimelineDocumentController::applyCaptionStyleMapToClip(
    const QVariantMap& style,
    Clip* clip) const {
  if (clip == nullptr) {
    return;
  }
  if (style.contains(QStringLiteral("fontFamily"))) {
    const auto family = style.value(QStringLiteral("fontFamily")).toString().simplified();
    clip->title_font_family = family.isEmpty() ? QStringLiteral("Sans Serif") : family.left(120);
  }
  if (style.contains(QStringLiteral("fontSize"))) {
    clip->title_font_size = qBound(12.0, style.value(QStringLiteral("fontSize")).toDouble(), 240.0);
  }
  if (style.contains(QStringLiteral("casing"))) {
    clip->caption_casing = normalized_caption_casing(style.value(QStringLiteral("casing")).toString());
  }
  if (style.contains(QStringLiteral("color"))) {
    clip->title_color = normalized_title_color(
        style.value(QStringLiteral("color")).toString(), clip->title_color);
  }
  if (style.contains(QStringLiteral("alignment"))) {
    clip->title_alignment = normalized_title_alignment(
        style.value(QStringLiteral("alignment")).toString());
  }
  if (style.contains(QStringLiteral("strokeColor"))) {
    clip->caption_stroke_color = normalized_title_color(
        style.value(QStringLiteral("strokeColor")).toString(), clip->caption_stroke_color);
  }
  if (style.contains(QStringLiteral("strokeWidth"))) {
    clip->caption_stroke_width =
        qBound(0.0, style.value(QStringLiteral("strokeWidth")).toDouble(), 12.0);
  }
  if (style.contains(QStringLiteral("shadowEnabled"))) {
    clip->caption_shadow_enabled = style.value(QStringLiteral("shadowEnabled")).toBool();
  }
  if (style.contains(QStringLiteral("shadowColor"))) {
    clip->caption_shadow_color = normalized_title_color(
        style.value(QStringLiteral("shadowColor")).toString(), clip->caption_shadow_color);
  }
  if (style.contains(QStringLiteral("shadowOffsetX"))) {
    clip->caption_shadow_offset_x =
        qBound(-32.0, style.value(QStringLiteral("shadowOffsetX")).toDouble(), 32.0);
  }
  if (style.contains(QStringLiteral("shadowOffsetY"))) {
    clip->caption_shadow_offset_y =
        qBound(-32.0, style.value(QStringLiteral("shadowOffsetY")).toDouble(), 32.0);
  }
  if (style.contains(QStringLiteral("backgroundColor"))) {
    clip->title_background_color = normalized_title_color(
        style.value(QStringLiteral("backgroundColor")).toString(),
        clip->title_background_color);
  }
  if (style.contains(QStringLiteral("backgroundPadding"))) {
    clip->caption_background_padding =
        qBound(0.0, style.value(QStringLiteral("backgroundPadding")).toDouble(), 64.0);
  }
  if (style.contains(QStringLiteral("backgroundRadius"))) {
    clip->caption_background_radius =
        qBound(0.0, style.value(QStringLiteral("backgroundRadius")).toDouble(), 64.0);
  }
  if (style.contains(QStringLiteral("positionX"))) {
    clip->title_position_x = qBound(0.0, style.value(QStringLiteral("positionX")).toDouble(), 1.0);
  }
  if (style.contains(QStringLiteral("positionY"))) {
    clip->title_position_y = qBound(0.0, style.value(QStringLiteral("positionY")).toDouble(), 1.0);
  }
  if (style.contains(QStringLiteral("safeMarginX"))) {
    clip->caption_safe_margin_x =
        qBound(0.0, style.value(QStringLiteral("safeMarginX")).toDouble(), 0.40);
  }
  if (style.contains(QStringLiteral("safeMarginY"))) {
    clip->caption_safe_margin_y =
        qBound(0.0, style.value(QStringLiteral("safeMarginY")).toDouble(), 0.40);
  }
}

QVariantMap TimelineDocumentController::captionStyleTemplatePreview(
    const QString& template_id) const {
  for (const auto& value : captionStyleTemplates()) {
    const auto map = value.toMap();
    if (map.value(QStringLiteral("templateId")).toString() != template_id) {
      continue;
    }
    auto preview = map;
    const auto style = map.value(QStringLiteral("style")).toMap();
    preview.insert(QStringLiteral("found"), true);
    preview.insert(
        QStringLiteral("summary"),
        QStringLiteral("%1 · %2 px · %3 · %4 aspect overrides")
            .arg(style.value(QStringLiteral("fontFamily")).toString())
            .arg(qRound(style.value(QStringLiteral("fontSize")).toDouble()))
            .arg(normalized_caption_casing(style.value(QStringLiteral("casing")).toString()))
            .arg(map.value(QStringLiteral("aspectOverrides")).toMap().size()));
    return preview;
  }
  return QVariantMap{{QStringLiteral("found"), false}};
}

