QVariantMap TimelineDocumentController::timelineDeliveryPreflight(const QString& preset) const {
  const auto normalized_preset = normalized_export_preset(
      preset.simplified().isEmpty() ? export_preset_ : preset);
  auto recommended_variant = QStringLiteral("portrait");
  auto platform_label = QStringLiteral("Instagram");
  auto target_lufs = -14.0;
  auto video_bitrate_mbps = 10;
  auto audio_bitrate_kbps = 192;
  if (normalized_preset == QStringLiteral("youtube")) {
    recommended_variant = QStringLiteral("landscape");
    platform_label = QStringLiteral("YouTube");
    video_bitrate_mbps = 12;
    audio_bitrate_kbps = 384;
  } else if (normalized_preset == QStringLiteral("youtube_shorts")) {
    recommended_variant = QStringLiteral("vertical");
    platform_label = QStringLiteral("YouTube Shorts");
    video_bitrate_mbps = 10;
  } else if (normalized_preset == QStringLiteral("tiktok")) {
    recommended_variant = QStringLiteral("vertical");
    platform_label = QStringLiteral("TikTok");
    video_bitrate_mbps = 10;
  } else if (active_output_variant_ == QStringLiteral("square") ||
             active_output_variant_ == QStringLiteral("vertical")) {
    recommended_variant = active_output_variant_;
  }
  const auto& recommended = output_variant_definition(recommended_variant);

  QVariantList issues;
  auto error_count = 0;
  auto warning_count = 0;
  const auto add_issue = [&](const QString& key,
                             const QString& severity,
                             const QString& label,
                             const QString& message,
                             const QString& category = QStringLiteral("Delivery"),
                             const QString& repair = QString(),
                             const QString& item_id = QString(),
                             const QString& path = QString()) {
    issues.push_back(QVariantMap{{QStringLiteral("key"), key},
                                 {QStringLiteral("severity"), severity},
                                 {QStringLiteral("category"), category},
                                 {QStringLiteral("label"), label},
                                 {QStringLiteral("message"), message},
                                 {QStringLiteral("repair"), repair},
                                 {QStringLiteral("itemId"), item_id},
                                 {QStringLiteral("path"), path}});
    if (severity == QStringLiteral("error")) {
      ++error_count;
    } else {
      ++warning_count;
    }
  };

  if (!has_active_timeline_) {
    add_issue(QStringLiteral("timeline"), QStringLiteral("error"),
              QStringLiteral("Timeline"), QStringLiteral("Open a timeline before checking delivery."));
  }

  const auto current_ratio = sequence_size_.height() > 0
      ? static_cast<double>(sequence_size_.width()) / static_cast<double>(sequence_size_.height())
      : 0.0;
  const auto recommended_ratio = static_cast<double>(recommended.size.width()) /
      static_cast<double>(recommended.size.height());
  auto format_repair_available = false;
  if (has_active_timeline_ && qAbs(current_ratio - recommended_ratio) > 0.01) {
    format_repair_available = true;
    add_issue(QStringLiteral("aspect-ratio"), QStringLiteral("error"),
              QStringLiteral("Frame layout"),
              QStringLiteral("%1 expects %2. This timeline is %3 x %4; switch to %5 %6 before export.")
                  .arg(platform_label, recommended.aspect_ratio)
                  .arg(sequence_size_.width())
                  .arg(sequence_size_.height())
                  .arg(recommended.label, recommended.aspect_ratio));
  } else if (has_active_timeline_ &&
             (sequence_size_.width() < recommended.size.width() ||
              sequence_size_.height() < recommended.size.height())) {
    add_issue(QStringLiteral("resolution"), QStringLiteral("warning"),
              QStringLiteral("Resolution"),
              QStringLiteral("%1 recommends at least %2 x %3; this timeline is %4 x %5.")
                  .arg(platform_label)
                  .arg(recommended.size.width())
                  .arg(recommended.size.height())
                  .arg(sequence_size_.width())
                  .arg(sequence_size_.height()));
  }

  const QVector<double> standard_frame_rates{24.0, 25.0, 30.0, 50.0, 60.0};
  const auto standard_rate = std::any_of(
      standard_frame_rates.cbegin(), standard_frame_rates.cend(),
      [this](double rate) { return qAbs(sequence_frame_rate_ - rate) < 0.01; });
  if (has_active_timeline_ && !standard_rate) {
    add_issue(QStringLiteral("frame-rate"), QStringLiteral("warning"),
              QStringLiteral("Frame rate"),
              QStringLiteral("%1 fps is unusual for social delivery. Use 24, 25, 30, 50, or 60 fps.")
                  .arg(QString::number(sequence_frame_rate_, 'f', 2)));
  }
  if (has_active_timeline_ &&
      (export_container_ != QStringLiteral("mp4") || export_codec_ != QStringLiteral("h264"))) {
    format_repair_available = true;
    add_issue(QStringLiteral("codec"), QStringLiteral("error"),
              QStringLiteral("Codec"),
              QStringLiteral("%1 delivery requires an MP4 with H.264 video. Current output is %2 / %3.")
                  .arg(platform_label, export_container_.toUpper(), export_codec_.toUpper()));
  }
  if (has_active_timeline_ && color_space_.compare(QStringLiteral("Rec.709"), Qt::CaseInsensitive) != 0) {
    add_issue(QStringLiteral("gamut"), QStringLiteral("error"),
              QStringLiteral("Delivery gamut"),
              QStringLiteral("Convert the timeline from %1 to Rec.709 for predictable platform color.")
                  .arg(color_space_));
  }
  if (has_active_timeline_ && data_levels_.compare(QStringLiteral("Legal"), Qt::CaseInsensitive) != 0) {
    add_issue(QStringLiteral("data-levels"), QStringLiteral("warning"),
              QStringLiteral("Signal range"),
              QStringLiteral("Limited/legal data levels are recommended for H.264 social delivery."));
  }

  auto has_audio = false;
  auto title_safe_violations = 0;
  auto offline_media_count = 0;
  auto missing_font_count = 0;
  auto unavailable_effect_count = 0;
  const QSet<QString> supported_effects{
      QStringLiteral("Exposure"),
      QStringLiteral("Contrast"),
      QStringLiteral("Saturation"),
      QStringLiteral("Black & White"),
      QStringLiteral("Blur"),
      QStringLiteral("Fade"),
      QStringLiteral("Punch"),
  };
  QSet<QString> available_fonts;
  const auto available_font_list = QFontDatabase::families();
  available_fonts.reserve(available_font_list.size());
  for (const auto& family : available_font_list) {
    available_fonts.insert(family.toCaseFolded());
  }
  for (const auto& track : tracks_) {
    if (track.kind == TrackKind::Audio) {
      has_audio = has_audio || std::any_of(
          track.clips.cbegin(), track.clips.cend(),
          [](const Clip& clip) { return clip.has_audio; });
      continue;
    }
    for (const auto& clip : track.clips) {
      const auto media_requires_file =
          clip.media_type != QStringLiteral("title") &&
          clip.media_type != QStringLiteral("caption") &&
          clip.media_type != QStringLiteral("adjustment");
      if (media_requires_file &&
          (clip.file_path.isEmpty() || !QFileInfo::exists(clip.file_path))) {
        ++offline_media_count;
        add_issue(
            QStringLiteral("missing-media"), QStringLiteral("error"),
            QStringLiteral("Media offline"),
            QStringLiteral("%1 cannot be read from its source path.").arg(clip.display_label),
            QStringLiteral("Media"), QStringLiteral("Relink source media"),
            clip.clip_id, clip.file_path);
      }
      for (const auto& effect_name : clip.effect_stack) {
        if (supported_effects.contains(effect_name)) {
          continue;
        }
        ++unavailable_effect_count;
        add_issue(
            QStringLiteral("unsupported-effect"), QStringLiteral("error"),
            QStringLiteral("Effect unavailable"),
            QStringLiteral("%1 uses '%2', which this build cannot render.")
                .arg(clip.display_label, effect_name),
            QStringLiteral("Effect"), QStringLiteral("Remove or replace effect"),
            clip.clip_id);
      }
      if (!clip.color_lut_path.isEmpty() && !QFileInfo::exists(clip.color_lut_path)) {
        ++unavailable_effect_count;
        add_issue(
            QStringLiteral("missing-effect-resource"), QStringLiteral("error"),
            QStringLiteral("LUT file missing"),
            QStringLiteral("%1 cannot find its color LUT.").arg(clip.display_label),
            QStringLiteral("Effect"), QStringLiteral("Relink LUT"),
            clip.clip_id, clip.color_lut_path);
      }
      if ((clip.media_type == QStringLiteral("title") ||
           clip.media_type == QStringLiteral("caption")) &&
          !clip.title_font_family.isEmpty() &&
          !available_fonts.contains(clip.title_font_family.toCaseFolded())) {
        ++missing_font_count;
        add_issue(
            QStringLiteral("missing-font"), QStringLiteral("error"),
            QStringLiteral("Font unavailable"),
            QStringLiteral("%1 requires '%2'.")
                .arg(clip.display_label, clip.title_font_family),
            QStringLiteral("Font"), QStringLiteral("Install or replace font"),
            clip.clip_id);
      }
      if (clip.media_type != QStringLiteral("title")) {
        continue;
      }
      if (clip.title_position_x < 0.08 || clip.title_position_x > 0.92 ||
          clip.title_position_y < 0.08 || clip.title_position_y > 0.92) {
        ++title_safe_violations;
      }
    }
  }
  if (has_active_timeline_ && title_safe_violations > 0) {
    add_issue(QStringLiteral("title-safe"), QStringLiteral("warning"),
              QStringLiteral("Safe area"),
              QStringLiteral("%1 title clip%2 outside the central 84% title-safe area.")
                  .arg(title_safe_violations)
                  .arg(title_safe_violations == 1 ? QStringLiteral(" sits") : QStringLiteral("s sit")));
  }
  if (has_active_timeline_ && captionCount() == 0) {
    add_issue(QStringLiteral("captions"), QStringLiteral("warning"),
              QStringLiteral("Captions"),
              QStringLiteral("No caption track is present. Add captions or provide an SRT/VTT sidecar for silent viewing."));
  } else if (has_active_timeline_) {
    const auto caption_validation = validateCaptions(QStringLiteral("srt"));
    const auto caption_blocking = caption_validation.value(QStringLiteral("blockingCount")).toInt();
    const auto caption_warnings = caption_validation.value(QStringLiteral("warningCount")).toInt();
    if (caption_blocking > 0 || caption_warnings > 0) {
      add_issue(
          QStringLiteral("caption-validation"),
          caption_blocking > 0 ? QStringLiteral("error") : QStringLiteral("warning"),
          QStringLiteral("Caption validation"),
          QStringLiteral("%1 blocking and %2 warning caption issue%3 remain for SRT delivery.")
              .arg(caption_blocking)
              .arg(caption_warnings)
              .arg(caption_blocking + caption_warnings == 1 ? QString{} : QStringLiteral("s")),
          QStringLiteral("Captions"), QStringLiteral("Open Caption Tools and review each cue"));
    }
  }

  const auto visibility = trackVisibilityState();
  QVector<double> visible_cut_times;
  for (const auto& track : tracks_) {
    if (track.kind != TrackKind::Video ||
        !visibility.effective_by_track_id.value(track.track_id, track.visible) ||
        track.muted) {
      continue;
    }
    for (const auto& clip : track.clips) {
      if (clip.media_type != QStringLiteral("caption") && clip.start_seconds > 0.0) {
        visible_cut_times.push_back(clip.start_seconds);
      }
    }
  }
  std::sort(visible_cut_times.begin(), visible_cut_times.end());
  auto rapid_cut_window_count = 0;
  for (int index = 0; index < visible_cut_times.size(); ++index) {
    auto cuts_in_window = 1;
    for (int next = index + 1; next < visible_cut_times.size() &&
         visible_cut_times.at(next) - visible_cut_times.at(index) <= 1.0;
         ++next) {
      ++cuts_in_window;
    }
    if (cuts_in_window >= 3) {
      ++rapid_cut_window_count;
    }
  }
  if (has_active_timeline_ && rapid_cut_window_count > 0) {
    add_issue(
        QStringLiteral("flash-risk"), QStringLiteral("warning"),
        QStringLiteral("Flash-risk review"),
        QStringLiteral("%1 rapid-cut window%2 contain at least three picture changes in one second. This edit-graph screen cannot replace a frame-luminance accessibility test.")
            .arg(rapid_cut_window_count)
            .arg(rapid_cut_window_count == 1 ? QString{} : QStringLiteral("s")),
        QStringLiteral("Accessibility"),
        QStringLiteral("Review rapid cuts and run a photosensitive-epilepsy frame analysis before release"));
  }
  const auto loudness_result = loudnessAnalysisResult();
  if (has_active_timeline_ && has_audio && loudnessAnalysisBusy()) {
    add_issue(QStringLiteral("loudness-running"), QStringLiteral("warning"),
              QStringLiteral("Loudness"),
              QStringLiteral("Post-mix LUFS and true-peak analysis is still running."));
  } else if (has_active_timeline_ && has_audio && loudness_measured_) {
    if (!loudness_result.value(QStringLiteral("withinLoudnessTarget")).toBool()) {
      add_issue(QStringLiteral("loudness"), QStringLiteral("warning"),
                QStringLiteral("Loudness"),
                QStringLiteral("The post-mix program measures %1 LUFS; the %2 target is %3 LUFS ±1.")
                    .arg(QString::number(loudness_integrated_lufs_, 'f', 1), platform_label)
                    .arg(QString::number(target_lufs, 'f', 0)));
    }
    if (!loudness_result.value(QStringLiteral("truePeakPass")).toBool()) {
      add_issue(QStringLiteral("true-peak"), QStringLiteral("error"),
                QStringLiteral("True peak"),
                QStringLiteral("The post-mix true peak is %1 dBTP; keep it at or below -1 dBTP for encoded delivery.")
                    .arg(QString::number(loudness_true_peak_dbtp_, 'f', 1)));
    }
  } else if (has_active_timeline_ && has_audio) {
    add_issue(QStringLiteral("loudness-unmeasured"), QStringLiteral("warning"),
              QStringLiteral("Loudness"),
              QStringLiteral("Measure the post-mix program to verify %1 LUFS and peaks at or below -1 dBTP.")
                  .arg(QString::number(target_lufs, 'f', 0)));
  } else if (has_active_timeline_) {
    add_issue(QStringLiteral("audio"), QStringLiteral("warning"),
              QStringLiteral("Audio"), QStringLiteral("This timeline has no active audio program."));
  }

  const auto duration_seconds = qMax(0.0, totalDurationSeconds());
  const auto estimated_output_bytes = static_cast<qint64>(std::ceil(
      duration_seconds *
      (static_cast<double>(video_bitrate_mbps) * 1000000.0 / 8.0 +
       static_cast<double>(audio_bitrate_kbps) * 1000.0 / 8.0)));
  QDir().mkpath(timelineRendersRootPath());
  QStorageInfo delivery_storage(timelineRendersRootPath());
  delivery_storage.refresh();
  const auto free_disk_bytes = delivery_storage.isValid() && delivery_storage.isReady()
                                   ? delivery_storage.bytesAvailable()
                                   : -1;
  const auto required_disk_bytes = qMax<qint64>(
      512LL * 1024LL * 1024LL, estimated_output_bytes * 2);
  if (has_active_timeline_ && free_disk_bytes >= 0 && free_disk_bytes < required_disk_bytes) {
    add_issue(
        QStringLiteral("insufficient-disk"), QStringLiteral("error"),
        QStringLiteral("Not enough free space"),
        QStringLiteral("The destination has %1 MB free; this publish needs a %2 MB safety allowance.")
            .arg(free_disk_bytes / (1024LL * 1024LL))
            .arg(required_disk_bytes / (1024LL * 1024LL)),
        QStringLiteral("Storage"),
        QStringLiteral("Free disk space or change destination"),
        QString{}, delivery_storage.rootPath());
  }

  return QVariantMap{
      {QStringLiteral("schema"), QStringLiteral("timeline-delivery-preflight:v3")},
      {QStringLiteral("ok"), error_count == 0},
      {QStringLiteral("preset"), normalized_preset},
      {QStringLiteral("platformLabel"), platform_label},
      {QStringLiteral("recommendedVariant"), recommended_variant},
      {QStringLiteral("recommendedPresetKey"),
       normalized_preset == QStringLiteral("instagram") ? recommended_variant : normalized_preset},
      {QStringLiteral("recommendedFormat"), recommended.label + QStringLiteral(" ") + recommended.aspect_ratio},
      {QStringLiteral("formatRepairAvailable"), format_repair_available},
      {QStringLiteral("recommendedWidth"), recommended.size.width()},
      {QStringLiteral("recommendedHeight"), recommended.size.height()},
      {QStringLiteral("width"), sequence_size_.width()},
      {QStringLiteral("height"), sequence_size_.height()},
      {QStringLiteral("frameRate"), sequence_frame_rate_},
      {QStringLiteral("videoBitrateMbps"), video_bitrate_mbps},
      {QStringLiteral("audioBitrateKbps"), audio_bitrate_kbps},
      {QStringLiteral("targetLufs"), target_lufs},
      {QStringLiteral("captionCount"), captionCount()},
      {QStringLiteral("titleSafeViolationCount"), title_safe_violations},
      {QStringLiteral("offlineMediaCount"), offline_media_count},
      {QStringLiteral("missingFontCount"), missing_font_count},
      {QStringLiteral("unavailableEffectCount"), unavailable_effect_count},
      {QStringLiteral("rapidCutWindowCount"), rapid_cut_window_count},
      {QStringLiteral("estimatedOutputBytes"), estimated_output_bytes},
      {QStringLiteral("freeDiskBytes"), free_disk_bytes},
      {QStringLiteral("requiredDiskBytes"), required_disk_bytes},
      {QStringLiteral("loudnessMeasured"), loudness_measured_},
      {QStringLiteral("loudnessAnalysisBusy"), loudnessAnalysisBusy()},
      {QStringLiteral("loudnessResult"), loudness_result},
      {QStringLiteral("errorCount"), error_count},
      {QStringLiteral("warningCount"), warning_count},
      {QStringLiteral("issues"), issues},
  };
}

QVariantMap TimelineDocumentController::timelinePublishSummary(const QString& preset) const {
  const auto preflight = timelineDeliveryPreflight(preset);
  const auto output_name = timeline_id_.isEmpty()
                               ? QStringLiteral("timeline-preview")
                               : timeline_id_;
  const auto destination_path = saved_render_path_.isEmpty()
                                    ? QDir(timelineRendersRootPath()).filePath(
                                          QStringLiteral("%1.%2")
                                              .arg(output_name, export_container_))
                                    : saved_render_path_;
  const auto duration_seconds = qMax(0.0, totalDurationSeconds());
  return QVariantMap{
      {QStringLiteral("schema"), QStringLiteral("timeline-publish-summary:v1")},
      {QStringLiteral("format"),
       QStringLiteral("%1 · %2").arg(export_container_.toUpper(), export_codec_.toUpper())},
      {QStringLiteral("width"), sequence_size_.width()},
      {QStringLiteral("height"), sequence_size_.height()},
      {QStringLiteral("frameRate"), sequence_frame_rate_},
      {QStringLiteral("durationSeconds"), duration_seconds},
      {QStringLiteral("durationText"), formatDurationText(duration_seconds)},
      {QStringLiteral("rangeLabel"), QStringLiteral("Entire sequence")},
      {QStringLiteral("rangeStartSeconds"), 0.0},
      {QStringLiteral("rangeEndSeconds"), duration_seconds},
      {QStringLiteral("destinationPath"), destination_path},
      {QStringLiteral("destinationDirectory"), QFileInfo(destination_path).absolutePath()},
      {QStringLiteral("errorCount"), preflight.value(QStringLiteral("errorCount"))},
      {QStringLiteral("warningCount"), preflight.value(QStringLiteral("warningCount"))},
      {QStringLiteral("estimatedOutputBytes"), preflight.value(QStringLiteral("estimatedOutputBytes"))},
      {QStringLiteral("publishEnabled"),
       has_active_timeline_ && clipCount() > 0 &&
           preflight.value(QStringLiteral("errorCount")).toInt() == 0},
      {QStringLiteral("preflight"), preflight},
  };
}

QVariantMap TimelineDocumentController::timelineProjectHealth() const {
  QVariantList issues;
  auto blocking_count = 0;
  auto warning_count = 0;
  auto info_count = 0;
  QSet<QString> issue_identities;
  const auto add_issue = [&](const QString& key,
                             const QString& severity,
                             const QString& category,
                             const QString& label,
                             const QString& message,
                             const QString& item_id = QString(),
                             const QString& path = QString(),
                             const QString& repair = QString()) {
    const auto identity = key + QLatin1Char('|') + item_id + QLatin1Char('|') + path;
    if (issue_identities.contains(identity)) {
      return;
    }
    issue_identities.insert(identity);
    issues.push_back(QVariantMap{
        {QStringLiteral("key"), key},
        {QStringLiteral("severity"), severity},
        {QStringLiteral("category"), category},
        {QStringLiteral("label"), label},
        {QStringLiteral("message"), message},
        {QStringLiteral("itemId"), item_id},
        {QStringLiteral("path"), path},
        {QStringLiteral("repair"), repair},
    });
    if (severity == QStringLiteral("error")) {
      ++blocking_count;
    } else if (severity == QStringLiteral("warning")) {
      ++warning_count;
    } else {
      ++info_count;
    }
  };

  if (!has_active_timeline_) {
    add_issue(
        QStringLiteral("no-timeline"),
        QStringLiteral("error"),
        QStringLiteral("Project"),
        QStringLiteral("No timeline open"),
        QStringLiteral("Open or create a timeline before scanning project health."));
  }

  const QSet<QString> supported_effects{
      QStringLiteral("Exposure"),
      QStringLiteral("Contrast"),
      QStringLiteral("Saturation"),
      QStringLiteral("Black & White"),
      QStringLiteral("Blur"),
      QStringLiteral("Fade"),
      QStringLiteral("Punch"),
  };
  const auto available_font_list = QFontDatabase::families();
  QSet<QString> available_fonts;
  available_fonts.reserve(available_font_list.size());
  for (const auto& family : available_font_list) {
    available_fonts.insert(family.toCaseFolded());
  }

  qint64 source_bytes = 0;
  auto scanned_clip_count = 0;
  auto source_integrity_verified_count = 0;
  auto generated_integrity_verified_count = 0;
  auto integrity_mismatch_count = 0;
  auto integrity_untracked_count = 0;
  QSet<QString> source_integrity_checked_paths;
  QSet<QString> integrity_checked_paths;
  const auto check_generated_integrity = [&](const QString& path,
                                             const QString& item_id,
                                             const QString& label,
                                             const QString& repair) {
    const auto normalized = normalized_path(path);
    if (normalized.isEmpty() || !QFileInfo::exists(normalized) ||
        integrity_checked_paths.contains(normalized)) {
      return;
    }
    integrity_checked_paths.insert(normalized);
    const auto verification = verify_integrity_sidecar(normalized);
    if (verification.value(QStringLiteral("valid")).toBool()) {
      ++generated_integrity_verified_count;
      return;
    }
    if (!verification.value(QStringLiteral("tracked")).toBool()) {
      ++integrity_untracked_count;
      add_issue(
          QStringLiteral("generated-integrity-untracked"),
          QStringLiteral("warning"),
          QStringLiteral("Integrity"),
          QStringLiteral("Generated media has no checksum"),
          QStringLiteral("%1 predates integrity tracking and should be rebuilt before trusted delivery.")
              .arg(label),
          item_id,
          normalized,
          repair);
      return;
    }
    ++integrity_mismatch_count;
    add_issue(
        QStringLiteral("generated-integrity-mismatch"),
        QStringLiteral("warning"),
        QStringLiteral("Integrity"),
        QStringLiteral("Generated media checksum mismatch"),
        QStringLiteral("%1 changed after it was published. The original source remains authoritative.")
            .arg(label),
        item_id,
        normalized,
        repair);
  };
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      ++scanned_clip_count;
      const auto media_requires_file =
          clip.media_type != QStringLiteral("title") &&
          clip.media_type != QStringLiteral("caption") &&
          clip.media_type != QStringLiteral("adjustment");
      if (media_requires_file &&
          (clip.file_path.isEmpty() || !QFileInfo::exists(clip.file_path))) {
        add_issue(
            QStringLiteral("missing-media"),
            QStringLiteral("error"),
            QStringLiteral("Media"),
            QStringLiteral("Missing media"),
            QStringLiteral("%1 is offline. Relink it before editing or delivery.")
                .arg(clip.display_label),
            clip.clip_id,
            clip.file_path,
            QStringLiteral("Relink source media"));
      } else if (media_requires_file) {
        source_bytes += QFileInfo(clip.file_path).size();
        const auto normalized_source_path = normalized_path(clip.file_path);
        if (!source_integrity_checked_paths.contains(normalized_source_path)) {
          source_integrity_checked_paths.insert(normalized_source_path);
          const auto current_signature = media_identity_signature(clip.file_path);
          if (!clip.source_identity_signature.isEmpty() &&
              current_signature != clip.source_identity_signature) {
            ++integrity_mismatch_count;
            add_issue(
                QStringLiteral("source-integrity-mismatch"),
                QStringLiteral("error"),
                QStringLiteral("Integrity"),
                QStringLiteral("Source media changed"),
                QStringLiteral("%1 no longer matches the fast SHA-256 identity recorded at ingest or relink.")
                    .arg(clip.display_label),
                clip.clip_id,
                clip.file_path,
                QStringLiteral("Relink or explicitly re-ingest the changed source"));
          } else if (clip.source_integrity_status == QStringLiteral("mismatch")) {
            ++integrity_mismatch_count;
            add_issue(
                QStringLiteral("source-integrity-mismatch"),
                QStringLiteral("error"),
                QStringLiteral("Integrity"),
                QStringLiteral("Source media checksum mismatch"),
                QStringLiteral("%1 failed the background full-file SHA-256 audit; the ingest checksum remains authoritative.")
                    .arg(clip.display_label),
                clip.clip_id,
                clip.file_path,
                QStringLiteral("Relink or explicitly re-ingest the changed source"));
          } else if (!clip.source_content_sha256.isEmpty() &&
                     clip.source_integrity_status == QStringLiteral("verified")) {
            ++source_integrity_verified_count;
          } else {
            ++integrity_untracked_count;
            add_issue(
                QStringLiteral("source-integrity-pending"),
                QStringLiteral("warning"),
                QStringLiteral("Integrity"),
                QStringLiteral("Source checksum is still being verified"),
                QStringLiteral("%1 is queued for a non-blocking full-file SHA-256 audit.")
                    .arg(clip.display_label),
                clip.clip_id,
                clip.file_path,
                QStringLiteral("Keep the project open until background verification finishes"));
          }
        }
      }

      if (clip.proxy_status == QStringLiteral("ready") &&
          (clip.proxy_path.isEmpty() || !QFileInfo::exists(clip.proxy_path) ||
           QFileInfo(clip.proxy_path).size() <= 0)) {
        add_issue(
            QStringLiteral("invalid-proxy"),
            QStringLiteral("warning"),
            QStringLiteral("Proxy"),
            QStringLiteral("Proxy needs rebuild"),
            QStringLiteral("%1 points to a missing or empty proxy; originals remain authoritative.")
                .arg(clip.display_label),
            clip.clip_id,
            clip.proxy_path,
            QStringLiteral("Regenerate proxy"));
      }
      if (clip.proxy_status == QStringLiteral("ready")) {
        check_generated_integrity(
            clip.proxy_path, clip.clip_id,
            QStringLiteral("Proxy for %1").arg(clip.display_label),
            QStringLiteral("Regenerate proxy"));
      }

      const auto waveform_path = QUrl(clip.waveform_source).toLocalFile();
      if (!waveform_path.isEmpty() && QFileInfo::exists(waveform_path) &&
          QImage(waveform_path).isNull()) {
        add_issue(
            QStringLiteral("corrupt-waveform-cache"),
            QStringLiteral("warning"),
            QStringLiteral("Cache"),
            QStringLiteral("Waveform cache is damaged"),
            QStringLiteral("%1 has an unreadable waveform preview; source audio is unaffected.")
                .arg(clip.display_label),
            clip.clip_id,
            waveform_path,
            QStringLiteral("Rebuild waveform cache"));
      }
      if (!waveform_path.isEmpty()) {
        check_generated_integrity(
            waveform_path, clip.clip_id,
            QStringLiteral("Waveform for %1").arg(clip.display_label),
            QStringLiteral("Rebuild waveform cache"));
      }
      const auto poster_path = QUrl(clip.poster_source).toLocalFile();
      if (!poster_path.isEmpty() && path_is_inside_root(poster_path, poster_cache_root())) {
        check_generated_integrity(
            poster_path, clip.clip_id,
            QStringLiteral("Poster for %1").arg(clip.display_label),
            QStringLiteral("Rebuild poster cache"));
      }

      for (const auto& effect_name : clip.effect_stack) {
        if (!supported_effects.contains(effect_name)) {
          add_issue(
              QStringLiteral("unsupported-effect"),
              QStringLiteral("error"),
              QStringLiteral("Effect"),
              QStringLiteral("Effect unavailable"),
              QStringLiteral("%1 uses '%2', which this build cannot render.")
                  .arg(clip.display_label, effect_name),
              clip.clip_id,
              QString{},
              QStringLiteral("Remove or replace effect"));
        }
      }
      if (!clip.color_lut_path.isEmpty() && !QFileInfo::exists(clip.color_lut_path)) {
        add_issue(
            QStringLiteral("missing-effect-resource"),
            QStringLiteral("error"),
            QStringLiteral("Effect"),
            QStringLiteral("LUT file missing"),
            QStringLiteral("%1 cannot find its color LUT.").arg(clip.display_label),
            clip.clip_id,
            clip.color_lut_path,
            QStringLiteral("Relink LUT"));
      }

      if ((clip.media_type == QStringLiteral("title") ||
           clip.media_type == QStringLiteral("caption")) &&
          !clip.title_font_family.isEmpty() &&
          !available_fonts.contains(clip.title_font_family.toCaseFolded())) {
        add_issue(
            QStringLiteral("missing-font"),
            QStringLiteral("error"),
            QStringLiteral("Font"),
            QStringLiteral("Font unavailable"),
            QStringLiteral("%1 requires '%2'.").arg(clip.display_label, clip.title_font_family),
            clip.clip_id,
            QString{},
            QStringLiteral("Install or replace font"));
      }

      if (!clip.compound_render_path.isEmpty() && QFileInfo::exists(clip.compound_render_path) &&
          QFileInfo(clip.compound_render_path).size() <= 0) {
        add_issue(
            QStringLiteral("corrupt-compound-cache"),
            QStringLiteral("warning"),
            QStringLiteral("Cache"),
            QStringLiteral("Compound preview is damaged"),
            QStringLiteral("%1 has an empty compound render cache.").arg(clip.display_label),
            clip.clip_id,
            clip.compound_render_path,
            QStringLiteral("Regenerate compound preview"));
      }
      if (!clip.compound_render_path.isEmpty()) {
        check_generated_integrity(
            clip.compound_render_path, clip.clip_id,
            QStringLiteral("Compound render for %1").arg(clip.display_label),
            QStringLiteral("Regenerate compound preview"));
      }
      if (!clip.stabilization_render_path.isEmpty()) {
        check_generated_integrity(
            clip.stabilization_render_path, clip.clip_id,
            QStringLiteral("Stabilized render for %1").arg(clip.display_label),
            QStringLiteral("Rebuild stabilization"));
      }
      if (!clip.stabilization_preview_path.isEmpty()) {
        check_generated_integrity(
            clip.stabilization_preview_path, clip.clip_id,
            QStringLiteral("Stabilization preview for %1").arg(clip.display_label),
            QStringLiteral("Rebuild stabilization"));
      }
      if (!clip.stabilization_transform_path.isEmpty()) {
        check_generated_integrity(
            clip.stabilization_transform_path, clip.clip_id,
            QStringLiteral("Stabilization transform for %1").arg(clip.display_label),
            QStringLiteral("Rebuild stabilization"));
      }
    }
  }

  QSet<QString> checked_compound_paths;
  std::function<void(const QString&, QSet<QString>, int)> scan_compound;
  scan_compound = [&](const QString& path, QSet<QString> ancestors, int depth) {
    if (path.isEmpty()) {
      return;
    }
    const auto normalized = normalized_path(path);
    if (ancestors.contains(normalized)) {
      add_issue(
          QStringLiteral("compound-cycle"),
          QStringLiteral("error"),
          QStringLiteral("Nesting"),
          QStringLiteral("Compound cycle detected"),
          QStringLiteral("A compound timeline eventually contains itself."),
          QString{},
          normalized,
          QStringLiteral("Remove cyclic nesting"));
      return;
    }
    if (depth > 32) {
      add_issue(
          QStringLiteral("compound-depth"),
          QStringLiteral("error"),
          QStringLiteral("Nesting"),
          QStringLiteral("Compound nesting is too deep"),
          QStringLiteral("The nesting graph exceeds the safe 32-level traversal limit."),
          QString{},
          normalized,
          QStringLiteral("Flatten nested compounds"));
      return;
    }
    if (checked_compound_paths.contains(normalized)) {
      return;
    }
    const auto object = read_timeline_document_object(normalized);
    if (object.isEmpty()) {
      add_issue(
          QStringLiteral("invalid-compound"),
          QStringLiteral("error"),
          QStringLiteral("Nesting"),
          QStringLiteral("Compound timeline unavailable"),
          QStringLiteral("A nested timeline is missing or malformed."),
          QString{},
          normalized,
          QStringLiteral("Relink or rebuild compound"));
      return;
    }
    checked_compound_paths.insert(normalized);
    ancestors.insert(normalized);
    for (const auto& track_value : object.value(QStringLiteral("tracks")).toArray()) {
      for (const auto& clip_value : track_value.toObject().value(QStringLiteral("clips")).toArray()) {
        const auto child_path = clip_value.toObject()
                                    .value(QStringLiteral("compoundDocumentPath"))
                                    .toString();
        if (!child_path.isEmpty()) {
          scan_compound(child_path, ancestors, depth + 1);
        }
      }
    }
  };
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (!clip.compound_document_path.isEmpty()) {
        scan_compound(clip.compound_document_path, {}, 0);
      }
    }
  }

  for (const auto& task : expectedRenderCacheTasks()) {
    if (QFileInfo::exists(task.output_path) && QFileInfo(task.output_path).size() <= 0) {
      add_issue(
          QStringLiteral("corrupt-render-cache"),
          QStringLiteral("warning"),
          QStringLiteral("Cache"),
          QStringLiteral("Preview cache is damaged"),
          QStringLiteral("A rendered preview segment is empty; delivery media is unaffected."),
          task.signature,
          task.output_path,
          QStringLiteral("Rebuild preview cache"));
    }
    if (QFileInfo::exists(task.output_path)) {
      check_generated_integrity(
          task.output_path, task.signature,
          QStringLiteral("Preview cache range"),
          QStringLiteral("Rebuild preview cache"));
    }
  }
  if (!saved_render_path_.isEmpty() && QFileInfo::exists(saved_render_path_)) {
    check_generated_integrity(
        saved_render_path_, timeline_id_,
        QStringLiteral("Saved delivery output"),
        QStringLiteral("Render the delivery again"));
  }

  const auto capabilities = deliveryCapabilities();
  if (!capabilities.value(QStringLiteral("ffmpegAvailable")).toBool()) {
    add_issue(
        QStringLiteral("renderer-unavailable"),
        QStringLiteral("error"),
        QStringLiteral("Delivery"),
        QStringLiteral("Renderer unavailable"),
        QStringLiteral("FFmpeg is not installed or cannot be found."),
        QString{},
        QString{},
        QStringLiteral("Install or configure FFmpeg"));
  }
  if (deliverySettings().value(QStringLiteral("hardwareFallback")).toBool()) {
    add_issue(
        QStringLiteral("hardware-encoder-fallback"),
        QStringLiteral("warning"),
        QStringLiteral("Delivery"),
        QStringLiteral("Hardware encoder unavailable"),
        QStringLiteral("The requested hardware path will fall back to software encoding."),
        QString{},
        QString{},
        QStringLiteral("Use Auto or Software encoder"));
  }
  if ((!export_alpha_ &&
       (export_container_ != QStringLiteral("mp4") || export_codec_ != QStringLiteral("h264"))) ||
      (export_alpha_ &&
       (export_container_ != QStringLiteral("mov") || export_codec_ != QStringLiteral("prores")))) {
    add_issue(
        QStringLiteral("unsupported-delivery-settings"),
        QStringLiteral("error"),
        QStringLiteral("Delivery"),
        QStringLiteral("Output combination unsupported"),
        QStringLiteral("The selected container, codec, and alpha settings cannot be rendered together."),
        QString{},
        QString{},
        QStringLiteral("Reset delivery settings"));
  }

  QDir().mkpath(timelineDocumentsRootPath());
  QStorageInfo storage(timelineDocumentsRootPath());
  storage.refresh();
  const auto minimum_free_bytes = qMax<qint64>(
      1024LL * 1024LL * 1024LL,
      qMin<qint64>(source_bytes, 10LL * 1024LL * 1024LL * 1024LL));
  const auto free_bytes = storage.isValid() && storage.isReady() ? storage.bytesAvailable() : -1;
  if (free_bytes >= 0 && free_bytes < minimum_free_bytes) {
    add_issue(
        QStringLiteral("insufficient-disk"),
        QStringLiteral("error"),
        QStringLiteral("Storage"),
        QStringLiteral("Low disk space"),
        QStringLiteral("Only %1 MB is free; keep at least %2 MB available for safe saves and delivery.")
            .arg(free_bytes / (1024LL * 1024LL))
            .arg(minimum_free_bytes / (1024LL * 1024LL)),
        QString{},
        storage.rootPath(),
        QStringLiteral("Free disk space or change destination"));
  }

  return QVariantMap{
      {QStringLiteral("ok"), blocking_count == 0},
      {QStringLiteral("scannedAt"), QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)},
      {QStringLiteral("timelineName"), timeline_name_},
      {QStringLiteral("scannedClipCount"), scanned_clip_count},
      {QStringLiteral("blockingCount"), blocking_count},
      {QStringLiteral("warningCount"), warning_count},
      {QStringLiteral("infoCount"), info_count},
      {QStringLiteral("freeDiskBytes"), free_bytes},
      {QStringLiteral("requiredFreeDiskBytes"), minimum_free_bytes},
      {QStringLiteral("documentHash"), deterministicDocumentHash()},
      {QStringLiteral("integritySchema"), QStringLiteral("timeline-media-integrity:v1")},
      {QStringLiteral("sourceIdentityAlgorithm"), QStringLiteral("sha256-full-v1")},
      {QStringLiteral("sourceFastIdentityAlgorithm"), QStringLiteral("sha256-size-head-tail-v1")},
      {QStringLiteral("generatedMediaAlgorithm"), QStringLiteral("sha256-full-v1")},
      {QStringLiteral("sourceIntegrityVerifiedCount"), source_integrity_verified_count},
      {QStringLiteral("generatedIntegrityVerifiedCount"), generated_integrity_verified_count},
      {QStringLiteral("integrityMismatchCount"), integrity_mismatch_count},
      {QStringLiteral("integrityUntrackedCount"), integrity_untracked_count},
      {QStringLiteral("issues"), issues},
  };
}

QString TimelineDocumentController::deterministicDocumentHash() const {
  return has_active_timeline_ ? stable_timeline_document_hash(documentObject()) : QString{};
}

QString TimelineDocumentController::agentTaskDocumentId() const {
  return has_active_timeline_ && !timeline_id_.isEmpty() ? QStringLiteral("timeline:") + timeline_id_ : QString{};
}

bool TimelineDocumentController::agentTaskDocumentReady() const {
  return has_active_timeline_ && !continuous_edit_active_ && !timelineSaveInProgress() &&
      !transcriptionBusy() && !beatAnalysisBusy() && !silenceAnalysisBusy() && !loudnessAnalysisBusy() &&
      !autoReframeBusy() && !stabilizationAnalysisBusy() && !mediaAnalysisBusy() && !renderCacheBusy();
}

QByteArray TimelineDocumentController::agentTaskDocumentState() const {
  if (!agentTaskDocumentReady()) return {};
  auto document = documentObject();
  document.remove(QStringLiteral("updatedAt"));
  return QJsonDocument(document).toJson(QJsonDocument::Compact);
}

QVariantMap TimelineDocumentController::inspectAgentDocument() const {
  return {{"ok", true}, {"resourceId", agentTaskDocumentId()}, {"ready", agentTaskDocumentReady()},
      {"name", timeline_name_}, {"documentHash", deterministicDocumentHash()},
      {"clips", clips()}, {"tracks", sequenceTracks()},
      {"width", sequence_size_.width()}, {"height", sequence_size_.height()},
      {"frameRate", sequence_frame_rate_}};
}

bool TimelineDocumentController::restoreAgentTaskDocument(const QByteArray& state) {
  if (!agentTaskDocumentReady()) return false;
  QJsonParseError error;
  const auto parsed = QJsonDocument::fromJson(state, &error);
  const auto document = parsed.object();
  if (error.error != QJsonParseError::NoError || !parsed.isObject() ||
      document.value(QStringLiteral("timelineId")).toString() != timeline_id_ ||
      !document.value(QStringLiteral("tracks")).isArray() ||
      !document.value(QStringLiteral("sequenceFormat")).isObject()) return false;
  auto undo = undo_stack_;
  undo.append(captureSnapshot());
  const auto saved_path = saved_document_path_;
  if (!loadDocumentObject(document, saved_path, false)) return false;
  saved_document_path_ = saved_path;
  undo_stack_ = std::move(undo);
  while (undo_stack_.size() > maxUndoDepthForCurrentProject()) undo_stack_.removeFirst();
  redo_stack_.clear();
  setDirty(true);
  emit undoStateChanged();
  return agentTaskDocumentState() == state;
}

QVariantMap TimelineDocumentController::timelineDeterminismFingerprint(
    const QString& render_path) const {
  const auto hash_file = [](const QString& path) {
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) {
      return QString{};
    }
    QCryptographicHash hash(QCryptographicHash::Sha256);
    while (!file.atEnd()) {
      hash.addData(file.read(1024 * 1024));
    }
    return QString::fromLatin1(hash.result().toHex());
  };
  const auto hash_decoded_stream = [this](const QString& ffmpeg,
                                      const QString& path,
                                      const QString& stream_selector) {
    if (ffmpeg.isEmpty() || path.isEmpty()) {
      return QString{};
    }
    QProcess process;
    process.start(
        ffmpeg,
        {QStringLiteral("-v"), QStringLiteral("error"),
         QStringLiteral("-i"), path,
         QStringLiteral("-map"), stream_selector,
         stream_selector.startsWith(QStringLiteral("0:v")) ? QStringLiteral("-an")
                                                            : QStringLiteral("-vn"),
         QStringLiteral("-f"), QStringLiteral("framemd5"), QStringLiteral("pipe:1")});
    if (!cancellable_process_succeeded(&process, [this]() { return renderCancellationRequested(); })) {
      return QString{};
    }
    return sha256_hex(process.readAllStandardOutput());
  };

  const auto active_document_hash = deterministicDocumentHash();
  const auto saved_document = read_timeline_document_object(saved_document_path_);
  const auto saved_document_hash = saved_document.isEmpty()
                                       ? QString{}
                                       : stable_timeline_document_hash(saved_document);
  const auto normalized_render_path = render_path.trimmed().isEmpty()
                                          ? saved_render_path_
                                          : normalized_path(render_path);
  const auto render_exists = QFileInfo::exists(normalized_render_path);
  const auto ffmpeg = QStandardPaths::findExecutable(QStringLiteral("ffmpeg"));
  const auto render_file_hash = render_exists ? hash_file(normalized_render_path) : QString{};
  const auto video_frame_hash = render_exists
                                    ? hash_decoded_stream(
                                          ffmpeg,
                                          normalized_render_path,
                                          QStringLiteral("0:v:0"))
                                    : QString{};
  const auto audio_frame_hash = render_exists
                                    ? hash_decoded_stream(
                                          ffmpeg,
                                          normalized_render_path,
                                          QStringLiteral("0:a:0?"))
                                    : QString{};
  const QJsonObject combined{
      {QStringLiteral("documentHash"), active_document_hash},
      {QStringLiteral("videoFrameHash"), video_frame_hash},
      {QStringLiteral("audioFrameHash"), audio_frame_hash},
  };
  return QVariantMap{
      {QStringLiteral("schema"), QStringLiteral("timeline-determinism:v1")},
      {QStringLiteral("documentHash"), active_document_hash},
      {QStringLiteral("savedDocumentHash"), saved_document_hash},
      {QStringLiteral("savedDocumentMatches"),
       !active_document_hash.isEmpty() && active_document_hash == saved_document_hash},
      {QStringLiteral("renderPath"), normalized_render_path},
      {QStringLiteral("renderExists"), render_exists},
      {QStringLiteral("renderFileHash"), render_file_hash},
      {QStringLiteral("videoFrameHash"), video_frame_hash},
      {QStringLiteral("audioFrameHash"), audio_frame_hash},
      {QStringLiteral("combinedHash"), sha256_hex(compact_json(combined))},
      {QStringLiteral("valid"),
       !active_document_hash.isEmpty() &&
           (!render_exists || !video_frame_hash.isEmpty())},
  };
}

