QString TimelineDocumentController::renderCacheSignature(
    double start_seconds,
    double end_seconds,
    const QJsonObject& document) const {
  auto root = document;
  root.remove(QStringLiteral("name"));
  root.remove(QStringLiteral("createdAt"));
  root.remove(QStringLiteral("updatedAt"));
  root.remove(QStringLiteral("renderPath"));
  root.remove(QStringLiteral("posterPath"));
  root.remove(QStringLiteral("activeTool"));
  root.remove(QStringLiteral("editMode"));
  root.remove(QStringLiteral("linkedSelectionEnabled"));
  root.remove(QStringLiteral("projectBinding"));
  root.remove(QStringLiteral("markers"));
  root.remove(QStringLiteral("clips"));
  // Preview ranges are project-owned. Keeping the timeline identity in the
  // signature prevents an explicit per-project cleanup from evicting an
  // identical edit that belongs to another saved project.
  root.insert(QStringLiteral("cacheVersion"), 4);
  root.insert(QStringLiteral("rangeStart"), start_seconds);
  root.insert(QStringLiteral("rangeEnd"), end_seconds);

  QJsonArray filtered_tracks;
  const auto source_tracks = root.value(QStringLiteral("tracks")).toArray();
  for (const auto& track_value : source_tracks) {
    auto track = track_value.toObject();
    track.remove(QStringLiteral("trackId"));
    track.remove(QStringLiteral("displayLabel"));
    track.remove(QStringLiteral("locked"));
    track.remove(QStringLiteral("targeted"));
    QJsonArray filtered_clips;
    for (const auto& clip_value : track.value(QStringLiteral("clips")).toArray()) {
      auto clip = clip_value.toObject();
      const auto clip_start = clip.value(QStringLiteral("startSeconds")).toDouble();
      const auto clip_duration = qMax(
          0.0,
          clip.value(QStringLiteral("trimEndSeconds")).toDouble() -
              clip.value(QStringLiteral("trimStartSeconds")).toDouble());
      const auto clip_end = clip_start + clip_duration;
      const auto transition_preroll = qMax(
          0.0, clip.value(QStringLiteral("transitionInSeconds")).toDouble());
      if (clip_end <= start_seconds + kBoundaryEpsilon ||
          clip_start - transition_preroll >= end_seconds - kBoundaryEpsilon) {
        continue;
      }
      const QFileInfo source_info(clip.value(QStringLiteral("filePath")).toString());
      clip.insert(QStringLiteral("sourceSize"), source_info.exists() ? source_info.size() : -1);
      clip.insert(
          QStringLiteral("sourceModifiedMs"),
          source_info.exists() ? source_info.lastModified().toMSecsSinceEpoch() : -1);
      const QFileInfo color_lut_info(
          clip.value(QStringLiteral("colorLutPath")).toString());
      clip.insert(
          QStringLiteral("colorLutFileSize"),
          color_lut_info.exists() ? color_lut_info.size() : -1);
      clip.insert(
          QStringLiteral("colorLutFileModifiedMs"),
          color_lut_info.exists()
              ? color_lut_info.lastModified().toMSecsSinceEpoch()
              : -1);
      clip.remove(QStringLiteral("assetId"));
      clip.remove(QStringLiteral("displayLabel"));
      clip.remove(QStringLiteral("posterSource"));
      clip.remove(QStringLiteral("linkedGroupId"));
      clip.remove(QStringLiteral("waveformSource"));
      clip.remove(QStringLiteral("sourceContentSha256"));
      clip.remove(QStringLiteral("proxyPath"));
      clip.remove(QStringLiteral("proxyEnabled"));
      filtered_clips.push_back(clip);
    }
    track.insert(QStringLiteral("clips"), filtered_clips);
    filtered_tracks.push_back(track);
  }
  root.insert(QStringLiteral("tracks"), filtered_tracks);
  const auto digest = QCryptographicHash::hash(
      QJsonDocument(root).toJson(QJsonDocument::Compact), QCryptographicHash::Sha256).toHex();
  return QString::fromLatin1(digest);
}

QVector<TimelineDocumentController::RenderCacheTask>
TimelineDocumentController::expectedRenderCacheTasks() const {
  if (!render_cache_tasks_dirty_) {
    return render_cache_tasks_cache_;
  }
  QVector<RenderCacheTask> tasks;
  const auto duration = totalDurationSeconds();
  const auto document = documentObject();
  for (auto start = 0.0; start < duration - kBoundaryEpsilon;
       start += kRenderCacheSegmentSeconds) {
    const auto end = qMin(duration, start + kRenderCacheSegmentSeconds);
    const auto signature = renderCacheSignature(start, end, document);
    tasks.push_back({
        start,
        end,
        signature,
        QDir(render_cache_root()).filePath(
            QStringLiteral("%1-%2.mp4").arg(timeline_id_, signature)),
    });
  }
  render_cache_tasks_cache_ = tasks;
  render_cache_tasks_dirty_ = false;
  return render_cache_tasks_cache_;
}

QString TimelineDocumentController::renderCacheRevisionIdentity() const {
  QCryptographicHash hash(QCryptographicHash::Sha256);
  hash.addData(QByteArrayLiteral("timeline-render-cache-revision-v1"));
  for (const auto& task : expectedRenderCacheTasks()) {
    hash.addData(QByteArray::number(task.start_seconds, 'f', 6));
    hash.addData(QByteArrayLiteral(":"));
    hash.addData(QByteArray::number(task.end_seconds, 'f', 6));
    hash.addData(QByteArrayLiteral(":"));
    hash.addData(task.signature.toUtf8());
    hash.addData(QByteArrayLiteral("\n"));
  }
  return QString::fromLatin1(hash.result().toHex());
}

QVariantList TimelineDocumentController::renderCacheRanges() const {
  QVariantList values;
  const auto tasks = expectedRenderCacheTasks();
  QSet<QString> pending_signatures;
  for (const auto& task : render_cache_pending_tasks_) {
    pending_signatures.insert(task.signature);
  }
  values.reserve(tasks.size());
  for (const auto& task : tasks) {
    const auto ready = QFileInfo::exists(task.output_path);
    const auto pending = pending_signatures.contains(task.signature);
    const auto generating = renderCacheBusy() && render_cache_task_index_ >= 0 &&
                            render_cache_task_index_ < render_cache_pending_tasks_.size() &&
                            render_cache_pending_tasks_.at(render_cache_task_index_).signature == task.signature;
    QVariantMap value;
    value.insert(QStringLiteral("startSeconds"), task.start_seconds);
    value.insert(QStringLiteral("endSeconds"), task.end_seconds);
    value.insert(QStringLiteral("durationSeconds"), task.end_seconds - task.start_seconds);
    value.insert(QStringLiteral("signature"), task.signature);
    value.insert(QStringLiteral("sourceUrl"), ready ? QUrl::fromLocalFile(task.output_path).toString() : QString{});
    value.insert(QStringLiteral("ready"), ready);
    value.insert(
        QStringLiteral("status"),
        ready ? QStringLiteral("ready")
              : generating ? QStringLiteral("generating")
                           : pending ? QStringLiteral("queued") : QStringLiteral("missing"));
    values.push_back(value);
  }
  return values;
}

