void TimelineDocumentController::recordStaleResultDiscard(
    const QString& workflow,
    const QString& requested_revision,
    const QString& current_revision,
    const QString& affected_item_id) {
  ++stale_result_discard_count_;
  stale_result_last_workflow_ = workflow;
  stale_result_last_requested_revision_ = requested_revision;
  stale_result_last_current_revision_ = current_revision;
  stale_result_last_affected_item_id_ = affected_item_id;
  emit staleResultStateChanged();
}

void TimelineDocumentController::setPhotoWorkIntent(
    bool visible, bool interaction_active, const QString& asset_id) {
  WorkerQueueRegistry::publishUserIntent(QStringLiteral("edit"), visible, false,
      interaction_active, visible ? QStringList{asset_id} : QStringList{}, asset_id);
  reprioritizeBackgroundWorkQueues();
  if (!shouldDeferBackgroundWork(QStringLiteral("proxy"))) resumeDeferredBackgroundWork();
}

void TimelineDocumentController::setBackgroundWorkIntent(
    bool workspace_visible,
    bool interaction_active,
    const QStringList& visible_clip_ids) {
  QSet<QString> normalized_visible_ids;
  for (const auto& clip_id : visible_clip_ids) {
    const auto normalized = clip_id.trimmed();
    if (!normalized.isEmpty()) {
      normalized_visible_ids.insert(normalized);
    }
  }
  const auto published_playback_active = workspace_visible && sequence_playing_;
  const auto changed = background_work_workspace_visible_ != workspace_visible ||
                       background_work_playback_active_ != published_playback_active ||
                       background_work_interaction_active_ != interaction_active ||
                       background_work_visible_clip_ids_ != normalized_visible_ids;
  background_work_workspace_visible_ = workspace_visible;
  background_work_playback_active_ = published_playback_active;
  background_work_interaction_active_ = workspace_visible && interaction_active;
  background_work_visible_clip_ids_ = workspace_visible
                                          ? normalized_visible_ids
                                          : QSet<QString>{};
  WorkerQueueRegistry::publishUserIntent(
      QStringLiteral("timeline"),
      background_work_workspace_visible_,
      sequence_playing_,
      background_work_interaction_active_,
      background_work_visible_clip_ids_.values(),
      selected_clip_id_);
  ++background_work_intent_generation_;
  reprioritizeBackgroundWorkQueues();
  if (shouldDeferBackgroundWork(QStringLiteral("proxy"))) {
    incremental_load_timer_.stop();
  } else {
    resumeDeferredBackgroundWork();
  }
  if (changed) {
    emit backgroundWorkPriorityChanged();
    emit mediaAnalysisChanged();
    emit incrementalLoadChanged();
  }
}

bool TimelineDocumentController::shouldDeferBackgroundWork(
    const QString& workflow,
    const QString& affected_clip_id) const {
  if (cache_pressure_level_ == QStringLiteral("critical")) {
    return true;
  }
  return WorkerQueueRegistry::shouldDefer(
      workflow, QStringLiteral("timeline"), affected_clip_id);
}

int TimelineDocumentController::backgroundWorkRankForClip(
    const QString& clip_id) const {
  const auto normalized = clip_id.trimmed();
  if (!normalized.isEmpty() && normalized == selected_clip_id_) {
    return 0;
  }
  if (!normalized.isEmpty() && background_work_visible_clip_ids_.contains(normalized)) {
    return 1;
  }
  return normalized.isEmpty() ? 3 : 2;
}

QString TimelineDocumentController::clipIdForMediaPath(
    const QString& file_path) const {
  const auto normalized = normalized_path(file_path);
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (normalized_path(clip.file_path) == normalized) {
        return clip.clip_id;
      }
    }
  }
  if (has_source_clip_ && normalized_path(source_clip_.file_path) == normalized) {
    return source_clip_.clip_id;
  }
  return {};
}

void TimelineDocumentController::reprioritizeBackgroundWorkQueues() {
  const auto clip_less = [this](const QString& left, const QString& right) {
    return backgroundWorkRankForClip(left) < backgroundWorkRankForClip(right);
  };
  std::stable_sort(
      deferred_media_hydration_queue_.begin(),
      deferred_media_hydration_queue_.end(),
      [this](const auto& left, const auto& right) {
        return backgroundWorkRankForClip(left.clip_id) <
               backgroundWorkRankForClip(right.clip_id);
      });
  std::stable_sort(
      media_analysis_queue_.begin(), media_analysis_queue_.end(),
      [this](const auto& left, const auto& right) {
        return backgroundWorkRankForClip(clipIdForMediaPath(left.file_path)) <
               backgroundWorkRankForClip(clipIdForMediaPath(right.file_path));
      });
  std::stable_sort(
      source_integrity_queue_.begin(), source_integrity_queue_.end(),
      [this](const auto& left, const auto& right) {
        return backgroundWorkRankForClip(clipIdForMediaPath(left.file_path)) <
               backgroundWorkRankForClip(clipIdForMediaPath(right.file_path));
      });
  std::stable_sort(
      poster_request_queue_.begin(), poster_request_queue_.end(),
      [this](const auto& left, const auto& right) {
        return backgroundWorkRankForClip(clipIdForMediaPath(left.file_path)) <
               backgroundWorkRankForClip(clipIdForMediaPath(right.file_path));
      });
  std::stable_sort(
      waveform_request_queue_.begin(), waveform_request_queue_.end(),
      [this](const auto& left, const auto& right) {
        return backgroundWorkRankForClip(left.clip_id) <
               backgroundWorkRankForClip(right.clip_id);
      });
  std::stable_sort(
      proxy_generation_queue_.begin(), proxy_generation_queue_.end(), clip_less);
  std::stable_sort(
      silence_analysis_queue_.begin(), silence_analysis_queue_.end(),
      [this](const auto& left, const auto& right) {
        return backgroundWorkRankForClip(left.clip_id) <
               backgroundWorkRankForClip(right.clip_id);
      });
  std::stable_sort(
      transcription_queue_.begin(), transcription_queue_.end(),
      [this](const auto& left, const auto& right) {
        return backgroundWorkRankForClip(clipIdForMediaPath(left.file_path)) <
               backgroundWorkRankForClip(clipIdForMediaPath(right.file_path));
      });
  std::stable_sort(
      beat_analysis_queue_.begin(), beat_analysis_queue_.end(),
      [this](const auto& left, const auto& right) {
        return backgroundWorkRankForClip(clipIdForMediaPath(left)) <
               backgroundWorkRankForClip(clipIdForMediaPath(right));
      });
  std::stable_sort(
      compound_render_queue_.begin(), compound_render_queue_.end(),
      [this](const auto& left, const auto& right) {
        return backgroundWorkRankForClip(left.clip_id) <
               backgroundWorkRankForClip(right.clip_id);
      });
  std::stable_sort(
      render_cache_pending_tasks_.begin(), render_cache_pending_tasks_.end(),
      [this](const auto& left, const auto& right) {
        const auto left_visible = sequence_playhead_seconds_ >= left.start_seconds &&
                                  sequence_playhead_seconds_ < left.end_seconds;
        const auto right_visible = sequence_playhead_seconds_ >= right.start_seconds &&
                                   sequence_playhead_seconds_ < right.end_seconds;
        return left_visible && !right_visible;
      });
}

void TimelineDocumentController::resumeDeferredBackgroundWork() {
  reprioritizeBackgroundWorkQueues();
  if (!deferred_media_hydration_queue_.isEmpty() &&
      !incremental_load_timer_.isActive()) {
    incremental_load_timer_.start();
  }
  startNextSourceIntegrity();
  startNextMediaAnalysis();
  startNextVideoPoster();
  startNextAudioWaveform();
  startNextProxyGeneration();
  startNextSilenceAnalysis();
  startNextTranscription();
  startNextBeatAnalysis();
  if (render_cache_status_ == QStringLiteral("queued") &&
      render_cache_process_ == nullptr && render_cache_task_index_ == -2) {
    render_cache_status_ = QStringLiteral("idle");
    (void)generateRenderCache();
  } else if (render_cache_process_ != nullptr && render_cache_task_index_ >= 0) {
    startNextRenderCacheTask();
  }
  if (compound_render_process_ == nullptr && !compound_render_queue_.isEmpty()) {
    const auto next = compound_render_queue_.takeFirst();
    QTimer::singleShot(0, this, [this, next]() {
      (void)startCompoundRender(next.clip_id, next.document_path, next.render_path);
    });
  }
}

QString TimelineDocumentController::renderCachePlaybackSourceUrl() const {
  const auto playhead = sequence_playhead_seconds_;
  for (const auto& task : expectedRenderCacheTasks()) {
    const auto contains_playhead = playhead + kBoundaryEpsilon >= task.start_seconds &&
                                   (playhead < task.end_seconds - kBoundaryEpsilon ||
                                    qAbs(playhead - totalDurationSeconds()) <= kBoundaryEpsilon);
    if (contains_playhead && QFileInfo::exists(task.output_path)) {
      return QUrl::fromLocalFile(task.output_path).toString();
    }
  }
  return {};
}

double TimelineDocumentController::renderCachePlaybackStartSeconds() const {
  const auto playhead = sequence_playhead_seconds_;
  for (const auto& task : expectedRenderCacheTasks()) {
    if (playhead + kBoundaryEpsilon >= task.start_seconds &&
        (playhead < task.end_seconds - kBoundaryEpsilon ||
         qAbs(playhead - totalDurationSeconds()) <= kBoundaryEpsilon) &&
        QFileInfo::exists(task.output_path)) {
      return task.start_seconds;
    }
  }
  return 0.0;
}

