QVariantList TimelineDocumentController::sourceTapeItems() const {
  QVariantList items;
  items.reserve(source_tape_items_.size());
  auto reel_start = 0.0;
  for (int index = 0; index < source_tape_items_.size(); ++index) {
    const auto& item = source_tape_items_.at(index);
    const auto item_in = index == source_tape_index_ && has_source_clip_
                             ? source_in_seconds_
                             : item.source_in_seconds;
    const auto item_out = index == source_tape_index_ && has_source_clip_
                              ? source_out_seconds_
                              : item.source_out_seconds;
    items.push_back(QVariantMap{
        {QStringLiteral("index"), index},
        {QStringLiteral("assetId"), item.asset_id},
        {QStringLiteral("filePath"), item.file_path},
        {QStringLiteral("displayLabel"), item.display_label},
        {QStringLiteral("posterSource"), item.poster_source},
        {QStringLiteral("mediaType"), item.media_type},
        {QStringLiteral("durationSeconds"), item.duration_seconds},
        {QStringLiteral("sourceInSeconds"), item_in},
        {QStringLiteral("sourceOutSeconds"), item_out},
        {QStringLiteral("reelStartSeconds"), reel_start},
        {QStringLiteral("current"), index == source_tape_index_},
    });
    reel_start += item.duration_seconds;
  }
  return items;
}

double TimelineDocumentController::sourceTapeDurationSeconds() const {
  auto duration = 0.0;
  for (const auto& item : source_tape_items_) {
    duration += item.duration_seconds;
  }
  return duration;
}

