bool TimelineDocumentController::validateSelectedTrimMutation(
    bool ripple,
    double ripple_boundary_seconds,
    double ripple_delta_seconds) {
  const auto ref = selectedClipRef();
  const auto* track = trackAt(ref.track_index);
  const auto* clip = clipAt(ref);
  if (track == nullptr || clip == nullptr) {
    return false;
  }
  if (track->locked) {
    setStatus(QStringLiteral("Unlock %1 before trimming its clip.").arg(track->display_label));
    return false;
  }

  if (track->kind == TrackKind::Video && clip->has_audio && !clip->audio_detached) {
    const auto lane_index = resolvedAudioLane(*clip, track->lane_index);
    const auto* audio_track = audioTrackForLane(lane_index);
    if (audio_track != nullptr && audio_track->locked) {
      setStatus(QStringLiteral("Unlock %1 before trimming linked audio.")
                    .arg(audio_track->display_label));
      return false;
    }
  }

  if (ripple && qAbs(ripple_delta_seconds) > kBoundaryEpsilon) {
    for (const auto& affected_track : tracks_) {
      if (!affected_track.locked) {
        continue;
      }
      const auto has_shifted_clip = std::any_of(
          affected_track.clips.cbegin(), affected_track.clips.cend(),
          [clip, ripple_boundary_seconds](const Clip& candidate) {
            return candidate.clip_id != clip->clip_id &&
                   candidate.start_seconds >=
                       ripple_boundary_seconds - kBoundaryEpsilon;
          });
      if (has_shifted_clip) {
        setStatus(QStringLiteral("Unlock %1 before ripple trimming; clips on that track would move.")
                      .arg(affected_track.display_label));
        return false;
      }
    }
  }
  return true;
}

bool TimelineDocumentController::detachSelectedClipAudio(bool push_undo_snapshot) {
  const auto selected_ref = selectedClipRef();
  auto* video_track = trackAt(selected_ref.track_index);
  auto* video_clip = clipAt(selected_ref);
  if (video_track == nullptr || video_clip == nullptr || video_track->kind != TrackKind::Video ||
      !video_clip->has_audio || video_clip->audio_detached) {
    return false;
  }

  const auto lane_index = resolvedAudioLane(*video_clip, video_track->lane_index);
  auto* audio_track = audioTrackForLane(lane_index);
  if (audio_track == nullptr) {
    return false;
  }
  if (push_undo_snapshot) {
    pushUndoSnapshot();
  }

  Clip audio_clip = *video_clip;
  audio_clip.clip_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  audio_clip.media_type = QStringLiteral("audio");
  audio_clip.display_label = QStringLiteral("%1 Audio").arg(video_clip->display_label);
  audio_clip.poster_source = audio_clip.waveform_source;
  audio_clip.linked_group_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  audio_clip.has_audio = true;
  audio_clip.audio_detached = false;

  video_clip->linked_group_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  video_clip->has_audio = false;
  video_clip->audio_detached = true;
  audio_track->clips.push_back(audio_clip);
  syncAudioTracks();
  updateCurrentIndexFromSelection();
  return true;
}

bool TimelineDocumentController::unlinkSelectedClipAudio() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (!detachSelectedClipAudio(true)) {
    setStatus(QStringLiteral("The selected clip has no linked audio to detach."));
    return false;
  }
  emitAllState();
  setDirty(true);
  setStatus(QStringLiteral("Unlinked the selected clip's audio."));
  return true;
}

bool TimelineDocumentController::relinkSelectedClipAudio() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto selected_ref = selectedClipRef();
  auto* video_track = trackAt(selected_ref.track_index);
  auto* video_clip = clipAt(selected_ref);
  if (video_track == nullptr || video_clip == nullptr || video_track->kind != TrackKind::Video ||
      !video_clip->audio_detached) {
    setStatus(QStringLiteral("The selected clip does not have detached audio to relink."));
    return false;
  }

  auto* audio_track = audioTrackForLane(resolvedAudioLane(*video_clip, video_track->lane_index));
  if (audio_track == nullptr) {
    return false;
  }
  auto candidate_index = -1;
  auto best_distance = std::numeric_limits<double>::max();
  for (int index = 0; index < audio_track->clips.size(); ++index) {
    const auto& candidate = audio_track->clips.at(index);
    if (candidate.media_type != QStringLiteral("audio") || candidate.file_path != video_clip->file_path) {
      continue;
    }
    const auto distance = qAbs(candidate.start_seconds - video_clip->start_seconds);
    if (distance < best_distance) {
      candidate_index = index;
      best_distance = distance;
    }
  }
  if (candidate_index < 0) {
    setStatus(QStringLiteral("No matching detached audio was found on the paired track."));
    return false;
  }

  pushUndoSnapshot();
  const auto detached_audio = audio_track->clips.at(candidate_index);
  audio_track->clips.removeAt(candidate_index);
  video_clip->has_audio = true;
  video_clip->audio_detached = false;
  video_clip->audio_gain_db = detached_audio.audio_gain_db;
  video_clip->fade_in_seconds = detached_audio.fade_in_seconds;
  video_clip->fade_out_seconds = detached_audio.fade_out_seconds;
  video_clip->linked_group_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  syncAudioTracks();
  updateCurrentIndexFromSelection();
  emitAllState();
  setDirty(true);
  setStatus(QStringLiteral("Relinked the selected clip's audio."));
  return true;
}

void TimelineDocumentController::createTimeline(const QString& timeline_name) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  QVariantMap settings;
  settings.insert(QStringLiteral("timelineName"), timeline_name);
  createTimelineWithSettings(settings);
}

void TimelineDocumentController::createTimelineWithSettings(const QVariantMap& settings) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  if (dirty_ && has_active_timeline_ && !flushEditJournal()) {
    setStatus(QStringLiteral("Unable to checkpoint the current timeline. Save it before creating another."));
    return;
  }
  cancelRecoveryOpen();
  ++working_session_generation_;
  cancelIncrementalMediaHydration();
  edit_journal_timer_.stop();
  resetAutoReframeAnalysis();
  resetTrackingAnalysis();
  resetStabilizationAnalysis();
  cancelSilenceAnalysis();
  cancelTranscription();
  cancelBeatAnalysis();
  silence_analysis_status_ = QStringLiteral("Audio silence has not been analyzed.");
  transcription_status_ = QStringLiteral("Audio has not been transcribed.");
  transcription_language_ = QStringLiteral("en-US");
  transcription_speaker_diarization_ = true;
  beat_suggestions_.clear();
  beat_analysis_status_ = QStringLiteral("Audio beats have not been analyzed.");
  emit silenceAnalysisChanged();
  emit transcriptionChanged();
  emit beatAnalysisChanged();
  pending_text_based_edits_.clear();
  pending_text_based_edit_document_hash_.clear();
  emit textBasedEditsChanged();
  if (!compound_navigation_loading_) {
    clearCompoundNavigation();
    undo_stack_.clear();
    redo_stack_.clear();
    continuous_edit_active_ = false;
    emit undoStateChanged();
  }
  initializeDefaultTracks();
  multicam_groups_.clear();
  media_bins_.clear();
  smart_collections_.clear();
  review_ranges_.clear();
  media_asset_bins_.clear();
  media_asset_metadata_.clear();
  removed_media_asset_ids_.clear();
  active_media_bin_id_.clear();
  active_smart_collection_id_.clear();
  has_active_timeline_ = true;
  timeline_id_ = QUuid::createUuid().toString(QUuid::WithoutBraces);
  timeline_name_ = default_timeline_name(settings.value(QStringLiteral("timelineName")).toString());
  created_at_ = QDateTime::currentDateTimeUtc().toString(Qt::ISODate);
  selected_clip_id_.clear();
  selected_clip_ids_.clear();
  preview_source_.clear();
  saved_document_path_.clear();
  saved_render_path_.clear();
  saved_poster_path_.clear();
  sequence_size_ = QSize(
      qMax(16, settings.value(QStringLiteral("width"), kDefaultSequenceWidth).toInt()),
      qMax(16, settings.value(QStringLiteral("height"), kDefaultSequenceHeight).toInt()));
  sequence_frame_rate_ = qMax(1.0, settings.value(QStringLiteral("frameRate"), kDefaultFramesPerSecond).toDouble());
  audio_sample_rate_ = qMax(8000, settings.value(QStringLiteral("audioSampleRate"), kDefaultAudioSampleRate).toInt());
  project_binding_ = settings.value(QStringLiteral("projectBinding")).toString().simplified();
  color_space_ = normalized_color_space(settings.value(QStringLiteral("colorSpace")).toString());
  data_levels_ = normalized_data_levels(settings.value(QStringLiteral("dataLevels")).toString());
  export_container_ = normalized_export_container(settings.value(QStringLiteral("exportContainer")).toString());
  export_codec_ = normalized_export_codec(settings.value(QStringLiteral("exportCodec")).toString());
  export_preset_ = normalized_export_preset(settings.value(QStringLiteral("exportPreset")).toString());
  export_encoder_mode_ = normalized_export_encoder_mode(
      settings.value(QStringLiteral("exportEncoderMode")).toString());
  export_two_pass_ = settings.value(QStringLiteral("exportTwoPass"), false).toBool();
  export_alpha_ = settings.value(QStringLiteral("exportAlpha"), false).toBool();
  export_audio_stems_ = settings.value(QStringLiteral("exportAudioStems"), false).toBool();
  export_image_sequence_ = settings.value(QStringLiteral("exportImageSequence"), false).toBool();
  cache_budgets_ = {};
  cache_pressure_override_for_testing_.clear();
  cache_pressure_level_ = detectedCachePressureLevel();
  applyCachePressureResponse();
  active_output_variant_ = normalized_output_variant_key(
      settings.value(QStringLiteral("activeOutputVariant")).toString(),
      sequence_size_);
  if (export_codec_ == QStringLiteral("prores") || export_alpha_) {
    export_container_ = QStringLiteral("mov");
    export_codec_ = QStringLiteral("prores");
  }
  if (settings.value(QStringLiteral("trackLayout")).toString() ==
      QStringLiteral("creator_social")) {
    auto* b_roll_track = appendIndependentVideoTrack();
    if (b_roll_track != nullptr) {
      const auto b_roll_lane = b_roll_track->lane_index;
      b_roll_track->display_label = QStringLiteral("B-roll");
      for (auto& track : tracks_) {
        if (track.kind == TrackKind::Video && track.role == QStringLiteral("media")) {
          track.targeted = track.lane_index == 0;
        } else if (track.kind == TrackKind::Video && track.lane_index == b_roll_lane) {
          track.targeted = false;
        }
      }
    }
    appendGraphicsTrack();
    appendCaptionTrack();

    const auto append_audio_role = [this](const QString& role) {
      auto lane_index = kIndependentAudioTrackLaneBase;
      auto role_index = 0;
      for (const auto& track : tracks_) {
        if (track.kind != TrackKind::Audio) {
          continue;
        }
        if (track.independent && track.audio_role == role) {
          ++role_index;
        }
        if (videoTrackForLane(track.lane_index) == nullptr) {
          lane_index = qMax(lane_index, track.lane_index + 1);
        }
      }

      Track track;
      track.track_id = QStringLiteral("%1-%2")
                           .arg(role, QUuid::createUuid().toString(QUuid::WithoutBraces));
      const auto role_label = role == QStringLiteral("effects")
                                  ? QStringLiteral("SFX")
                                  : QStringLiteral("%1%2")
                                        .arg(role.left(1).toUpper(), role.mid(1));
      track.display_label = QStringLiteral("%1 %2").arg(role_label).arg(role_index + 1);
      track.kind = TrackKind::Audio;
      track.lane_index = lane_index;
      track.independent = true;
      track.visible = true;
      track.targeted = false;
      track.audio_role = role;
      track.audio_bus = default_bus_for_audio_role(role);
      tracks_.push_back(track);
    };
    append_audio_role(QStringLiteral("voiceover"));
    append_audio_role(QStringLiteral("music"));
    append_audio_role(QStringLiteral("effects"));
    syncAudioTracks();

    const auto picture_group_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
    const auto graphics_group_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
    const auto audio_group_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
    for (auto& track : tracks_) {
      if (track.kind == TrackKind::Audio) {
        track.group_id = audio_group_id;
        track.group_name = QStringLiteral("Audio");
      } else if (track.role == QStringLiteral("graphics") ||
                 track.role == QStringLiteral("caption")) {
        track.group_id = graphics_group_id;
        track.group_name = QStringLiteral("Visual");
      } else {
        track.group_id = picture_group_id;
        track.group_name = QStringLiteral("Video");
      }
      track.group_parent_id.clear();
      track.group_collapsed = false;
      track.group_transform_scale = 1.0;
      track.group_transform_offset_x = 0.0;
      track.group_transform_offset_y = 0.0;
      track.group_transform_rotation_degrees = 0.0;
    }
  }
  current_index_ = -1;
  sequence_playhead_seconds_ = 0.0;
  current_clip_playhead_seconds_ = 0.0;
  sequence_playing_ = false;
  active_tool_ = QStringLiteral("select");
  edit_mode_ = QStringLiteral("insert");
  linked_selection_enabled_ = true;
  markers_.clear();
  has_source_clip_ = false;
  source_tape_items_.clear();
  source_tape_index_ = -1;
  source_clip_ = Clip{};
  source_in_seconds_ = 0.0;
  source_out_seconds_ = 0.0;
  emitAllState();
  setDirty(false);
  setStatus(QStringLiteral("New timeline ready. Add media from the gallery."));
}

TimelineDocumentController::OutputVariantOverride
TimelineDocumentController::outputVariantOverrideForClip(const Clip& clip) {
  OutputVariantOverride value;
  value.frame_mode = clip.frame_mode;
  value.frame_scale = clip.frame_scale;
  value.frame_offset_x = clip.frame_offset_x;
  value.frame_offset_y = clip.frame_offset_y;
  value.frame_rotation_degrees = clip.frame_rotation_degrees;
  value.frame_perspective_x = clip.frame_perspective_x;
  value.frame_perspective_y = clip.frame_perspective_y;
  value.title_font_size = clip.title_font_size;
  value.title_position_x = clip.title_position_x;
  value.title_position_y = clip.title_position_y;
  value.title_font_family = clip.title_font_family;
  value.title_color = clip.title_color;
  value.title_alignment = clip.title_alignment;
  value.title_background_color = clip.title_background_color;
  value.caption_casing = clip.caption_casing;
  value.caption_stroke_color = clip.caption_stroke_color;
  value.caption_stroke_width = clip.caption_stroke_width;
  value.caption_shadow_enabled = clip.caption_shadow_enabled;
  value.caption_shadow_color = clip.caption_shadow_color;
  value.caption_shadow_offset_x = clip.caption_shadow_offset_x;
  value.caption_shadow_offset_y = clip.caption_shadow_offset_y;
  value.caption_background_padding = clip.caption_background_padding;
  value.caption_background_radius = clip.caption_background_radius;
  value.caption_safe_margin_x = clip.caption_safe_margin_x;
  value.caption_safe_margin_y = clip.caption_safe_margin_y;
  for (const auto& keyframe : clip.keyframes) {
    if (keyframe.parameter == QStringLiteral("frameScale") ||
        keyframe.parameter == QStringLiteral("frameOffsetX") ||
        keyframe.parameter == QStringLiteral("frameOffsetY") ||
        keyframe.parameter == QStringLiteral("frameRotationDegrees") ||
        keyframe.parameter == QStringLiteral("framePerspectiveX") ||
        keyframe.parameter == QStringLiteral("framePerspectiveY")) {
      value.framing_keyframes.push_back(keyframe);
    }
  }
  return value;
}

void TimelineDocumentController::captureOutputVariantOverrides(const QString& variant_key) {
  const auto normalized_key = normalized_output_variant_key(variant_key, sequence_size_);
  for (auto& track : tracks_) {
    if (track.kind != TrackKind::Video) {
      continue;
    }
    for (auto& clip : track.clips) {
      clip.output_variant_overrides.insert(
          normalized_key,
          outputVariantOverrideForClip(clip));
    }
  }
}

void TimelineDocumentController::applyOutputVariantOverrides(const QString& variant_key) {
  const auto normalized_key = normalized_output_variant_key(variant_key);
  for (auto& track : tracks_) {
    if (track.kind != TrackKind::Video) {
      continue;
    }
    for (auto& clip : track.clips) {
      if (!clip.output_variant_overrides.contains(normalized_key)) {
        clip.output_variant_overrides.insert(
            normalized_key,
            outputVariantOverrideForClip(clip));
      }
      const auto value = clip.output_variant_overrides.value(normalized_key);
      clip.frame_mode = value.frame_mode;
      clip.frame_scale = value.frame_scale;
      clip.frame_offset_x = value.frame_offset_x;
      clip.frame_offset_y = value.frame_offset_y;
      clip.frame_rotation_degrees = value.frame_rotation_degrees;
      clip.frame_perspective_x = value.frame_perspective_x;
      clip.frame_perspective_y = value.frame_perspective_y;
      clip.title_font_size = value.title_font_size;
      clip.title_position_x = value.title_position_x;
      clip.title_position_y = value.title_position_y;
      clip.title_font_family = value.title_font_family;
      clip.title_color = value.title_color;
      clip.title_alignment = value.title_alignment;
      clip.title_background_color = value.title_background_color;
      clip.caption_casing = value.caption_casing;
      clip.caption_stroke_color = value.caption_stroke_color;
      clip.caption_stroke_width = value.caption_stroke_width;
      clip.caption_shadow_enabled = value.caption_shadow_enabled;
      clip.caption_shadow_color = value.caption_shadow_color;
      clip.caption_shadow_offset_x = value.caption_shadow_offset_x;
      clip.caption_shadow_offset_y = value.caption_shadow_offset_y;
      clip.caption_background_padding = value.caption_background_padding;
      clip.caption_background_radius = value.caption_background_radius;
      clip.caption_safe_margin_x = value.caption_safe_margin_x;
      clip.caption_safe_margin_y = value.caption_safe_margin_y;
      clip.keyframes.erase(
          std::remove_if(
              clip.keyframes.begin(),
              clip.keyframes.end(),
              [](const ClipKeyframe& keyframe) {
                return keyframe.parameter == QStringLiteral("frameScale") ||
                       keyframe.parameter == QStringLiteral("frameOffsetX") ||
                       keyframe.parameter == QStringLiteral("frameOffsetY") ||
                       keyframe.parameter == QStringLiteral("frameRotationDegrees") ||
                       keyframe.parameter == QStringLiteral("framePerspectiveX") ||
                       keyframe.parameter == QStringLiteral("framePerspectiveY");
              }),
          clip.keyframes.end());
      clip.keyframes += value.framing_keyframes;
      std::sort(
          clip.keyframes.begin(),
          clip.keyframes.end(),
          [](const ClipKeyframe& left, const ClipKeyframe& right) {
            if (left.parameter == right.parameter) {
              return left.local_seconds < right.local_seconds;
            }
            return left.parameter < right.parameter;
          });
    }
  }
  syncAudioTracks();
}

void TimelineDocumentController::applyOutputPreset(const QString& preset) {
  if (!has_active_timeline_) {
    return;
  }
  const auto variant_key = normalized_output_variant_key(preset, sequence_size_);
  const auto& definition = output_variant_definition(variant_key);
  const auto next_export_preset = preset.simplified().compare(
                                      QStringLiteral("tiktok"),
                                      Qt::CaseInsensitive) == 0
                                      ? QStringLiteral("tiktok")
                                      : definition.export_preset;
  if (sequence_size_ == definition.size && export_preset_ == next_export_preset &&
      active_output_variant_ == variant_key &&
      export_container_ == QStringLiteral("mp4") && export_codec_ == QStringLiteral("h264")) {
    return;
  }
  pushUndoSnapshot();
  captureOutputVariantOverrides(active_output_variant_);
  applyOutputVariantOverrides(variant_key);
  active_output_variant_ = variant_key;
  sequence_size_ = definition.size;
  export_preset_ = next_export_preset;
  export_container_ = QStringLiteral("mp4");
  export_codec_ = QStringLiteral("h264");
  emit sequenceChanged();
  setDirty(true);
  setStatus(QStringLiteral("Switched to %1 %2 at %3 x %4. Framing is saved independently for this format.")
                .arg(definition.label, definition.aspect_ratio)
                .arg(sequence_size_.width())
                .arg(sequence_size_.height()));
}

bool TimelineDocumentController::setDeliverySetting(const QString& setting, const QVariant& value) {
  if (!has_active_timeline_) {
    return false;
  }
  const auto normalized = setting.trimmed();
  const auto next_encoder_mode = normalized_export_encoder_mode(value.toString());
  const auto next_bool = value.toBool();
  const auto unchanged =
      (normalized == QStringLiteral("encoderMode") && export_encoder_mode_ == next_encoder_mode) ||
      (normalized == QStringLiteral("twoPass") && export_two_pass_ == next_bool) ||
      (normalized == QStringLiteral("alpha") && export_alpha_ == next_bool) ||
      (normalized == QStringLiteral("audioStems") && export_audio_stems_ == next_bool) ||
      (normalized == QStringLiteral("imageSequence") && export_image_sequence_ == next_bool);
  if (unchanged) {
    return false;
  }
  if (normalized != QStringLiteral("encoderMode") && normalized != QStringLiteral("twoPass") &&
      normalized != QStringLiteral("alpha") && normalized != QStringLiteral("audioStems") &&
      normalized != QStringLiteral("imageSequence")) {
    return false;
  }
  pushUndoSnapshot();
  if (normalized == QStringLiteral("encoderMode")) {
    export_encoder_mode_ = next_encoder_mode;
  } else if (normalized == QStringLiteral("twoPass")) {
    export_two_pass_ = next_bool;
  } else if (normalized == QStringLiteral("alpha")) {
    export_alpha_ = next_bool;
    if (export_alpha_) {
      export_container_ = QStringLiteral("mov");
      export_codec_ = QStringLiteral("prores");
    } else {
      export_container_ = QStringLiteral("mp4");
      export_codec_ = QStringLiteral("h264");
    }
  } else if (normalized == QStringLiteral("audioStems")) {
    export_audio_stems_ = next_bool;
  } else {
    export_image_sequence_ = next_bool;
  }
  emit sequenceChanged();
  setDirty(true);
  setStatus(QStringLiteral("Updated the timeline delivery package."));
  return true;
}

bool TimelineDocumentController::resetSelectedClipOutputVariantOverride() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  auto* clip = clipAt(selectedClipRef());
  if (clip == nullptr) {
    setStatus(QStringLiteral("Select a clip before resetting format framing."));
    return false;
  }
  pushUndoSnapshot();
  OutputVariantOverride value;
  clip->output_variant_overrides.insert(active_output_variant_, value);
  clip->frame_mode = value.frame_mode;
  clip->frame_scale = value.frame_scale;
  clip->frame_offset_x = value.frame_offset_x;
  clip->frame_offset_y = value.frame_offset_y;
  clip->frame_rotation_degrees = value.frame_rotation_degrees;
  clip->frame_perspective_x = value.frame_perspective_x;
  clip->frame_perspective_y = value.frame_perspective_y;
  clip->title_font_size = value.title_font_size;
  clip->title_position_x = value.title_position_x;
  clip->title_position_y = value.title_position_y;
  clip->title_font_family = value.title_font_family;
  clip->title_color = value.title_color;
  clip->title_alignment = value.title_alignment;
  clip->title_background_color = value.title_background_color;
  clip->caption_casing = value.caption_casing;
  clip->caption_stroke_color = value.caption_stroke_color;
  clip->caption_stroke_width = value.caption_stroke_width;
  clip->caption_shadow_enabled = value.caption_shadow_enabled;
  clip->caption_shadow_color = value.caption_shadow_color;
  clip->caption_shadow_offset_x = value.caption_shadow_offset_x;
  clip->caption_shadow_offset_y = value.caption_shadow_offset_y;
  clip->caption_background_padding = value.caption_background_padding;
  clip->caption_background_radius = value.caption_background_radius;
  clip->caption_safe_margin_x = value.caption_safe_margin_x;
  clip->caption_safe_margin_y = value.caption_safe_margin_y;
  clip->keyframes.erase(
      std::remove_if(
          clip->keyframes.begin(),
          clip->keyframes.end(),
          [](const ClipKeyframe& keyframe) {
            return keyframe.parameter == QStringLiteral("frameScale") ||
                   keyframe.parameter == QStringLiteral("frameOffsetX") ||
                   keyframe.parameter == QStringLiteral("frameOffsetY") ||
                   keyframe.parameter == QStringLiteral("frameRotationDegrees") ||
                   keyframe.parameter == QStringLiteral("framePerspectiveX") ||
                   keyframe.parameter == QStringLiteral("framePerspectiveY");
          }),
      clip->keyframes.end());
  syncAudioTracks();
  emitAllState();
  setDirty(true);
  setStatus(QStringLiteral("Reset selected clip framing for the %1 variant.")
                .arg(output_variant_definition(active_output_variant_).label));
  return true;
}

QVariantList TimelineDocumentController::recentTimelines() const {
  return timeline_asset_records_to_variant_list(loadTimelineAssetRecords());
}

QVariantList TimelineDocumentController::recentTimelineRecords() const {
  return recent_timeline_records_;
}

bool TimelineDocumentController::recentTimelinesLoading() const {
  return recent_timelines_loading_;
}

void TimelineDocumentController::refreshRecentTimelines() {
  if (recent_timelines_watcher_ != nullptr) {
    recent_timelines_refresh_pending_ = true;
    return;
  }

  recent_timelines_loading_ = true;
  emit recentTimelinesChanged();
  auto* watcher = new QFutureWatcher<QVariantList>(this);
  recent_timelines_watcher_ = watcher;
  connect(watcher, &QFutureWatcher<QVariantList>::finished, this, [this, watcher]() {
    if (watcher != recent_timelines_watcher_) {
      watcher->deleteLater();
      return;
    }

    recent_timeline_records_ = watcher->result();
    recent_timelines_watcher_ = nullptr;
    recent_timelines_loading_ = false;
    watcher->deleteLater();
    emit recentTimelinesChanged();

    const bool refresh_again = recent_timelines_refresh_pending_;
    recent_timelines_refresh_pending_ = false;
    if (refresh_again)
      refreshRecentTimelines();
  });
  watcher->setFuture(QtConcurrent::run(&timeline_storage_thread_pool(), []() {
    return recent_timelines_with_recoveries();
  }));
}

QVariantList TimelineDocumentController::pancakeSequences() const {
  QVariantList result;
  const auto current_path = normalized_path(saved_document_path_);
  for (const auto& value : recent_timeline_records_) {
    auto entry = value.toMap();
    if (entry.value(QStringLiteral("isRecovery")).toBool())
      continue;
    const auto document_path = normalized_path(
        entry.value(QStringLiteral("documentPath")).toString());
    if (document_path.isEmpty() || document_path == current_path ||
        !QFileInfo(document_path).isReadable() ||
        entry.value(QStringLiteral("timelineId")).toString() == timeline_id_) {
      continue;
    }
    entry.insert(QStringLiteral("documentPath"), document_path);
    result.push_back(entry);
  }
  return result;
}

QVariantMap TimelineDocumentController::pancakeSequencePreview(
    const QString& document_path) const {
  QVariantMap preview{
      {QStringLiteral("schema"), QStringLiteral("timeline-pancake-preview:v1")},
      {QStringLiteral("available"), false},
      {QStringLiteral("documentPath"), normalized_path(document_path)},
      {QStringLiteral("tracks"), QVariantList{}},
  };
  const auto normalized = normalized_path(document_path);
  if (normalized.isEmpty() || normalized == normalized_path(saved_document_path_)) {
    preview.insert(
        QStringLiteral("reason"),
        QStringLiteral("Choose a different saved sequence for the upper timeline."));
    return preview;
  }
  TimelineDocumentController source;
  if (!source.loadTimeline(normalized)) {
    preview.insert(
        QStringLiteral("reason"),
        QStringLiteral("The source sequence could not be opened read-only."));
    return preview;
  }
  preview.insert(QStringLiteral("available"), true);
  preview.insert(QStringLiteral("timelineId"), source.timeline_id_);
  preview.insert(QStringLiteral("name"), source.timeline_name_);
  preview.insert(QStringLiteral("durationSeconds"), source.totalDurationSeconds());
  preview.insert(QStringLiteral("frameRate"), source.framesPerSecond());
  preview.insert(QStringLiteral("trackCount"), source.tracks_.size());
  preview.insert(QStringLiteral("clipCount"), source.clipCount());
  preview.insert(QStringLiteral("tracks"), source.sequenceTracks());
  preview.insert(
      QStringLiteral("note"),
      QStringLiteral("The upper sequence stays read-only until Copy or Move is committed."));
  return preview;
}

QVariantMap TimelineDocumentController::pancakeTransferPreview(
    const QString& source_document_path,
    const QStringList& clip_ids,
    double source_range_start_seconds,
    double source_range_end_seconds,
    double destination_seconds,
    const QString& edit_mode,
    const QString& transfer_mode) const {
  QVariantMap result{
      {QStringLiteral("schema"), QStringLiteral("timeline-pancake-transfer-preview:v1")},
      {QStringLiteral("available"), false},
      {QStringLiteral("clipCount"), 0},
      {QStringLiteral("editMode"), edit_mode.simplified().toLower()},
      {QStringLiteral("transferMode"), transfer_mode.simplified().toLower()},
  };
  const auto normalized_path_value = normalized_path(source_document_path);
  if (!has_active_timeline_ || normalized_path_value.isEmpty() ||
      normalized_path_value == normalized_path(saved_document_path_)) {
    result.insert(QStringLiteral("reason"), QStringLiteral("Choose two different saved sequences."));
    return result;
  }
  TimelineDocumentController source;
  if (!source.loadTimeline(normalized_path_value)) {
    result.insert(QStringLiteral("reason"), QStringLiteral("The source sequence could not be opened."));
    return result;
  }
  const auto source_fps = source.framesPerSecond();
  const auto destination_fps = framesPerSecond();
  const auto source_snap = [source_fps](double seconds) {
    return qMax(0.0, qRound64(seconds * source_fps) / source_fps);
  };
  const auto destination_snap = [destination_fps](double seconds) {
    return qMax(0.0, qRound64(seconds * destination_fps) / destination_fps);
  };
  const QSet<QString> requested_ids(clip_ids.cbegin(), clip_ids.cend());
  auto count = 0;
  auto selection_start = std::numeric_limits<double>::max();
  auto selection_end = 0.0;
  const auto range_start = source_snap(source_range_start_seconds);
  const auto range_end = source_snap(source_range_end_seconds);
  const auto range_mode = requested_ids.isEmpty() &&
                          range_end > range_start + kBoundaryEpsilon;
  for (const auto& track : source.tracks_) {
    if (track.kind != TrackKind::Video) {
      continue;
    }
    for (const auto& clip : track.clips) {
      const auto included = range_mode
                                ? clip.start_seconds < range_end - kBoundaryEpsilon &&
                                      source.clipEndSeconds(clip) > range_start + kBoundaryEpsilon
                                : requested_ids.contains(clip.clip_id);
      if (!included) {
        continue;
      }
      ++count;
      selection_start = qMin(
          selection_start, range_mode ? qMax(range_start, clip.start_seconds)
                                      : clip.start_seconds);
      selection_end = qMax(
          selection_end, range_mode ? qMin(range_end, source.clipEndSeconds(clip))
                                    : source.clipEndSeconds(clip));
    }
  }
  if (count <= 0) {
    result.insert(
        QStringLiteral("reason"),
        QStringLiteral("Select one or more upper clips, or set a source In and Out range."));
    return result;
  }
  if (!range_mode && count != requested_ids.size()) {
    result.insert(
        QStringLiteral("reason"),
        QStringLiteral("One or more selected clips no longer exist in the saved source sequence."));
    return result;
  }
  const auto exact_start = range_mode ? range_start : selection_start;
  const auto exact_end = range_mode ? range_end : selection_end;
  result.insert(QStringLiteral("available"), true);
  result.insert(QStringLiteral("clipCount"), count);
  result.insert(QStringLiteral("sourceStartSeconds"), exact_start);
  result.insert(QStringLiteral("sourceEndSeconds"), exact_end);
  result.insert(QStringLiteral("durationSeconds"), qMax(0.0, exact_end - exact_start));
  result.insert(QStringLiteral("destinationSeconds"), destination_snap(destination_seconds));
  result.insert(QStringLiteral("sourceFrameRate"), source_fps);
  result.insert(QStringLiteral("destinationFrameRate"), destination_fps);
  result.insert(QStringLiteral("rangeMode"), range_mode);
  result.insert(
      QStringLiteral("frameRateConversion"),
      qAbs(source_fps - destination_fps) > kBoundaryEpsilon);
  result.insert(
      QStringLiteral("summary"),
      QStringLiteral("%1 %2 clip%3 from %4 at %5 using %6.")
          .arg(transfer_mode.simplified().toLower() == QStringLiteral("move")
                   ? QStringLiteral("Move") : QStringLiteral("Copy"))
          .arg(count)
          .arg(count == 1 ? QString{} : QStringLiteral("s"))
          .arg(source.timeline_name_, formatDurationText(destination_snap(destination_seconds)),
               edit_mode.simplified().toLower()));
  return result;
}

int TimelineDocumentController::transferFromPancakeSequence(
    const QString& source_document_path,
    const QStringList& clip_ids,
    double source_range_start_seconds,
    double source_range_end_seconds,
    double destination_seconds,
    const QString& edit_mode,
    const QString& transfer_mode) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto preview = pancakeTransferPreview(
      source_document_path, clip_ids, source_range_start_seconds,
      source_range_end_seconds, destination_seconds, edit_mode, transfer_mode);
  if (!preview.value(QStringLiteral("available")).toBool()) {
    setStatus(preview.value(QStringLiteral("reason")).toString());
    return 0;
  }
  const auto source_path = normalized_path(source_document_path);
  QFile source_file(source_path);
  if (!source_file.open(QIODevice::ReadOnly)) {
    setStatus(QStringLiteral("The source sequence changed before the transfer could start."));
    return 0;
  }
  const auto source_bytes_before = source_file.readAll();
  source_file.close();

  TimelineDocumentController source;
  if (!source.loadTimeline(source_path)) {
    setStatus(QStringLiteral("The source sequence could not be opened for transfer."));
    return 0;
  }
  const auto normalized_edit_mode = edit_mode.simplified().toLower();
  const auto normalized_transfer_mode = transfer_mode.simplified().toLower();
  if ((normalized_edit_mode != QStringLiteral("overwrite") &&
       normalized_edit_mode != QStringLiteral("insert")) ||
      (normalized_transfer_mode != QStringLiteral("copy") &&
       normalized_transfer_mode != QStringLiteral("move"))) {
    setStatus(QStringLiteral("Choose Copy or Move and Overwrite or Insert."));
    return 0;
  }

  const QSet<QString> requested_ids(clip_ids.cbegin(), clip_ids.cend());
  const auto range_start = preview.value(QStringLiteral("sourceStartSeconds")).toDouble();
  const auto range_end = preview.value(QStringLiteral("sourceEndSeconds")).toDouble();
  const auto range_mode = preview.value(QStringLiteral("rangeMode")).toBool();
  QVector<ClipboardClip> imported;
  auto origin_video_lane = std::numeric_limits<int>::max();
  auto origin_audio_lane = std::numeric_limits<int>::max();
  for (const auto& track : source.tracks_) {
    if (track.kind != TrackKind::Video) {
      continue;
    }
    for (const auto& original : track.clips) {
      const auto included = range_mode
                                ? original.start_seconds < range_end - kBoundaryEpsilon &&
                                      source.clipEndSeconds(original) > range_start + kBoundaryEpsilon
                                : requested_ids.contains(original.clip_id);
      if (!included) {
        continue;
      }
      if (normalized_transfer_mode == QStringLiteral("move") && track.locked) {
        setStatus(QStringLiteral("Unlock %1 in the source sequence before moving material.")
                      .arg(track.display_label));
        return 0;
      }
      Clip transfer_clip = original;
      if (range_mode &&
          (original.start_seconds < range_start - kBoundaryEpsilon ||
           source.clipEndSeconds(original) > range_end + kBoundaryEpsilon)) {
        Track scratch = track;
        scratch.clips = {original};
        if (original.start_seconds < range_start - kBoundaryEpsilon) {
          source.splitTrackClipAtSequenceSeconds(&scratch, 0, range_start);
        }
        for (auto index = 0; index < scratch.clips.size(); ++index) {
          const auto& candidate = scratch.clips.at(index);
          if (candidate.start_seconds < range_end - kBoundaryEpsilon &&
              source.clipEndSeconds(candidate) > range_end + kBoundaryEpsilon) {
            source.splitTrackClipAtSequenceSeconds(&scratch, index, range_end);
            break;
          }
        }
        auto found_slice = false;
        for (const auto& candidate : scratch.clips) {
          if (candidate.start_seconds >= range_start - kBoundaryEpsilon &&
              source.clipEndSeconds(candidate) <= range_end + kBoundaryEpsilon &&
              source.clipEndSeconds(candidate) > range_start + kBoundaryEpsilon) {
            transfer_clip = candidate;
            found_slice = true;
            break;
          }
        }
        if (!found_slice) {
          continue;
        }
        if (original.start_seconds < range_start - kBoundaryEpsilon) {
          transfer_clip.transition_in_name.clear();
          transfer_clip.transition_in_seconds = 0.0;
        }
        if (source.clipEndSeconds(original) > range_end + kBoundaryEpsilon) {
          transfer_clip.transition_out_name.clear();
          transfer_clip.transition_out_seconds = 0.0;
        }
      }
      const auto relative_start = qMax(
          0.0, transfer_clip.start_seconds -
                   (range_mode ? range_start
                               : preview.value(QStringLiteral("sourceStartSeconds")).toDouble()));
      imported.push_back({transfer_clip, track.lane_index, relative_start});
      origin_video_lane = qMin(origin_video_lane, track.lane_index);
      if (transfer_clip.audio_lane_index >= 0) {
        origin_audio_lane = qMin(origin_audio_lane, transfer_clip.audio_lane_index);
      }
    }
  }
  if (imported.isEmpty()) {
    setStatus(QStringLiteral("The selected source material no longer has transferable clips."));
    return 0;
  }
  std::sort(
      imported.begin(), imported.end(),
      [](const auto& left, const auto& right) {
        if (qAbs(left.relative_start_seconds - right.relative_start_seconds) >
            kBoundaryEpsilon) {
          return left.relative_start_seconds < right.relative_start_seconds;
        }
        return left.lane_index < right.lane_index;
      });

  const auto saved_clipboard = clip_clipboard_;
  const auto saved_clipboard_duration = clip_clipboard_duration_seconds_;
  const auto saved_video_origin = clip_clipboard_origin_video_lane_;
  const auto saved_audio_origin = clip_clipboard_origin_audio_lane_;
  clip_clipboard_ = imported;
  clip_clipboard_duration_seconds_ =
      preview.value(QStringLiteral("durationSeconds")).toDouble();
  clip_clipboard_origin_video_lane_ =
      origin_video_lane == std::numeric_limits<int>::max() ? 0 : origin_video_lane;
  clip_clipboard_origin_audio_lane_ =
      origin_audio_lane == std::numeric_limits<int>::max()
          ? clip_clipboard_origin_video_lane_ : origin_audio_lane;
  sequence_playhead_seconds_ = preview.value(QStringLiteral("destinationSeconds")).toDouble();
  const auto pasted_count = pasteClipsAtPlayhead(normalized_edit_mode);
  clip_clipboard_ = saved_clipboard;
  clip_clipboard_duration_seconds_ = saved_clipboard_duration;
  clip_clipboard_origin_video_lane_ = saved_video_origin;
  clip_clipboard_origin_audio_lane_ = saved_audio_origin;
  emit clipClipboardChanged();
  if (pasted_count <= 0) {
    return 0;
  }

  if (normalized_transfer_mode == QStringLiteral("move")) {
    if (range_mode) {
      for (auto& track : source.tracks_) {
        if (track.kind == TrackKind::Video) {
          source.overwriteTrackRange(&track, range_start, range_end);
        }
      }
    } else {
      for (auto& track : source.tracks_) {
        if (track.kind != TrackKind::Video) {
          continue;
        }
        track.clips.erase(
            std::remove_if(
                track.clips.begin(), track.clips.end(),
                [&requested_ids](const Clip& clip) {
                  return requested_ids.contains(clip.clip_id);
                }),
            track.clips.end());
      }
    }
    source.syncAudioTracks();
    source.clampPlaybackState();
    (void)source.appendEditJournalEntry(QStringLiteral("pancake-move"));
    const auto source_document_after = source.documentObject();
    auto source_records = loadTimelineAssetRecords();
    TimelineAssetRecord source_record;
    auto found_record = false;
    const auto updated_at = QDateTime::currentDateTimeUtc().toString(Qt::ISODate);
    for (auto& record : source_records) {
      if (record.timeline_id != source.timeline_id_) {
        continue;
      }
      record.name = source.timeline_name_;
      record.document_path = source_path;
      record.duration_seconds = source.totalDurationSeconds();
      record.updated_at = updated_at;
      source_record = record;
      found_record = true;
      break;
    }
    const auto persisted = source.persistDocument(source_path) &&
                           found_record && saveTimelineAssetRecords(source_records) &&
                           saveTimelineDocumentBackup(source_record, source_document_after);
    if (!persisted) {
      QSaveFile rollback(source_path);
      if (rollback.open(QIODevice::WriteOnly)) {
        rollback.write(source_bytes_before);
        (void)rollback.commit();
      }
      undo();
      redo_stack_.clear();
      emit undoStateChanged();
      setStatus(QStringLiteral("The source sequence could not be updated; the destination transfer was rolled back."));
      return 0;
    }
    if (!undo_stack_.isEmpty()) {
      undo_stack_.last().external_document_bytes.insert(
          source_path, source_bytes_before);
    }
  }

  setStatus(QStringLiteral("%1 %2 clip%3 from '%4' at %5 using %6 mode.")
                .arg(normalized_transfer_mode == QStringLiteral("move")
                         ? QStringLiteral("Moved") : QStringLiteral("Copied"))
                .arg(pasted_count)
                .arg(pasted_count == 1 ? QString{} : QStringLiteral("s"))
                .arg(source.timeline_name_,
                     formatDurationText(preview.value(QStringLiteral("destinationSeconds")).toDouble()),
                     normalized_edit_mode));
  emit pancakeSequencesChanged();
  return pasted_count;
}

QString TimelineDocumentController::sequenceVersionsRootPath() const {
  if (timeline_id_.isEmpty()) {
    return {};
  }
  return QDir(timelineDocumentsRootPath())
      .filePath(QStringLiteral("versions/%1").arg(timeline_id_));
}

QString TimelineDocumentController::sequenceVersionDocumentPath(const QString& version_id) const {
  const auto normalized_id = version_id.trimmed();
  if (normalized_id == QStringLiteral("autosave")) {
    return saved_document_path_.isEmpty()
               ? QString{}
               : saved_document_path_ + QStringLiteral(".autosave");
  }
  const auto root_path = sequenceVersionsRootPath();
  if (normalized_id.isEmpty() || root_path.isEmpty()) {
    return {};
  }
  const auto files = QDir(root_path).entryInfoList(
      {QStringLiteral("*.json")}, QDir::Files | QDir::Readable, QDir::Time);
  for (const auto& info : files) {
    QFile file(info.absoluteFilePath());
    if (!file.open(QIODevice::ReadOnly)) {
      continue;
    }
    const auto object = QJsonDocument::fromJson(file.readAll()).object();
    const auto metadata = object.value(QStringLiteral("_sequenceVersion")).toObject();
    if (metadata.value(QStringLiteral("versionId")).toString() == normalized_id) {
      return info.absoluteFilePath();
    }
  }
  return {};
}

QVariantList TimelineDocumentController::sequenceVersions() const {
  QVariantList result;
  if (!has_active_timeline_ || timeline_id_.isEmpty()) {
    return result;
  }
  const auto root_path = sequenceVersionsRootPath();
  const auto files = QDir(root_path).entryInfoList(
      {QStringLiteral("*.json")}, QDir::Files | QDir::Readable, QDir::Time);
  const QFileInfo autosave_info(saved_document_path_.isEmpty()
                                    ? QString{}
                                    : saved_document_path_ + QStringLiteral(".autosave"));
  const QFileInfo saved_info(saved_document_path_);
  const auto include_autosave = autosave_info.exists() &&
                                (!saved_info.exists() ||
                                 autosave_info.lastModified() > saved_info.lastModified());
  QString cache_key = timeline_id_ + QLatin1Char('|') +
                      QString::number(document_edit_revision_) + QLatin1Char('|') +
                      saved_document_path_;
  for (const auto& info : files) {
    cache_key += QLatin1Char('|') + info.absoluteFilePath() + QLatin1Char(':') +
                 QString::number(info.size()) + QLatin1Char(':') +
                 QString::number(info.lastModified().toMSecsSinceEpoch());
  }
  if (include_autosave) {
    cache_key += QLatin1Char('|') + autosave_info.absoluteFilePath() + QLatin1Char(':') +
                 QString::number(autosave_info.size()) + QLatin1Char(':') +
                 QString::number(autosave_info.lastModified().toMSecsSinceEpoch());
  }
  if (cache_key == sequence_versions_cache_key_) {
    return sequence_versions_cache_;
  }
  if (files.isEmpty() && !include_autosave) {
    sequence_versions_cache_key_ = cache_key;
    sequence_versions_cache_.clear();
    return sequence_versions_cache_;
  }
  const auto current_document = documentObject();
  const auto current_clip_count = clipCount();

  const auto append_document = [this, &result, &current_document, current_clip_count](
                                   const QString& path,
                                   const QString& fallback_id,
                                   const QString& fallback_label,
                                   const QString& fallback_kind,
                                   const QDateTime& fallback_created_at) {
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) {
      return;
    }
    const auto document = QJsonDocument::fromJson(file.readAll());
    if (!document.isObject()) {
      return;
    }
    const auto object = document.object();
    const auto metadata = object.value(QStringLiteral("_sequenceVersion")).toObject();
    const auto metrics = metadata.isEmpty() ? sequence_document_metrics(object) : metadata.toVariantMap();
    const auto version_clip_count = metrics.value(QStringLiteral("clipCount")).toInt();
    const auto version_marker_count = metrics.value(QStringLiteral("markerCount")).toInt();
    const auto version_duration = metrics.value(QStringLiteral("durationSeconds")).toDouble();
    const auto clip_delta = version_clip_count - current_clip_count;
    const auto marker_delta = version_marker_count - static_cast<int>(markers_.size());
    const auto duration_delta = version_duration - totalDurationSeconds();
    const auto kind = metadata.value(QStringLiteral("kind")).toString(fallback_kind);

    QVariantMap entry;
    entry.insert(
        QStringLiteral("versionId"),
        metadata.value(QStringLiteral("versionId")).toString(fallback_id));
    entry.insert(
        QStringLiteral("label"),
        metadata.value(QStringLiteral("label")).toString(fallback_label));
    entry.insert(QStringLiteral("kind"), kind);
    entry.insert(
        QStringLiteral("createdAt"),
        metadata.value(QStringLiteral("createdAt")).toString(
            fallback_created_at.toUTC().toString(Qt::ISODateWithMs)));
    entry.insert(
        QStringLiteral("metadataUpdatedAt"),
        metadata.value(QStringLiteral("metadataUpdatedAt")).toString());
    entry.insert(
        QStringLiteral("notes"),
        metadata.value(QStringLiteral("notes")).toString());
    entry.insert(
        QStringLiteral("author"),
        metadata.value(QStringLiteral("author")).toString(
            kind == QStringLiteral("named")
                ? QStringLiteral("Local editor")
                : QStringLiteral("Looksy")));
    entry.insert(
        QStringLiteral("protected"),
        metadata.value(QStringLiteral("protected")).toBool(false));
    entry.insert(
        QStringLiteral("duplicatedFromVersionId"),
        metadata.value(QStringLiteral("duplicatedFromVersionId")).toString());
    const auto comparison_media_path =
        metadata.value(QStringLiteral("comparisonMediaPath")).toString().trimmed();
    entry.insert(QStringLiteral("comparisonMediaPath"), comparison_media_path);
    entry.insert(
        QStringLiteral("comparisonMediaUrl"),
        comparison_media_path.isEmpty()
            ? QString{}
            : QUrl::fromLocalFile(comparison_media_path).toString());
    entry.insert(
        QStringLiteral("comparisonMediaKind"),
        metadata.value(QStringLiteral("comparisonMediaKind")).toString());
    entry.insert(
        QStringLiteral("comparisonFrameSeconds"),
        metadata.value(QStringLiteral("comparisonFrameSeconds")).toDouble());
    entry.insert(
        QStringLiteral("comparisonMediaAvailable"),
        !comparison_media_path.isEmpty() && QFileInfo(comparison_media_path).isReadable());
    entry.insert(QStringLiteral("documentPath"), path);
    entry.insert(QStringLiteral("clipCount"), version_clip_count);
    entry.insert(QStringLiteral("trackCount"), metrics.value(QStringLiteral("trackCount")).toInt());
    entry.insert(QStringLiteral("markerCount"), version_marker_count);
    entry.insert(QStringLiteral("durationSeconds"), version_duration);
    entry.insert(QStringLiteral("clipDelta"), clip_delta);
    entry.insert(QStringLiteral("markerDelta"), marker_delta);
    entry.insert(QStringLiteral("durationDeltaSeconds"), duration_delta);
    const auto detailed_comparison =
        sequence_version_detailed_comparison(object, current_document);
    for (auto iterator = detailed_comparison.cbegin();
         iterator != detailed_comparison.cend(); ++iterator) {
      entry.insert(iterator.key(), iterator.value());
    }
    const auto metric_summary =
        sequence_version_comparison_summary(clip_delta, marker_delta, duration_delta);
    entry.insert(
        QStringLiteral("comparisonSummary"),
        detailed_comparison.value(QStringLiteral("matchesCurrent")).toBool()
            ? metric_summary
            : detailed_comparison.value(QStringLiteral("detailSummary")).toString());
    entry.insert(QStringLiteral("isRecovery"), kind != QStringLiteral("named"));
    result.push_back(entry);
  };

  for (const auto& info : files) {
    append_document(
        info.absoluteFilePath(),
        info.completeBaseName(),
        QStringLiteral("Version"),
        QStringLiteral("named"),
        info.lastModified());
  }

  if (!saved_document_path_.isEmpty()) {
    if (include_autosave) {
      append_document(
          autosave_info.absoluteFilePath(),
          QStringLiteral("autosave"),
          QStringLiteral("Autosave recovery"),
          QStringLiteral("autosave"),
          autosave_info.lastModified());
    }
  }

  std::sort(result.begin(), result.end(), [](const QVariant& left, const QVariant& right) {
    return left.toMap().value(QStringLiteral("createdAt")).toString() >
           right.toMap().value(QStringLiteral("createdAt")).toString();
  });
  sequence_versions_cache_key_ = cache_key;
  sequence_versions_cache_ = result;
  return sequence_versions_cache_;
}

QVariantMap TimelineDocumentController::sequenceVersionComparison(const QString& version_id) const {
  for (const auto& value : sequenceVersions()) {
    const auto entry = value.toMap();
    if (entry.value(QStringLiteral("versionId")).toString() == version_id.trimmed()) {
      return entry;
    }
  }
  return {};
}

QString TimelineDocumentController::programComparisonCapturePath(
    const QString& role,
    int revision) const {
  auto safe_role = role.trimmed().toLower();
  if (safe_role != QStringLiteral("current") &&
      safe_role != QStringLiteral("reference") &&
      safe_role != QStringLiteral("effects-after") &&
      safe_role != QStringLiteral("scopes")) {
    safe_role = QStringLiteral("frame");
  }
  const auto capture_root = QDir(poster_cache_root()).filePath(
      QStringLiteral("program-comparison-captures"));
  if (!QDir().mkpath(capture_root)) {
    return {};
  }
  const auto cached_frames = QDir(capture_root).entryInfoList(
      {QStringLiteral("timeline-program-comparison-*.png")},
      QDir::Files,
      QDir::Time);
  for (auto index = 15; index < cached_frames.size(); ++index) {
    QFile::remove(cached_frames.at(index).absoluteFilePath());
  }
  return QDir(capture_root).filePath(
      QStringLiteral("timeline-program-comparison-%1-%2.png")
          .arg(safe_role)
          .arg(qMax(0, revision)));
}

void TimelineDocumentController::requestProgramScopeAnalysis(
    const QString& source,
    int revision) {
  const auto trimmed_source = source.trimmed();
  if (trimmed_source.isEmpty() || revision < 0) {
    return;
  }
  if (programScopeAnalysisBusy()) {
    if (revision >= pending_program_scope_revision_) {
      pending_program_scope_source_ = trimmed_source;
      pending_program_scope_revision_ = revision;
    }
    return;
  }
  if (revision < program_scope_published_revision_) {
    return;
  }
  program_scope_watcher_ = new QFutureWatcher<QVariantMap>(this);
  auto* watcher = program_scope_watcher_;
  connect(watcher, &QFutureWatcher<QVariantMap>::finished, this, [this, watcher]() {
    if (watcher != program_scope_watcher_) {
      watcher->deleteLater();
      return;
    }
    const auto result = watcher->result();
    const auto result_revision = result.value(QStringLiteral("revision")).toInt();
    program_scope_watcher_ = nullptr;
    watcher->deleteLater();
    if (result_revision >= program_scope_published_revision_) {
      program_scope_data_ = result;
      program_scope_published_revision_ = result_revision;
    }
    const auto pending_source = pending_program_scope_source_;
    const auto pending_revision = pending_program_scope_revision_;
    pending_program_scope_source_.clear();
    pending_program_scope_revision_ = -1;
    emit programScopeAnalysisChanged();
    if (!pending_source.isEmpty() && pending_revision > result_revision) {
      requestProgramScopeAnalysis(pending_source, pending_revision);
    }
  });
  watcher->setFuture(QtConcurrent::run(
      [trimmed_source, revision]() {
        return analyze_program_scope_frame(trimmed_source, revision);
      }));
  emit programScopeAnalysisChanged();
}

void TimelineDocumentController::clearProgramScopeAnalysis() {
  pending_program_scope_source_.clear();
  pending_program_scope_revision_ = -1;
  if (program_scope_watcher_ != nullptr) {
    auto* abandoned_watcher = program_scope_watcher_;
    program_scope_watcher_ = nullptr;
    abandoned_watcher->disconnect(this);
    connect(
        abandoned_watcher, &QFutureWatcher<QVariantMap>::finished,
        abandoned_watcher, &QObject::deleteLater);
  }
  program_scope_data_.clear();
  program_scope_published_revision_ = -1;
  emit programScopeAnalysisChanged();
}

QVariantMap TimelineDocumentController::renderProgramComparisonDifference(
    const QString& current_source,
    const QString& reference_source,
    double gain) const {
  const auto local_path = [](const QString& source) {
    const QUrl url(source.trimmed());
    return url.isLocalFile() ? url.toLocalFile() : source.trimmed();
  };
  const auto current_path = local_path(current_source);
  const auto reference_path = local_path(reference_source);
  QImageReader current_reader(current_path);
  QImageReader reference_reader(reference_path);
  current_reader.setAutoTransform(true);
  reference_reader.setAutoTransform(true);
  auto current = current_reader.read();
  auto reference = reference_reader.read();
  if (current.isNull() || reference.isNull()) {
    return {
        {QStringLiteral("success"), false},
        {QStringLiteral("errorMessage"),
         QStringLiteral("Both comparison frames must be readable images.")},
    };
  }

  const auto target_size = current.size().boundedTo(QSize(1920, 1080));
  if (!target_size.isValid() || target_size.isEmpty()) {
    return {
        {QStringLiteral("success"), false},
        {QStringLiteral("errorMessage"), QStringLiteral("The current frame has no pixels.")},
    };
  }
  const auto fit_frame = [&target_size](const QImage& source) {
    QImage fitted(target_size, QImage::Format_RGBA8888);
    fitted.fill(Qt::black);
    const auto scaled = source.scaled(
        target_size, Qt::KeepAspectRatio, Qt::SmoothTransformation);
    QPainter painter(&fitted);
    painter.setCompositionMode(QPainter::CompositionMode_Source);
    painter.drawImage(
        QPoint((target_size.width() - scaled.width()) / 2,
               (target_size.height() - scaled.height()) / 2),
        scaled.convertToFormat(QImage::Format_RGBA8888));
    return fitted;
  };
  current = fit_frame(current);
  reference = fit_frame(reference);

  std::array<double, 256> linear_lut{};
  for (auto value = 0; value < 256; ++value) {
    const auto encoded = static_cast<double>(value) / 255.0;
    linear_lut[static_cast<std::size_t>(value)] =
        encoded <= 0.04045
            ? encoded / 12.92
            : std::pow((encoded + 0.055) / 1.055, 2.4);
  }
  const auto encode_linear = [](double value) {
    const auto bounded = qBound(0.0, value, 1.0);
    const auto encoded = bounded <= 0.0031308
                             ? bounded * 12.92
                             : 1.055 * std::pow(bounded, 1.0 / 2.4) - 0.055;
    return static_cast<uchar>(qBound(0, qRound(encoded * 255.0), 255));
  };
  const auto bounded_gain = qBound(0.25, gain, 8.0);
  QImage difference(target_size, QImage::Format_RGBA8888);
  for (auto y = 0; y < target_size.height(); ++y) {
    const auto* current_row = current.constScanLine(y);
    const auto* reference_row = reference.constScanLine(y);
    auto* difference_row = difference.scanLine(y);
    for (auto x = 0; x < target_size.width(); ++x) {
      const auto offset = x * 4;
      for (auto channel = 0; channel < 3; ++channel) {
        const auto current_linear =
            linear_lut[static_cast<std::size_t>(current_row[offset + channel])];
        const auto reference_linear =
            linear_lut[static_cast<std::size_t>(reference_row[offset + channel])];
        difference_row[offset + channel] = encode_linear(
            std::abs(current_linear - reference_linear) * bounded_gain);
      }
      difference_row[offset + 3] = 255;
    }
  }

  const auto identity = QStringLiteral("%1|%2|%3|%4x%5")
                            .arg(current_path, reference_path)
                            .arg(QString::number(bounded_gain, 'f', 3))
                            .arg(target_size.width())
                            .arg(target_size.height());
  const auto digest = QCryptographicHash::hash(
                          identity.toUtf8(), QCryptographicHash::Sha256)
                          .toHex();
  const auto difference_root =
      QDir(poster_cache_root()).filePath(QStringLiteral("program-comparisons"));
  if (!QDir().mkpath(difference_root)) {
    return {
        {QStringLiteral("success"), false},
        {QStringLiteral("errorMessage"),
         QStringLiteral("Unable to create the comparison cache folder.")},
    };
  }
  const auto output_path = QDir(difference_root).filePath(
      QStringLiteral("difference-%1.png").arg(QString::fromLatin1(digest)));
  if (!QFileInfo(output_path).isReadable() && !difference.save(output_path, "PNG")) {
    return {
        {QStringLiteral("success"), false},
        {QStringLiteral("errorMessage"),
         QStringLiteral("Unable to write the comparison difference frame.")},
    };
  }
  const auto cached_frames = QDir(difference_root).entryInfoList(
      {QStringLiteral("difference-*.png")}, QDir::Files, QDir::Time);
  for (auto index = 16; index < cached_frames.size(); ++index) {
    QFile::remove(cached_frames.at(index).absoluteFilePath());
  }
  return {
      {QStringLiteral("success"), true},
      {QStringLiteral("path"), output_path},
      {QStringLiteral("url"), QUrl::fromLocalFile(output_path).toString()},
      {QStringLiteral("width"), target_size.width()},
      {QStringLiteral("height"), target_size.height()},
      {QStringLiteral("gain"), bounded_gain},
      {QStringLiteral("space"), QStringLiteral("linear-light-srgb")},
  };
}

bool TimelineDocumentController::createSequenceVersionInternal(
    const QString& requested_label,
    const QString& kind,
    const QString& requested_notes,
    const QString& requested_author,
    bool protected_milestone,
    const QJsonObject& source_document,
    const QString& duplicated_from_version_id) {
  if (!has_active_timeline_) {
    setStatus(QStringLiteral("Open a timeline before creating a version."));
    return false;
  }
  if (timeline_id_.isEmpty()) {
    timeline_id_ = QUuid::createUuid().toString(QUuid::WithoutBraces);
    emit savedPathsChanged();
  }
  if (created_at_.isEmpty()) {
    created_at_ = QDateTime::currentDateTimeUtc().toString(Qt::ISODate);
  }

  const auto normalized_kind = kind == QStringLiteral("recovery")
                                   ? QStringLiteral("recovery")
                                   : QStringLiteral("named");
  auto label = requested_label.simplified().left(80);
  if (label.isEmpty()) {
    auto named_count = 0;
    for (const auto& value : sequenceVersions()) {
      if (value.toMap().value(QStringLiteral("kind")).toString() == QStringLiteral("named")) {
        ++named_count;
      }
    }
    label = QStringLiteral("Version %1").arg(named_count + 1);
  }

  const auto root_path = sequenceVersionsRootPath();
  if (root_path.isEmpty() || !QDir().mkpath(root_path)) {
    setStatus(QStringLiteral("Unable to create the timeline versions folder."));
    return false;
  }

  const auto version_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  const auto now = QDateTime::currentDateTimeUtc();
  auto root = source_document.isEmpty() ? documentObject() : source_document;
  root.remove(QStringLiteral("_sequenceVersion"));
  auto metadata = sequence_document_metrics(root);
  auto author = requested_author.simplified().left(80);
  if (author.isEmpty()) {
    author = qEnvironmentVariable("USER").simplified().left(80);
  }
  if (author.isEmpty()) {
    author = normalized_kind == QStringLiteral("named")
                 ? QStringLiteral("Local editor")
                 : QStringLiteral("Looksy");
  }
  metadata.insert(QStringLiteral("versionId"), version_id);
  metadata.insert(QStringLiteral("label"), label);
  metadata.insert(QStringLiteral("kind"), normalized_kind);
  metadata.insert(QStringLiteral("createdAt"), now.toString(Qt::ISODateWithMs));
  metadata.insert(QStringLiteral("notes"), requested_notes.trimmed().left(1000));
  metadata.insert(QStringLiteral("author"), author);
  metadata.insert(
      QStringLiteral("protected"),
      normalized_kind == QStringLiteral("named") && protected_milestone);
  if (!duplicated_from_version_id.trimmed().isEmpty()) {
    metadata.insert(
        QStringLiteral("duplicatedFromVersionId"),
        duplicated_from_version_id.trimmed());
  }

  QString comparison_media_source;
  double comparison_frame_seconds = sequence_playhead_seconds_;
  if (!duplicated_from_version_id.trimmed().isEmpty()) {
    const auto duplicated_version =
        sequenceVersionComparison(duplicated_from_version_id.trimmed());
    comparison_media_source =
        duplicated_version.value(QStringLiteral("comparisonMediaPath")).toString();
    comparison_frame_seconds =
        duplicated_version.value(QStringLiteral("comparisonFrameSeconds")).toDouble();
  }
  if (!QFileInfo(comparison_media_source).isReadable() &&
      QFileInfo(saved_poster_path_).isReadable()) {
    comparison_media_source = saved_poster_path_;
    comparison_frame_seconds = 0.0;
  }
  if (!QFileInfo(comparison_media_source).isReadable()) {
    const auto* comparison_clip = clipAt(programClipRef());
    if (comparison_clip != nullptr) {
      const auto poster_url = QUrl(comparison_clip->poster_source);
      const auto poster_path = poster_url.isLocalFile()
                                   ? poster_url.toLocalFile()
                                   : comparison_clip->poster_source;
      if (QFileInfo(poster_path).isReadable() &&
          QImageReader(poster_path).canRead()) {
        comparison_media_source = poster_path;
      }
    }
  }
  if (QFileInfo(comparison_media_source).isReadable()) {
    auto suffix = QFileInfo(comparison_media_source).suffix().toLower();
    if (suffix.isEmpty()) {
      suffix = QStringLiteral("png");
    }
    const auto comparison_media_path = QDir(root_path).filePath(
        QStringLiteral("%1-comparison.%2").arg(version_id, suffix));
    QFile::remove(comparison_media_path);
    if (QFile::copy(comparison_media_source, comparison_media_path)) {
      metadata.insert(QStringLiteral("comparisonMediaPath"), comparison_media_path);
      metadata.insert(QStringLiteral("comparisonMediaKind"), QStringLiteral("image"));
      metadata.insert(QStringLiteral("comparisonFrameSeconds"), comparison_frame_seconds);
      metadata.insert(
          QStringLiteral("comparisonCapturedAt"), now.toString(Qt::ISODateWithMs));
    }
  }
  root.insert(QStringLiteral("_sequenceVersion"), QJsonObject::fromVariantMap(metadata));

  const auto path = QDir(root_path).filePath(
      QStringLiteral("%1-%2.json")
          .arg(now.toString(QStringLiteral("yyyyMMdd'T'HHmmsszzz'Z'")), version_id));
  QSaveFile file(path);
  if (!file.open(QIODevice::WriteOnly)) {
    setStatus(QStringLiteral("Unable to create the timeline version."));
    return false;
  }
  file.write(QJsonDocument(root).toJson(QJsonDocument::Indented));
  if (!file.commit()) {
    setStatus(QStringLiteral("Unable to finish writing the timeline version."));
    return false;
  }

  if (normalized_kind == QStringLiteral("recovery")) {
    QVector<QFileInfo> recovery_files;
    const auto files = QDir(root_path).entryInfoList(
        {QStringLiteral("*.json")}, QDir::Files | QDir::Readable, QDir::Time);
    for (const auto& info : files) {
      QFile candidate_file(info.absoluteFilePath());
      if (!candidate_file.open(QIODevice::ReadOnly)) {
        continue;
      }
      const auto candidate = QJsonDocument::fromJson(candidate_file.readAll()).object();
      if (candidate.value(QStringLiteral("_sequenceVersion"))
              .toObject()
              .value(QStringLiteral("kind"))
              .toString() == QStringLiteral("recovery")) {
        recovery_files.push_back(info);
      }
    }
    for (auto index = 10; index < recovery_files.size(); ++index) {
      QFile candidate_file(recovery_files.at(index).absoluteFilePath());
      if (candidate_file.open(QIODevice::ReadOnly)) {
        const auto candidate = QJsonDocument::fromJson(candidate_file.readAll()).object();
        const auto comparison_media_path = candidate.value(QStringLiteral("_sequenceVersion"))
                                               .toObject()
                                               .value(QStringLiteral("comparisonMediaPath"))
                                               .toString();
        if (!comparison_media_path.isEmpty()) {
          QFile::remove(comparison_media_path);
        }
      }
      QFile::remove(recovery_files.at(index).absoluteFilePath());
    }
  }

  emit sequenceVersionsChanged();
  setStatus(
      normalized_kind == QStringLiteral("named")
          ? QStringLiteral("Created timeline version '%1'.").arg(label)
          : QStringLiteral("Created a restore safety checkpoint."));
  return true;
}

bool TimelineDocumentController::createSequenceVersion(const QString& label) {
  return createSequenceVersionInternal(label, QStringLiteral("named"));
}

bool TimelineDocumentController::createSequenceVersionWithMetadata(
    const QString& label,
    const QString& notes,
    const QString& author,
    bool protected_milestone) {
  return createSequenceVersionInternal(
      label,
      QStringLiteral("named"),
      notes,
      author,
      protected_milestone);
}

bool TimelineDocumentController::updateSequenceVersionMetadata(
    const QString& version_id,
    const QString& requested_label,
    const QString& notes,
    const QString& requested_author,
    bool protected_milestone) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto comparison = sequenceVersionComparison(version_id);
  if (comparison.value(QStringLiteral("kind")).toString() != QStringLiteral("named")) {
    setStatus(QStringLiteral("Only named versions have editable milestone details."));
    return false;
  }
  const auto document_path = comparison.value(QStringLiteral("documentPath")).toString();
  QFile source_file(document_path);
  if (document_path.isEmpty() || !source_file.open(QIODevice::ReadOnly)) {
    setStatus(QStringLiteral("That timeline version is no longer available."));
    emit sequenceVersionsChanged();
    return false;
  }
  auto root = QJsonDocument::fromJson(source_file.readAll()).object();
  source_file.close();
  auto metadata = root.value(QStringLiteral("_sequenceVersion")).toObject();
  if (metadata.value(QStringLiteral("versionId")).toString() != version_id.trimmed()) {
    setStatus(QStringLiteral("The selected version metadata is invalid."));
    return false;
  }
  auto label = requested_label.simplified().left(80);
  if (label.isEmpty()) {
    label = metadata.value(QStringLiteral("label")).toString(QStringLiteral("Version"));
  }
  auto author = requested_author.simplified().left(80);
  if (author.isEmpty()) {
    author = metadata.value(QStringLiteral("author")).toString(QStringLiteral("Local editor"));
  }
  metadata.insert(QStringLiteral("label"), label);
  metadata.insert(QStringLiteral("notes"), notes.trimmed().left(1000));
  metadata.insert(QStringLiteral("author"), author);
  metadata.insert(QStringLiteral("protected"), protected_milestone);
  metadata.insert(
      QStringLiteral("metadataUpdatedAt"),
      QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));
  root.insert(QStringLiteral("_sequenceVersion"), metadata);

  QSaveFile destination(document_path);
  if (!destination.open(QIODevice::WriteOnly)) {
    setStatus(QStringLiteral("Unable to update the version details."));
    return false;
  }
  destination.write(QJsonDocument(root).toJson(QJsonDocument::Indented));
  if (!destination.commit()) {
    setStatus(QStringLiteral("Unable to finish updating the version details."));
    return false;
  }
  emit sequenceVersionsChanged();
  setStatus(QStringLiteral("Updated milestone details for '%1'.").arg(label));
  return true;
}

bool TimelineDocumentController::duplicateSequenceVersion(
    const QString& version_id,
    const QString& requested_label) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto comparison = sequenceVersionComparison(version_id);
  const auto document_path = comparison.value(QStringLiteral("documentPath")).toString();
  QFile source_file(document_path);
  if (document_path.isEmpty() || !source_file.open(QIODevice::ReadOnly)) {
    setStatus(QStringLiteral("That timeline version is no longer available."));
    emit sequenceVersionsChanged();
    return false;
  }
  auto source_document = QJsonDocument::fromJson(source_file.readAll()).object();
  source_file.close();
  if (source_document.value(QStringLiteral("timelineId")).toString() != timeline_id_) {
    setStatus(QStringLiteral("The selected version belongs to another timeline."));
    return false;
  }
  auto label = requested_label.simplified().left(80);
  if (label.isEmpty()) {
    const auto source_label =
        comparison.value(QStringLiteral("label")).toString().trimmed();
    label = QStringLiteral("%1 Copy")
                .arg(source_label.isEmpty() ? QStringLiteral("Version") : source_label)
                .left(80);
  }
  return createSequenceVersionInternal(
      label,
      QStringLiteral("named"),
      comparison.value(QStringLiteral("notes")).toString(),
      comparison.value(QStringLiteral("author")).toString(),
      false,
      source_document,
      version_id.trimmed());
}

bool TimelineDocumentController::restoreSequenceVersion(const QString& version_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto comparison = sequenceVersionComparison(version_id);
  const auto document_path = comparison.value(QStringLiteral("documentPath")).toString();
  if (document_path.isEmpty()) {
    setStatus(QStringLiteral("That timeline version is no longer available."));
    emit sequenceVersionsChanged();
    return false;
  }

  TimelineDocumentController candidate;
  if (!candidate.loadTimeline(document_path) || candidate.timeline_id_ != timeline_id_) {
    setStatus(QStringLiteral("The selected version is invalid or belongs to another timeline."));
    return false;
  }

  const auto label = comparison.value(QStringLiteral("label")).toString();
  if (!createSequenceVersionInternal(
          QStringLiteral("Before restoring %1").arg(label), QStringLiteral("recovery"))) {
    setStatus(QStringLiteral("Restore stopped because a safety checkpoint could not be created."));
    return false;
  }

  const auto previous_playhead = sequence_playhead_seconds_;
  pushUndoSnapshot();
  tracks_ = candidate.copyTracksForSnapshot();
  markers_ = candidate.markers_;
  sequence_size_ = candidate.sequence_size_;
  sequence_frame_rate_ = candidate.sequence_frame_rate_;
  audio_sample_rate_ = candidate.audio_sample_rate_;
  project_binding_ = candidate.project_binding_;
  color_space_ = candidate.color_space_;
  data_levels_ = candidate.data_levels_;
  export_container_ = candidate.export_container_;
  export_codec_ = candidate.export_codec_;
  export_preset_ = candidate.export_preset_;
  active_tool_ = candidate.active_tool_;
  edit_mode_ = candidate.edit_mode_;
  linked_selection_enabled_ = candidate.linked_selection_enabled_;
  selected_clip_id_.clear();
  selected_clip_ids_.clear();
  current_index_ = -1;
  preview_source_.clear();
  sequence_playhead_seconds_ = qBound(0.0, previous_playhead, totalDurationSeconds());
  current_clip_playhead_seconds_ = 0.0;
  sequence_playing_ = false;
  has_source_clip_ = false;
  source_tape_items_.clear();
  source_tape_index_ = -1;
  source_clip_ = Clip{};
  source_in_seconds_ = 0.0;
  source_out_seconds_ = 0.0;
  emitAllState();
  setDirty(true);
  setStatus(QStringLiteral("Restored '%1'. The previous edit is available in Versions and Undo.").arg(label));
  return true;
}

bool TimelineDocumentController::deleteSequenceVersion(const QString& version_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto comparison = sequenceVersionComparison(version_id);
  if (comparison.value(QStringLiteral("protected")).toBool()) {
    setStatus(QStringLiteral("Unprotect this milestone before removing it."));
    return false;
  }
  const auto document_path = comparison.value(QStringLiteral("documentPath")).toString();
  if (document_path.isEmpty() || !QFile::remove(document_path)) {
    setStatus(QStringLiteral("Unable to remove that timeline version."));
    return false;
  }
  const auto comparison_media_path =
      comparison.value(QStringLiteral("comparisonMediaPath")).toString();
  if (!comparison_media_path.isEmpty()) {
    QFile::remove(comparison_media_path);
  }
  emit sequenceVersionsChanged();
  setStatus(QStringLiteral("Removed timeline version '%1'.")
                .arg(comparison.value(QStringLiteral("label")).toString()));
  return true;
}

QString TimelineDocumentController::editJournalRootPath() const {
  return QDir(timelineDocumentsRootPath()).filePath(QStringLiteral("journals"));
}

QString TimelineDocumentController::editJournalPath() const {
  if (timeline_id_.isEmpty()) {
    return {};
  }
  return QDir(editJournalRootPath())
      .filePath(QStringLiteral("%1.jsonl").arg(timeline_id_));
}

QFuture<bool> TimelineDocumentController::submitEditJournalEntry(
    const QString& reason,
    const QFuture<QJsonObject>& serialized_document) {
  QJsonObject entry{
      {QStringLiteral("schema"), QStringLiteral("timeline-edit-journal:v1")},
      {QStringLiteral("entryId"), QUuid::createUuid().toString(QUuid::WithoutBraces)},
      {QStringLiteral("timelineId"), timeline_id_},
      {QStringLiteral("timestamp"), QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)},
      {QStringLiteral("reason"), reason.simplified().left(80)},
      {QStringLiteral("sequenceName"), timeline_name_},
      {QStringLiteral("baseDocumentPath"), saved_document_path_.isEmpty()
          ? QDir(timelineDocumentsRootPath()).filePath(QStringLiteral("%1.json").arg(timeline_id_))
          : saved_document_path_},
  };
  const auto path = editJournalPath();
  if (serialized_document.isValid()) {
    edit_journal_future_ = enqueue_timeline_checkpoint(
        [path, entry = std::move(entry), serialized_document]() mutable {
          entry.insert(QStringLiteral("document"), serialized_document.result());
          return persist_timeline_journal_snapshot(path, entry);
        });
  } else {
    const auto snapshot = captureDocumentSnapshot();
    edit_journal_future_ = enqueue_timeline_checkpoint(
        [path, entry = std::move(entry), snapshot]() mutable {
          entry.insert(QStringLiteral("document"), serializeDocumentSnapshot(snapshot));
          return persist_timeline_journal_snapshot(path, entry);
        });
  }
  return edit_journal_future_;
}

void TimelineDocumentController::scheduleEditJournalEntry(const QString& reason) {
  if (!has_active_timeline_ || timeline_id_.isEmpty()) return;
  // Coalesce while a write is active instead of queuing unbounded snapshots.
  if (edit_journal_watcher_.isRunning()) {
    edit_journal_timer_.start();
    return;
  }
  edit_journal_watcher_.setFuture(submitEditJournalEntry(reason));
}

bool TimelineDocumentController::appendEditJournalEntry(const QString& reason) {
  if (!has_active_timeline_ || timeline_id_.isEmpty()) return false;
  return submitEditJournalEntry(reason).result();
}

bool TimelineDocumentController::flushEditJournal() {
  edit_journal_timer_.stop();
  const auto succeeded = appendEditJournalEntry(QStringLiteral("explicit-flush"));
  if (succeeded) {
    emit recoveryCandidatesChanged();
  }
  return succeeded;
}

QVariantList TimelineDocumentController::recoveryCandidates() const {
  return discover_timeline_recoveries();
}

QVariantList TimelineDocumentController::displayedRecoveryCandidates() const {
  return recovery_candidate_records_;
}

bool TimelineDocumentController::recoveryCandidatesLoading() const {
  return recovery_candidates_loading_;
}

bool TimelineDocumentController::recoveryOpenInProgress() const {
  return recovery_open_in_progress_;
}

QString TimelineDocumentController::recoveryOpenCandidateId() const {
  return recovery_open_candidate_id_;
}

void TimelineDocumentController::refreshRecoveryCandidates() {
  if (recovery_candidates_watcher_ != nullptr) {
    recovery_candidates_refresh_pending_ = true;
    return;
  }
  recovery_candidates_loading_ = true;
  emit recoveryCandidatesChanged();
  auto* watcher = new QFutureWatcher<QVariantList>(this);
  recovery_candidates_watcher_ = watcher;
  connect(watcher, &QFutureWatcher<QVariantList>::finished, this, [this, watcher]() {
    if (watcher != recovery_candidates_watcher_) {
      watcher->deleteLater();
      return;
    }
    recovery_candidate_records_ = watcher->result();
    recovery_candidates_watcher_ = nullptr;
    recovery_candidates_loading_ = false;
    watcher->deleteLater();
    emit recoveryCandidatesChanged();
    const bool refresh_again = recovery_candidates_refresh_pending_;
    recovery_candidates_refresh_pending_ = false;
    if (refresh_again) refreshRecoveryCandidates();
  });
  watcher->setFuture(QtConcurrent::run(
      &timeline_storage_thread_pool(), []() { return discover_timeline_recoveries(); }));
}

QJsonObject TimelineDocumentController::recoveryDocumentForCandidate(
    const QString& candidate_id,
    QVariantMap* metadata) const {
  QVariantMap selected;
  QJsonObject document;
  static_cast<void>(discover_timeline_recoveries(candidate_id, &selected, &document));
  if (metadata != nullptr) *metadata = selected;
  return document;
}

bool TimelineDocumentController::openRecoveryCandidate(const QString& candidate_id) {
  const auto customer_edit_scope = customer_edit_access_.restore();
  const auto normalized_candidate_id = candidate_id.trimmed();
  if (normalized_candidate_id.isEmpty()) {
    setStatus(QStringLiteral("Select a recovery to open."));
    return false;
  }
  if (timeline_save_watcher_ != nullptr) {
    setStatus(QStringLiteral("Finish the current Save before opening recovery."));
    return false;
  }
  if (recovery_open_watcher_ != nullptr || recovery_open_in_progress_) {
    setStatus(QStringLiteral("A recovery is already opening."));
    return false;
  }
  const auto request_generation = ++recovery_open_request_generation_;
  const auto session_generation = working_session_generation_;
  const auto edit_revision = document_edit_revision_;
  recovery_open_candidate_id_ = normalized_candidate_id;
  recovery_open_in_progress_ = true;
  emit recoveryOpenStateChanged();
  setStatus(QStringLiteral("Verifying the selected recovery…"));

  auto* watcher = new QFutureWatcher<QVariantMap>(this);
  watcher->setObjectName(QStringLiteral("timelineRecoveryOpenWatcher"));
  recovery_open_watcher_ = watcher;
  connect(watcher, &QFutureWatcher<QVariantMap>::finished, this,
          [this, watcher, normalized_candidate_id, request_generation,
           session_generation, edit_revision]() {
    if (watcher != recovery_open_watcher_) {
      watcher->deleteLater();
      return;
    }
    const auto result = watcher->result();
    const auto finish_open = [this, watcher, normalized_candidate_id](bool succeeded) {
      recovery_open_watcher_ = nullptr;
      recovery_open_candidate_id_.clear();
      recovery_open_in_progress_ = false;
      if (!succeeded && dirty_ && has_active_timeline_ &&
          !edit_journal_timer_.isActive()) {
        edit_journal_timer_.start();
      }
      watcher->deleteLater();
      emit recoveryOpenStateChanged();
      emit recoveryOpenCompleted(normalized_candidate_id, succeeded);
    };

    if (request_generation != recovery_open_request_generation_) {
      setStatus(QStringLiteral("Recovery opening was canceled."));
      finish_open(false);
      return;
    } else if (session_generation != working_session_generation_) {
      setStatus(QStringLiteral("Recovery opening stopped because the active timeline changed."));
      finish_open(false);
      return;
    } else if (edit_revision != document_edit_revision_) {
      setStatus(QStringLiteral("Recovery opening stopped because the timeline changed. Your edits remain open."));
      finish_open(false);
      return;
    } else if (timeline_save_watcher_ != nullptr) {
      setStatus(QStringLiteral("Finish the current Save before opening recovery."));
      finish_open(false);
      return;
    }

    const auto stage = result.value(QStringLiteral("stage")).toString();
    if (result.value(QStringLiteral("success")).toBool() &&
        stage == QStringLiteral("verified") && has_active_timeline_ && dirty_) {
      edit_journal_timer_.stop();
      const auto checkpoint_future =
          submitEditJournalEntry(QStringLiteral("open-recovery"));
      if (!checkpoint_future.isValid()) {
        edit_journal_timer_.start();
        setStatus(QStringLiteral(
            "Unable to checkpoint the current timeline. Your edits remain open."));
        finish_open(false);
        return;
      }

      setStatus(QStringLiteral(
          "Committing a recovery checkpoint before opening the verified recovery…"));
      watcher->setFuture(QtConcurrent::run(
          &timeline_storage_thread_pool(),
          [checkpoint_result = result, checkpoint_future]() mutable {
            auto checkpoint_succeeded = false;
#ifndef QT_NO_EXCEPTIONS
            try {
              checkpoint_succeeded = checkpoint_future.result();
            } catch (...) {
              checkpoint_succeeded = false;
            }
#else
            checkpoint_succeeded = checkpoint_future.result();
#endif
            if (!checkpoint_succeeded) {
              checkpoint_result.insert(QStringLiteral("success"), false);
              checkpoint_result.insert(
                  QStringLiteral("status"),
                  QStringLiteral(
                      "Unable to checkpoint the current timeline. Your edits remain open."));
              checkpoint_result.insert(QStringLiteral("stage"), QStringLiteral("checkpointed"));
              return checkpoint_result;
            }
            checkpoint_result.insert(QStringLiteral("stage"), QStringLiteral("checkpointed"));
            return checkpoint_result;
          }));
      return;
    }

    if (!result.value(QStringLiteral("success")).toBool()) {
      auto status = result.value(QStringLiteral("status")).toString();
      if (status.isEmpty()) {
        status = QStringLiteral(
            "That recovery is no longer available. Refresh the recovery list and try again.");
      }
      if (stage == QStringLiteral("checkpointed") && dirty_ && has_active_timeline_ &&
          !edit_journal_timer_.isActive()) {
        edit_journal_timer_.start();
      }
      setStatus(status);
      refreshRecoveryCandidates();
      finish_open(false);
      return;
    }

    const auto metadata = result.value(QStringLiteral("metadata")).toMap();
    const auto document = result.value(QStringLiteral("document")).value<QJsonObject>();
    const auto canonical_path =
        metadata.value(QStringLiteral("canonicalDocumentPath")).toString();
    const auto expected_timeline_id =
        metadata.value(QStringLiteral("timelineId")).toString();
    if (document.isEmpty() || canonical_path.isEmpty() ||
        document.value(QStringLiteral("timelineId")).toString() != expected_timeline_id) {
      setStatus(QStringLiteral("The selected recovery did not pass its document identity check."));
      finish_open(false);
      return;
    }

    // The current dirty revision, when present, was durably checkpointed by
    // the worker stage above. Never make the recovery selection wait on a
    // synchronous flush inside loadDocumentObject.
    recovery_open_watcher_ = nullptr;
    watcher->deleteLater();
    if (!loadDocumentObject(document, canonical_path, false)) {
      recovery_open_candidate_id_.clear();
      recovery_open_in_progress_ = false;
      if (dirty_ && has_active_timeline_ && !edit_journal_timer_.isActive())
        edit_journal_timer_.start();
      emit recoveryOpenStateChanged();
      emit recoveryOpenCompleted(normalized_candidate_id, false);
      return;
    }
    saved_document_path_ = normalized_path(canonical_path);
    emit savedPathsChanged();
    setDirty(true);
    refreshRecentTimelines();
    setStatus(QStringLiteral(
                  "Opened recovered state for '%1'. The saved project remains unchanged until you save.")
                  .arg(timeline_name_));
    recovery_open_candidate_id_.clear();
    recovery_open_in_progress_ = false;
    emit recoveryOpenStateChanged();
    emit recoveryOpenCompleted(normalized_candidate_id, true);
  });
  watcher->setFuture(QtConcurrent::run(
      &timeline_storage_thread_pool(), [normalized_candidate_id]() {
        QVariantMap metadata;
        QJsonObject document;
        static_cast<void>(discover_timeline_recoveries(
            normalized_candidate_id, &metadata, &document));
        if (metadata.isEmpty() || document.isEmpty()) {
          return QVariantMap{
              {QStringLiteral("success"), false},
              {QStringLiteral("status"), QStringLiteral(
                   "That recovery is no longer available. Refresh the recovery list and try again.")},
          };
        }
        return QVariantMap{
            {QStringLiteral("success"), true},
            {QStringLiteral("stage"), QStringLiteral("verified")},
            {QStringLiteral("metadata"), metadata},
            {QStringLiteral("document"), QVariant::fromValue(document)},
        };
      }));
  return true;
}

void TimelineDocumentController::cancelRecoveryOpen() {
  auto* watcher = recovery_open_watcher_;
  if (watcher == nullptr) return;
  const auto candidate_id = recovery_open_candidate_id_;
  ++recovery_open_request_generation_;
  recovery_open_watcher_ = nullptr;
  recovery_open_candidate_id_.clear();
  recovery_open_in_progress_ = false;
  emit recoveryOpenStateChanged();
  setStatus(QStringLiteral("Recovery opening was canceled."));
  if (dirty_ && has_active_timeline_ && !edit_journal_timer_.isActive())
    edit_journal_timer_.start();
  emit recoveryOpenCompleted(candidate_id, false);
  // The worker only owns local values. Keep its watcher connected long enough
  // to delete it after completion, without allowing its result to replace a
  // newer working session.
}

bool TimelineDocumentController::restoreRecoveryCandidateAsCopy(const QString& candidate_id) {
  const auto customer_edit_scope = customer_edit_access_.restore();
  QVariantMap metadata;
  auto document = recoveryDocumentForCandidate(candidate_id, &metadata);
  if (document.isEmpty()) {
    setStatus(QStringLiteral("That recovery is no longer available."));
    refreshRecoveryCandidates();
    return false;
  }
  const auto new_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  const auto original_name = default_timeline_name(document.value(QStringLiteral("name")).toString());
  const auto recovered_name = QStringLiteral("%1 — Recovered Copy").arg(original_name);
  const auto now = QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);
  const auto copy_path = QDir(timelineDocumentsRootPath())
                             .filePath(QStringLiteral("%1.json").arg(new_id));
  document.insert(QStringLiteral("timelineId"), new_id);
  document.insert(QStringLiteral("name"), recovered_name);
  document.insert(QStringLiteral("createdAt"), now);
  document.insert(QStringLiteral("updatedAt"), now);
  document.insert(QStringLiteral("renderPath"), QString{});
  document.insert(QStringLiteral("posterPath"), QString{});
  document.remove(QStringLiteral("_sequenceVersion"));
  if (!QDir().mkpath(timelineDocumentsRootPath())) {
    setStatus(QStringLiteral("Unable to create the recovered copy folder."));
    return false;
  }
  QSaveFile copy_file(copy_path);
  if (!copy_file.open(QIODevice::WriteOnly) ||
      copy_file.write(QJsonDocument(document).toJson(QJsonDocument::Indented)) <= 0 ||
      !copy_file.commit()) {
    setStatus(QStringLiteral("Unable to write the recovered copy."));
    return false;
  }

  auto records = loadTimelineAssetRecords();
  const auto metrics = sequence_document_metrics(document);
  TimelineAssetRecord record;
  record.asset_id = QStringLiteral("timeline:%1").arg(new_id);
  record.timeline_id = new_id;
  record.name = recovered_name;
  record.document_path = copy_path;
  record.duration_seconds = metrics.value(QStringLiteral("durationSeconds")).toDouble();
  record.created_at = now;
  record.updated_at = now;
  records.push_back(record);
  if (!saveTimelineAssetRecords(records) || !saveTimelineDocumentBackup(record, document)) {
    QFile::remove(copy_path);
    setStatus(QStringLiteral("Unable to register the recovered copy."));
    return false;
  }
  if (!loadTimeline(copy_path)) {
    return false;
  }
  refreshRecentTimelines();
  setStatus(QStringLiteral("Created and opened '%1'. The original project was not changed.")
                .arg(recovered_name));
  return true;
}

bool TimelineDocumentController::discardRecoveryCandidate(const QString& candidate_id) {
  QVariantMap metadata;
  if (recoveryDocumentForCandidate(candidate_id, &metadata).isEmpty()) {
    setStatus(QStringLiteral("That recovery is no longer available."));
    refreshRecoveryCandidates();
    return false;
  }
  const auto source_path = metadata.value(QStringLiteral("sourcePath")).toString();
  auto succeeded = false;
  if (metadata.value(QStringLiteral("kind")).toString() == QStringLiteral("journal")) {
    const auto archive_path = source_path + QStringLiteral(".discarded-") +
                              QDateTime::currentDateTimeUtc().toString(
                                  QStringLiteral("yyyyMMdd'T'HHmmsszzz'Z'"));
    succeeded = QFile::rename(source_path, archive_path);
  } else {
    succeeded = QFile::remove(source_path);
  }
  if (!succeeded) {
    setStatus(QStringLiteral("Unable to discard that recovery."));
    return false;
  }
  refreshRecoveryCandidates();
  refreshRecentTimelines();
  setStatus(QStringLiteral("Discarded the selected recovery. The last saved project was not changed."));
  return true;
}

QVariantList TimelineDocumentController::offlineMediaItems() const {
  QVariantList items;
  QSet<QString> seen_paths;
  QHash<QString, int> use_count_by_path;
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (!clip.file_path.isEmpty()) {
        ++use_count_by_path[normalized_path(clip.file_path)];
      }
    }
  }
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (clip.file_path.isEmpty() || QFileInfo(clip.file_path).isReadable()) {
        continue;
      }
      const auto original_path = normalized_path(clip.file_path);
      if (seen_paths.contains(original_path)) {
        continue;
      }
      seen_paths.insert(original_path);
      items.push_back(QVariantMap{
          {QStringLiteral("originalPath"), original_path},
          {QStringLiteral("displayLabel"), clip.display_label},
          {QStringLiteral("fileName"), QFileInfo(original_path).fileName()},
          {QStringLiteral("mediaType"), clip.media_type},
          {QStringLiteral("durationSeconds"), clip.duration_seconds},
          {QStringLiteral("sourceFileSize"), clip.source_file_size},
          {QStringLiteral("sourceIdentitySignature"), clip.source_identity_signature},
          {QStringLiteral("sourceContentSha256"), clip.source_content_sha256},
          {QStringLiteral("sourceIntegrityStatus"), clip.source_integrity_status},
          {QStringLiteral("sourceWidth"), clip.source_size.width()},
          {QStringLiteral("sourceHeight"), clip.source_size.height()},
          {QStringLiteral("useCount"), use_count_by_path.value(original_path)},
      });
    }
  }
  return items;
}

bool TimelineDocumentController::hasOfflineMediaItems() const {
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (!clip.file_path.isEmpty() && !QFileInfo(clip.file_path).isReadable()) {
        return true;
      }
    }
  }
  return false;
}

QVariantList TimelineDocumentController::mediaBins() const {
  QVariantList result;
  QHash<QString, const MediaBin*> bin_by_id;
  QHash<QString, int> asset_count_by_bin;
  QHash<QString, int> child_count_by_bin;
  bin_by_id.reserve(media_bins_.size());
  for (const auto& bin : media_bins_) {
    bin_by_id.insert(bin.bin_id, &bin);
  }
  for (auto assignment = media_asset_bins_.cbegin();
       assignment != media_asset_bins_.cend(); ++assignment) {
    ++asset_count_by_bin[assignment.value()];
  }
  for (const auto& bin : media_bins_) {
    if (!bin.parent_bin_id.isEmpty()) {
      ++child_count_by_bin[bin.parent_bin_id];
    }
  }
  for (const auto& bin : media_bins_) {
    auto depth = 0;
    auto parent_id = bin.parent_bin_id;
    QSet<QString> visited;
    while (!parent_id.isEmpty() && depth < 16 && !visited.contains(parent_id)) {
      visited.insert(parent_id);
      const auto parent = bin_by_id.constFind(parent_id);
      if (parent == bin_by_id.cend()) {
        break;
      }
      ++depth;
      parent_id = (*parent)->parent_bin_id;
    }
    result.push_back(QVariantMap{
        {QStringLiteral("binId"), bin.bin_id},
        {QStringLiteral("parentBinId"), bin.parent_bin_id},
        {QStringLiteral("name"), bin.name},
        {QStringLiteral("depth"), depth},
        {QStringLiteral("assetCount"), asset_count_by_bin.value(bin.bin_id)},
        {QStringLiteral("childCount"), child_count_by_bin.value(bin.bin_id)},
        {QStringLiteral("active"), bin.bin_id == active_media_bin_id_},
    });
  }
  return result;
}

QString TimelineDocumentController::activeMediaBinId() const {
  return active_media_bin_id_;
}

void TimelineDocumentController::setActiveMediaBinId(const QString& bin_id) {
  const auto normalized = bin_id.trimmed();
  if (!normalized.isEmpty() &&
      std::none_of(
          media_bins_.cbegin(), media_bins_.cend(), [&normalized](const MediaBin& bin) {
            return bin.bin_id == normalized;
          })) {
    return;
  }
  if (active_media_bin_id_ == normalized) {
    return;
  }
  active_media_bin_id_ = normalized;
  emit mediaBinsChanged();
  emit activeMediaBinChanged();
}

QString TimelineDocumentController::createMediaBin(
    const QString& name,
    const QString& parent_bin_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized_parent = parent_bin_id.trimmed();
  if (!normalized_parent.isEmpty() &&
      std::none_of(
          media_bins_.cbegin(), media_bins_.cend(), [&normalized_parent](const MediaBin& bin) {
            return bin.bin_id == normalized_parent;
          })) {
    setStatus(QStringLiteral("Choose an existing parent bin."));
    return {};
  }
  const auto base_name = name.simplified().isEmpty()
                             ? QStringLiteral("New Bin")
                             : name.simplified();
  auto unique_name = base_name;
  auto suffix = 2;
  const auto sibling_name_exists = [this, &normalized_parent](const QString& candidate_name) {
    return std::any_of(
        media_bins_.cbegin(), media_bins_.cend(),
        [&normalized_parent, &candidate_name](const MediaBin& bin) {
          return bin.parent_bin_id == normalized_parent &&
                 bin.name.compare(candidate_name, Qt::CaseInsensitive) == 0;
        });
  };
  while (sibling_name_exists(unique_name)) {
    unique_name = QStringLiteral("%1 %2").arg(base_name).arg(suffix++);
  }
  pushUndoSnapshot();
  const auto id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  media_bins_.push_back({id, normalized_parent, unique_name});
  const auto active_bin_changed = active_media_bin_id_ != id;
  active_media_bin_id_ = id;
  setDirty(true);
  emit mediaBinsChanged();
  if (active_bin_changed) {
    emit activeMediaBinChanged();
  }
  setStatus(unique_name == base_name
                ? QStringLiteral("Created media bin '%1'.").arg(unique_name)
                : QStringLiteral("Created media bin '%1' because that sibling name already existed.")
                      .arg(unique_name));
  return id;
}

bool TimelineDocumentController::renameMediaBin(
    const QString& bin_id,
    const QString& name) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  auto target = std::find_if(
      media_bins_.begin(), media_bins_.end(), [&bin_id](const MediaBin& bin) {
        return bin.bin_id == bin_id;
      });
  if (target == media_bins_.end() || name.simplified().isEmpty()) {
    return false;
  }
  const auto base_name = name.simplified();
  auto unique_name = base_name;
  auto suffix = 2;
  const auto parent_id = target->parent_bin_id;
  while (std::any_of(
      media_bins_.cbegin(), media_bins_.cend(),
      [&bin_id, &parent_id, &unique_name](const MediaBin& bin) {
        return bin.bin_id != bin_id && bin.parent_bin_id == parent_id &&
               bin.name.compare(unique_name, Qt::CaseInsensitive) == 0;
      })) {
    unique_name = QStringLiteral("%1 %2").arg(base_name).arg(suffix++);
  }
  if (target->name == unique_name) {
    return true;
  }
  pushUndoSnapshot();
  target = std::find_if(
      media_bins_.begin(), media_bins_.end(), [&bin_id](const MediaBin& bin) {
        return bin.bin_id == bin_id;
      });
  target->name = unique_name;
  setDirty(true);
  emit mediaBinsChanged();
  setStatus(QStringLiteral("Renamed media bin to '%1'.").arg(unique_name));
  return true;
}

bool TimelineDocumentController::moveMediaBin(
    const QString& bin_id,
    const QString& parent_bin_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized_parent = parent_bin_id.trimmed();
  auto target = std::find_if(
      media_bins_.begin(), media_bins_.end(), [&bin_id](const MediaBin& bin) {
        return bin.bin_id == bin_id;
      });
  if (target == media_bins_.end() || bin_id == normalized_parent) {
    return false;
  }
  auto ancestor_id = normalized_parent;
  QSet<QString> visited;
  while (!ancestor_id.isEmpty() && !visited.contains(ancestor_id)) {
    if (ancestor_id == bin_id) {
      setStatus(QStringLiteral("A bin cannot move inside one of its descendants."));
      return false;
    }
    visited.insert(ancestor_id);
    const auto ancestor = std::find_if(
        media_bins_.cbegin(), media_bins_.cend(), [&ancestor_id](const MediaBin& bin) {
          return bin.bin_id == ancestor_id;
        });
    if (ancestor == media_bins_.cend()) {
      return false;
    }
    ancestor_id = ancestor->parent_bin_id;
  }
  if (target->parent_bin_id == normalized_parent) {
    return true;
  }
  pushUndoSnapshot();
  target = std::find_if(
      media_bins_.begin(), media_bins_.end(), [&bin_id](const MediaBin& bin) {
        return bin.bin_id == bin_id;
      });
  target->parent_bin_id = normalized_parent;
  setDirty(true);
  emit mediaBinsChanged();
  setStatus(QStringLiteral("Moved media bin '%1'.").arg(target->name));
  return true;
}

bool TimelineDocumentController::deleteMediaBin(const QString& bin_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto target = std::find_if(
      media_bins_.cbegin(), media_bins_.cend(), [&bin_id](const MediaBin& bin) {
        return bin.bin_id == bin_id;
      });
  if (target == media_bins_.cend()) {
    return false;
  }
  const auto parent_id = target->parent_bin_id;
  const auto name = target->name;
  pushUndoSnapshot();
  for (auto& bin : media_bins_) {
    if (bin.parent_bin_id == bin_id) {
      bin.parent_bin_id = parent_id;
    }
  }
  for (auto assignment = media_asset_bins_.begin();
       assignment != media_asset_bins_.end(); ++assignment) {
    if (assignment.value() == bin_id) {
      assignment.value() = parent_id;
    }
  }
  media_bins_.erase(
      std::remove_if(
          media_bins_.begin(), media_bins_.end(), [&bin_id](const MediaBin& bin) {
            return bin.bin_id == bin_id;
          }),
      media_bins_.end());
  const auto active_bin_changed = active_media_bin_id_ == bin_id;
  if (active_bin_changed) {
    active_media_bin_id_ = parent_id;
  }
  setDirty(true);
  emit mediaBinsChanged();
  if (active_bin_changed) {
    emit activeMediaBinChanged();
  }
  setStatus(QStringLiteral("Deleted media bin '%1'; its contents moved to the parent.")
                .arg(name));
  return true;
}

bool TimelineDocumentController::assignMediaAssetToBin(
    const QString& asset_id,
    const QString& bin_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized_asset = asset_id.trimmed();
  const auto normalized_bin = bin_id.trimmed();
  if (normalized_asset.isEmpty() ||
      (!normalized_bin.isEmpty() &&
       std::none_of(
           media_bins_.cbegin(), media_bins_.cend(), [&normalized_bin](const MediaBin& bin) {
             return bin.bin_id == normalized_bin;
           }))) {
    return false;
  }
  if (media_asset_bins_.value(normalized_asset) == normalized_bin) {
    return true;
  }
  pushUndoSnapshot();
  if (normalized_bin.isEmpty()) {
    media_asset_bins_.remove(normalized_asset);
  } else {
    media_asset_bins_.insert(normalized_asset, normalized_bin);
  }
  setDirty(true);
  emit mediaBinsChanged();
  setStatus(normalized_bin.isEmpty()
                ? QStringLiteral("Moved media to All Media.")
                : QStringLiteral("Moved media into the selected bin."));
  return true;
}

bool TimelineDocumentController::mediaAssetVisibleInBin(
    const QString& asset_id,
    const QString& bin_id) const {
  if (removed_media_asset_ids_.contains(asset_id.trimmed())) {
    return false;
  }
  const auto selected_bin = bin_id.trimmed();
  if (selected_bin.isEmpty()) {
    return true;
  }
  auto assigned_bin = media_asset_bins_.value(asset_id.trimmed());
  QSet<QString> visited;
  while (!assigned_bin.isEmpty() && !visited.contains(assigned_bin)) {
    if (assigned_bin == selected_bin) {
      return true;
    }
    visited.insert(assigned_bin);
    const auto parent = std::find_if(
        media_bins_.cbegin(), media_bins_.cend(), [&assigned_bin](const MediaBin& bin) {
          return bin.bin_id == assigned_bin;
        });
    if (parent == media_bins_.cend()) {
      break;
    }
    assigned_bin = parent->parent_bin_id;
  }
  return false;
}

QVariantList TimelineDocumentController::smartCollections() const {
  QVariantList result;
  result.reserve(smart_collections_.size());
  for (const auto& collection : smart_collections_) {
    result.push_back(QVariantMap{
        {QStringLiteral("collectionId"), collection.collection_id},
        {QStringLiteral("name"), collection.name},
        {QStringLiteral("rules"), collection.rules},
        {QStringLiteral("ruleCount"), collection.rules.size()},
        {QStringLiteral("active"), collection.collection_id == active_smart_collection_id_},
    });
  }
  return result;
}

QString TimelineDocumentController::activeSmartCollectionId() const {
  return active_smart_collection_id_;
}

void TimelineDocumentController::setActiveSmartCollectionId(const QString& collection_id) {
  const auto normalized = collection_id.trimmed();
  if (!normalized.isEmpty() &&
      std::none_of(
          smart_collections_.cbegin(), smart_collections_.cend(),
          [&normalized](const SmartCollection& collection) {
            return collection.collection_id == normalized;
          })) {
    return;
  }
  if (active_smart_collection_id_ == normalized) {
    return;
  }
  active_smart_collection_id_ = normalized;
  emit smartCollectionsChanged();
}

QString TimelineDocumentController::createSmartCollection(
    const QString& name,
    const QVariantMap& rules) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto base_name = name.simplified().isEmpty()
                             ? QStringLiteral("New Smart Collection")
                             : name.simplified().left(80);
  auto unique_name = base_name;
  auto suffix = 2;
  while (std::any_of(
      smart_collections_.cbegin(), smart_collections_.cend(),
      [&unique_name](const SmartCollection& collection) {
        return collection.name.compare(unique_name, Qt::CaseInsensitive) == 0;
      })) {
    unique_name = QStringLiteral("%1 %2").arg(base_name).arg(suffix++);
  }
  const auto normalized_rules = normalized_smart_collection_rules(rules);
  if (normalized_rules.isEmpty()) {
    setStatus(QStringLiteral("Add at least one rule before saving a smart collection."));
    return {};
  }
  pushUndoSnapshot();
  const auto id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  smart_collections_.push_back({id, unique_name, normalized_rules});
  active_smart_collection_id_ = id;
  setDirty(true);
  emit smartCollectionsChanged();
  setStatus(QStringLiteral("Created smart collection '%1'.").arg(unique_name));
  return id;
}

bool TimelineDocumentController::updateSmartCollection(
    const QString& collection_id,
    const QString& name,
    const QVariantMap& rules) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  auto target = std::find_if(
      smart_collections_.begin(), smart_collections_.end(),
      [&collection_id](const SmartCollection& collection) {
        return collection.collection_id == collection_id.trimmed();
      });
  const auto normalized_name = name.simplified().left(80);
  const auto normalized_rules = normalized_smart_collection_rules(rules);
  if (target == smart_collections_.end() || normalized_name.isEmpty() ||
      normalized_rules.isEmpty()) {
    return false;
  }
  auto unique_name = normalized_name;
  auto suffix = 2;
  while (std::any_of(
      smart_collections_.cbegin(), smart_collections_.cend(),
      [&collection_id, &unique_name](const SmartCollection& collection) {
        return collection.collection_id != collection_id.trimmed() &&
               collection.name.compare(unique_name, Qt::CaseInsensitive) == 0;
      })) {
    unique_name = QStringLiteral("%1 %2").arg(normalized_name).arg(suffix++);
  }
  if (target->name == unique_name && target->rules == normalized_rules) {
    return true;
  }
  pushUndoSnapshot();
  target = std::find_if(
      smart_collections_.begin(), smart_collections_.end(),
      [&collection_id](const SmartCollection& collection) {
        return collection.collection_id == collection_id.trimmed();
      });
  target->name = unique_name;
  target->rules = normalized_rules;
  setDirty(true);
  emit smartCollectionsChanged();
  setStatus(QStringLiteral("Updated smart collection '%1'.").arg(unique_name));
  return true;
}

bool TimelineDocumentController::deleteSmartCollection(const QString& collection_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized = collection_id.trimmed();
  const auto target = std::find_if(
      smart_collections_.cbegin(), smart_collections_.cend(),
      [&normalized](const SmartCollection& collection) {
        return collection.collection_id == normalized;
      });
  if (target == smart_collections_.cend()) {
    return false;
  }
  const auto name = target->name;
  pushUndoSnapshot();
  smart_collections_.erase(
      std::remove_if(
          smart_collections_.begin(), smart_collections_.end(),
          [&normalized](const SmartCollection& collection) {
            return collection.collection_id == normalized;
          }),
      smart_collections_.end());
  if (active_smart_collection_id_ == normalized) {
    active_smart_collection_id_.clear();
  }
  setDirty(true);
  emit smartCollectionsChanged();
  setStatus(QStringLiteral("Deleted smart collection '%1'.").arg(name));
  return true;
}

bool TimelineDocumentController::mediaAssetMatchesSmartCollection(
    const QVariantMap& catalog_asset,
    const QString& collection_id) const {
  const auto normalized_id = collection_id.trimmed();
  if (normalized_id.isEmpty()) {
    return true;
  }
  const auto collection = std::find_if(
      smart_collections_.cbegin(), smart_collections_.cend(),
      [&normalized_id](const SmartCollection& candidate) {
        return candidate.collection_id == normalized_id;
      });
  if (collection == smart_collections_.cend()) {
    return false;
  }
  const auto asset_id = catalog_asset.value(QStringLiteral("assetId")).toString().trimmed();
  if (asset_id.isEmpty() || removed_media_asset_ids_.contains(asset_id)) {
    return false;
  }
  const auto& rules = collection->rules;
  const auto media_type =
      catalog_asset.value(QStringLiteral("mediaType")).toString().trimmed().toLower();
  if (rules.contains(QStringLiteral("mediaType")) &&
      media_type != rules.value(QStringLiteral("mediaType")).toString()) {
    return false;
  }
  const auto editorial = media_asset_metadata_.value(asset_id);
  const auto catalog_rating = catalog_asset.value(QStringLiteral("rating")).toInt();
  const auto rating = editorial.rating > 0 ? editorial.rating : catalog_rating;
  if (rating < rules.value(QStringLiteral("minimumRating"), 0).toInt()) {
    return false;
  }
  if (rules.contains(QStringLiteral("colorLabel"))) {
    const auto catalog_label = catalog_asset.value(QStringLiteral("colorLabel"))
                                   .toString().trimmed().toLower();
    const auto label = editorial.color_label != QStringLiteral("none")
                           ? editorial.color_label : catalog_label;
    if (label != rules.value(QStringLiteral("colorLabel")).toString()) {
      return false;
    }
  }
  if (rules.contains(QStringLiteral("tag"))) {
    const auto wanted = rules.value(QStringLiteral("tag")).toString().toCaseFolded();
    if (std::none_of(
            editorial.tags.cbegin(), editorial.tags.cend(),
            [&wanted](const QString& tag) { return tag.toCaseFolded() == wanted; })) {
      return false;
    }
  }
  if (rules.contains(QStringLiteral("customField"))) {
    const auto wanted_key =
        rules.value(QStringLiteral("customField")).toString().toCaseFolded();
    const auto wanted_value =
        rules.value(QStringLiteral("customValue")).toString().toCaseFolded();
    auto custom_match = false;
    for (auto field = editorial.custom_fields.cbegin();
         field != editorial.custom_fields.cend(); ++field) {
      if (field.key().toCaseFolded() == wanted_key &&
          field.value().toString().toCaseFolded().contains(wanted_value)) {
        custom_match = true;
        break;
      }
    }
    if (!custom_match) {
      return false;
    }
  }
  const auto capture_date = QDate::fromString(
      catalog_asset.value(QStringLiteral("captureDate")).toString().trimmed(), Qt::ISODate);
  if (rules.contains(QStringLiteral("dateFrom")) &&
      (!capture_date.isValid() || capture_date < QDate::fromString(
           rules.value(QStringLiteral("dateFrom")).toString(), Qt::ISODate))) {
    return false;
  }
  if (rules.contains(QStringLiteral("dateTo")) &&
      (!capture_date.isValid() || capture_date > QDate::fromString(
           rules.value(QStringLiteral("dateTo")).toString(), Qt::ISODate))) {
    return false;
  }
  const auto duration = qMax(
      0.0, catalog_asset.value(QStringLiteral("durationSeconds")).toDouble());
  if (duration + kBoundaryEpsilon <
      rules.value(QStringLiteral("minimumDuration"), 0.0).toDouble()) {
    return false;
  }
  const auto maximum_duration =
      rules.value(QStringLiteral("maximumDuration"), 0.0).toDouble();
  if (maximum_duration > 0.0 && duration - kBoundaryEpsilon > maximum_duration) {
    return false;
  }
  if (rules.contains(QStringLiteral("orientation"))) {
    auto width = catalog_asset.value(QStringLiteral("sourceWidth")).toInt();
    auto height = catalog_asset.value(QStringLiteral("sourceHeight")).toInt();
    if (width <= 0 || height <= 0) {
      for (const auto& track : tracks_) {
        const auto clip = std::find_if(
            track.clips.cbegin(), track.clips.cend(), [&asset_id](const Clip& candidate) {
              return candidate.asset_id == asset_id && candidate.source_size.isValid();
            });
        if (clip != track.clips.cend()) {
          width = clip->source_size.width();
          height = clip->source_size.height();
          break;
        }
      }
    }
    if ((width <= 0 || height <= 0) && media_type == QStringLiteral("photo")) {
      const QImageReader reader(catalog_asset.value(QStringLiteral("filePath")).toString());
      const auto size = reader.size();
      width = size.width();
      height = size.height();
    }
    const auto orientation = width == height && width > 0
                                 ? QStringLiteral("square")
                                 : width > height ? QStringLiteral("landscape")
                                                  : height > width ? QStringLiteral("portrait")
                                                                   : QString{};
    if (orientation != rules.value(QStringLiteral("orientation")).toString()) {
      return false;
    }
  }
  if (rules.contains(QStringLiteral("onlineState"))) {
    const auto online = catalog_asset.contains(QStringLiteral("online"))
                            ? catalog_asset.value(QStringLiteral("online")).toBool()
                            : QFileInfo::exists(
                                  catalog_asset.value(QStringLiteral("filePath")).toString());
    if ((rules.value(QStringLiteral("onlineState")).toString() ==
         QStringLiteral("online")) != online) {
      return false;
    }
  }
  if (rules.contains(QStringLiteral("usage"))) {
    auto used = false;
    for (const auto& track : tracks_) {
      if (std::any_of(
              track.clips.cbegin(), track.clips.cend(),
              [&asset_id](const Clip& clip) { return clip.asset_id == asset_id; })) {
        used = true;
        break;
      }
    }
    if ((rules.value(QStringLiteral("usage")).toString() == QStringLiteral("used")) != used) {
      return false;
    }
  }
  return true;
}

QVariantList TimelineDocumentController::reviewRanges() const {
  QVariantList result;
  result.reserve(review_ranges_.size());
  for (const auto& range : review_ranges_) {
    result.push_back(QVariantMap{
        {QStringLiteral("rangeId"), range.range_id},
        {QStringLiteral("name"), range.name},
        {QStringLiteral("startSeconds"), range.start_seconds},
        {QStringLiteral("endSeconds"), range.end_seconds},
        {QStringLiteral("durationSeconds"), range.end_seconds - range.start_seconds},
        {QStringLiteral("prerollSeconds"), range.preroll_seconds},
        {QStringLiteral("postrollSeconds"), range.postroll_seconds},
    });
  }
  return result;
}

QString TimelineDocumentController::createReviewRange(
    const QString& name,
    double start_seconds,
    double end_seconds,
    double preroll_seconds,
    double postroll_seconds) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto fps = qMax(1.0, framesPerSecond());
  const auto snap = [fps](double seconds) {
    return std::round(qMax(0.0, seconds) * fps) / fps;
  };
  const auto start = qBound(0.0, snap(start_seconds), totalDurationSeconds());
  const auto end = qBound(0.0, snap(end_seconds), totalDurationSeconds());
  if (end <= start) {
    setStatus(QStringLiteral("A review range needs an Out point after its In point."));
    return {};
  }
  const auto base_name = name.simplified().isEmpty()
                             ? QStringLiteral("Review Range")
                             : name.simplified().left(80);
  auto unique_name = base_name;
  auto suffix = 2;
  while (std::any_of(
      review_ranges_.cbegin(), review_ranges_.cend(),
      [&unique_name](const ReviewRange& range) {
        return range.name.compare(unique_name, Qt::CaseInsensitive) == 0;
      })) {
    unique_name = QStringLiteral("%1 %2").arg(base_name).arg(suffix++);
  }
  pushUndoSnapshot();
  const auto id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  review_ranges_.push_back({
      id, unique_name, start, end,
      qBound(0.0, snap(preroll_seconds), 60.0),
      qBound(0.0, snap(postroll_seconds), 60.0),
  });
  setDirty(true);
  emit reviewRangesChanged();
  setStatus(QStringLiteral("Saved review range '%1'.").arg(unique_name));
  return id;
}

bool TimelineDocumentController::updateReviewRange(
    const QString& range_id,
    const QString& name,
    double start_seconds,
    double end_seconds,
    double preroll_seconds,
    double postroll_seconds) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  auto target = std::find_if(
      review_ranges_.begin(), review_ranges_.end(),
      [&range_id](const ReviewRange& range) {
        return range.range_id == range_id.trimmed();
      });
  const auto normalized_name = name.simplified().left(80);
  const auto fps = qMax(1.0, framesPerSecond());
  const auto snap = [fps](double seconds) {
    return std::round(qMax(0.0, seconds) * fps) / fps;
  };
  const auto start = qBound(0.0, snap(start_seconds), totalDurationSeconds());
  const auto end = qBound(0.0, snap(end_seconds), totalDurationSeconds());
  if (target == review_ranges_.end() || normalized_name.isEmpty() || end <= start) {
    return false;
  }
  auto unique_name = normalized_name;
  auto suffix = 2;
  while (std::any_of(
      review_ranges_.cbegin(), review_ranges_.cend(),
      [&range_id, &unique_name](const ReviewRange& range) {
        return range.range_id != range_id.trimmed() &&
               range.name.compare(unique_name, Qt::CaseInsensitive) == 0;
      })) {
    unique_name = QStringLiteral("%1 %2").arg(normalized_name).arg(suffix++);
  }
  const auto preroll = qBound(0.0, snap(preroll_seconds), 60.0);
  const auto postroll = qBound(0.0, snap(postroll_seconds), 60.0);
  if (target->name == unique_name && qFuzzyCompare(target->start_seconds + 1.0, start + 1.0) &&
      qFuzzyCompare(target->end_seconds + 1.0, end + 1.0) &&
      qFuzzyCompare(target->preroll_seconds + 1.0, preroll + 1.0) &&
      qFuzzyCompare(target->postroll_seconds + 1.0, postroll + 1.0)) {
    return true;
  }
  pushUndoSnapshot();
  target = std::find_if(
      review_ranges_.begin(), review_ranges_.end(),
      [&range_id](const ReviewRange& range) {
        return range.range_id == range_id.trimmed();
      });
  target->name = unique_name;
  target->start_seconds = start;
  target->end_seconds = end;
  target->preroll_seconds = preroll;
  target->postroll_seconds = postroll;
  setDirty(true);
  emit reviewRangesChanged();
  setStatus(QStringLiteral("Updated review range '%1'.").arg(unique_name));
  return true;
}

bool TimelineDocumentController::deleteReviewRange(const QString& range_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized = range_id.trimmed();
  const auto target = std::find_if(
      review_ranges_.cbegin(), review_ranges_.cend(),
      [&normalized](const ReviewRange& range) {
        return range.range_id == normalized;
      });
  if (target == review_ranges_.cend()) {
    return false;
  }
  const auto name = target->name;
  pushUndoSnapshot();
  review_ranges_.erase(
      std::remove_if(
          review_ranges_.begin(), review_ranges_.end(),
          [&normalized](const ReviewRange& range) {
            return range.range_id == normalized;
          }),
      review_ranges_.end());
  setDirty(true);
  emit reviewRangesChanged();
  setStatus(QStringLiteral("Deleted review range '%1'.").arg(name));
  return true;
}

QVariantMap TimelineDocumentController::mediaAssetMetadata(const QString& asset_id) const {
  const auto metadata = media_asset_metadata_.value(asset_id.trimmed());
  return QVariantMap{
      {QStringLiteral("rating"), metadata.rating},
      {QStringLiteral("disposition"), metadata.disposition},
      {QStringLiteral("favorite"), metadata.disposition == QStringLiteral("favorite")},
      {QStringLiteral("rejected"), metadata.disposition == QStringLiteral("rejected")},
      {QStringLiteral("colorLabel"), metadata.color_label},
      {QStringLiteral("tags"), metadata.tags},
      {QStringLiteral("detectedOnScreenText"), metadata.detected_on_screen_text},
      {QStringLiteral("notes"), metadata.notes},
      {QStringLiteral("customFields"), metadata.custom_fields},
  };
}

QVariantMap TimelineDocumentController::inspectMediaAssetTechnicalMetadata(
    const QVariantMap& catalog_asset) const {
  const auto file_path =
      normalized_path(catalog_asset.value(QStringLiteral("filePath")).toString());
  QVariantMap result{
      {QStringLiteral("schema"), QStringLiteral("timeline-media-technical-metadata:v1")},
      {QStringLiteral("assetId"), catalog_asset.value(QStringLiteral("assetId"))},
      {QStringLiteral("filePath"), file_path},
      {QStringLiteral("fileName"), QFileInfo(file_path).fileName()},
      {QStringLiteral("fileBytes"), QFileInfo(file_path).size()},
      {QStringLiteral("captureDate"), catalog_asset.value(QStringLiteral("captureDate"))},
      {QStringLiteral("camera"), catalog_asset.value(QStringLiteral("cameraLabel"))},
      {QStringLiteral("lens"), catalog_asset.value(QStringLiteral("lensModel"))},
      {QStringLiteral("available"), false},
  };
  const auto ffprobe = QStandardPaths::findExecutable(QStringLiteral("ffprobe"));
  if (ffprobe.isEmpty() || !QFileInfo(file_path).isReadable()) {
    result.insert(QStringLiteral("error"),
                  ffprobe.isEmpty() ? QStringLiteral("ffprobe is unavailable")
                                    : QStringLiteral("source media is offline"));
      return result;
  }
  QProcess process;
  process.start(
      ffprobe,
      {
          QStringLiteral("-v"), QStringLiteral("error"),
          QStringLiteral("-show_entries"),
          QStringLiteral("format=format_name,duration:format_tags=creation_time,Gamma for Look,"
                         "Color for Look,Monitoring Description,Monitoring Base Curve,"
                         "Monitoring Color Primaries,Monitoring Coding Equations,"
                         "Capture Gamma Equation,Color Primaries (Capture Color Primaries),"
                         "Pre-CDL Transform,Post-CDL Transform:stream="
                         "codec_type,codec_name,width,height,r_frame_rate,pix_fmt,color_space,color_range,"
                         "color_transfer,color_primaries,channels,channel_layout,sample_rate:"
                         "stream_tags=Gamma for Look,Color for Look,Monitoring Description,"
                         "Monitoring Base Curve,Monitoring Color Primaries,"
                         "Monitoring Coding Equations,Capture Gamma Equation,"
                         "Color Primaries (Capture Color Primaries),Pre-CDL Transform,"
                         "Post-CDL Transform,gamma_for_look,color_for_look,"
                         "monitoring_description,capture_gamma_equation,color_primaries,"
                         "color_transfer,picture_profile"),
          QStringLiteral("-of"), QStringLiteral("json"), file_path,
      });
  if (!process.waitForFinished(2500) || process.exitStatus() != QProcess::NormalExit ||
      process.exitCode() != 0) {
    process.kill();
    process.waitForFinished(250);
    result.insert(QStringLiteral("error"), QStringLiteral("technical metadata probe timed out or failed"));
    return result;
  }
  QJsonParseError parse_error;
  const auto document = QJsonDocument::fromJson(process.readAllStandardOutput(), &parse_error);
  if (parse_error.error != QJsonParseError::NoError || !document.isObject()) {
    result.insert(QStringLiteral("error"), QStringLiteral("ffprobe returned malformed metadata"));
    return result;
  }
  const auto root = document.object();
  const auto format = root.value(QStringLiteral("format")).toObject();
  const auto streams = root.value(QStringLiteral("streams")).toArray();
  const auto color_metadata_tags = [](const QJsonObject& tags) {
    QVariantMap selected;
    const QStringList color_terms{
        QStringLiteral("color"), QStringLiteral("colour"), QStringLiteral("gamma"),
        QStringLiteral("gamut"), QStringLiteral("log"), QStringLiteral("lut"),
        QStringLiteral("monitor"), QStringLiteral("cdl"), QStringLiteral("capture"),
        QStringLiteral("primar"), QStringLiteral("transfer"),
    };
    for (auto tag = tags.constBegin(); tag != tags.constEnd(); ++tag) {
      auto normalized_key = tag.key().toLower();
      normalized_key.remove(QRegularExpression(QStringLiteral("[^a-z0-9]")));
      if (!std::any_of(color_terms.cbegin(), color_terms.cend(),
                       [&normalized_key](const QString& term) {
                         return normalized_key.contains(term);
                       })) {
        continue;
      }
      const auto value = tag.value().toString().simplified();
      if (!value.isEmpty()) {
        selected.insert(tag.key().left(96), value.left(256));
      }
      if (selected.size() >= 16) {
        break;
      }
    }
    return selected;
  };
  const auto parse_rate = [](const QString& value) {
    const auto parts = value.split(QLatin1Char('/'));
    if (parts.isEmpty()) {
      return 0.0;
    }
    const auto numerator = parts.first().toDouble();
    const auto denominator = parts.size() > 1 ? parts.at(1).toDouble() : 1.0;
    return denominator > 0.0 ? numerator / denominator : 0.0;
  };
  auto video_found = false;
  auto audio_found = false;
  for (const auto& stream_value : streams) {
    const auto stream = stream_value.toObject();
    const auto type = stream.value(QStringLiteral("codec_type")).toString();
    if (type == QStringLiteral("video") && !video_found) {
      video_found = true;
      result.insert(QStringLiteral("videoCodec"), stream.value(QStringLiteral("codec_name")).toString());
      result.insert(QStringLiteral("width"), stream.value(QStringLiteral("width")).toInt());
      result.insert(QStringLiteral("height"), stream.value(QStringLiteral("height")).toInt());
      result.insert(QStringLiteral("frameRate"),
                    parse_rate(stream.value(QStringLiteral("r_frame_rate")).toString()));
      result.insert(QStringLiteral("pixelFormat"), stream.value(QStringLiteral("pix_fmt")).toString());
      result.insert(QStringLiteral("colorSpace"), stream.value(QStringLiteral("color_space")).toString());
      result.insert(QStringLiteral("colorRange"), stream.value(QStringLiteral("color_range")).toString());
      result.insert(QStringLiteral("colorTransfer"), stream.value(QStringLiteral("color_transfer")).toString());
      result.insert(QStringLiteral("colorPrimaries"), stream.value(QStringLiteral("color_primaries")).toString());
      result.insert(QStringLiteral("streamColorMetadataTags"),
                    color_metadata_tags(stream.value(QStringLiteral("tags")).toObject()));
    } else if (type == QStringLiteral("audio") && !audio_found) {
      audio_found = true;
      result.insert(QStringLiteral("audioCodec"), stream.value(QStringLiteral("codec_name")).toString());
      result.insert(QStringLiteral("audioChannels"), stream.value(QStringLiteral("channels")).toInt());
      result.insert(QStringLiteral("channelLayout"), stream.value(QStringLiteral("channel_layout")).toString());
      result.insert(QStringLiteral("sampleRate"), stream.value(QStringLiteral("sample_rate")).toString().toInt());
    }
  }
  result.insert(QStringLiteral("container"), format.value(QStringLiteral("format_name")).toString());
  result.insert(QStringLiteral("durationSeconds"), format.value(QStringLiteral("duration")).toString().toDouble());
  result.insert(QStringLiteral("creationTime"),
                format.value(QStringLiteral("tags")).toObject()
                    .value(QStringLiteral("creation_time")).toString());
  result.insert(QStringLiteral("formatColorMetadataTags"),
                color_metadata_tags(format.value(QStringLiteral("tags")).toObject()));
  const auto profile_evidence = sony_video_profile_evidence(
      result.value(QStringLiteral("streamColorMetadataTags")).toMap(),
      result.value(QStringLiteral("formatColorMetadataTags")).toMap());
  result.insert(QStringLiteral("sourceProfileMetadataResolution"),
                profile_evidence.resolution);
  result.insert(QStringLiteral("sourceProfileGamma"), profile_evidence.gamma);
  result.insert(QStringLiteral("sourceProfileGamut"), profile_evidence.gamut);
  result.insert(QStringLiteral("suggestedVideoInputTransform"),
                profile_evidence.suggested_transform);
  result.insert(QStringLiteral("hasVideo"), video_found);
  result.insert(QStringLiteral("hasAudio"), audio_found);
  result.insert(QStringLiteral("available"), true);
  return result;
}

bool TimelineDocumentController::setMediaAssetNotesAndCustomFields(
    const QString& asset_id,
    const QString& notes,
    const QVariantMap& custom_fields) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized_asset_id = asset_id.trimmed();
  if (normalized_asset_id.isEmpty()) {
    return false;
  }
  const auto normalized_notes = notes.trimmed().left(4000);
  QVariantMap normalized_fields;
  QStringList keys = custom_fields.keys();
  std::sort(keys.begin(), keys.end(), [](const QString& left, const QString& right) {
    return left.toCaseFolded() < right.toCaseFolded();
  });
  QSet<QString> folded_keys;
  for (const auto& raw_key : keys) {
    const auto key = raw_key.simplified().left(48);
    const auto folded = key.toCaseFolded();
    const auto value = custom_fields.value(raw_key).toString().simplified().left(200);
    if (key.isEmpty() || value.isEmpty() || folded_keys.contains(folded)) {
      continue;
    }
    folded_keys.insert(folded);
    normalized_fields.insert(key, value);
    if (normalized_fields.size() >= 32) {
      break;
    }
  }
  const auto current = media_asset_metadata_.value(normalized_asset_id);
  if (current.notes == normalized_notes && current.custom_fields == normalized_fields) {
    return true;
  }
  pushUndoSnapshot();
  auto& metadata = media_asset_metadata_[normalized_asset_id];
  metadata.notes = normalized_notes;
  metadata.custom_fields = normalized_fields;
  if (metadata.rating == 0 && metadata.disposition == QStringLiteral("none") &&
      metadata.color_label == QStringLiteral("none") && metadata.tags.isEmpty() &&
      metadata.detected_on_screen_text.isEmpty() && metadata.notes.isEmpty() &&
      metadata.custom_fields.isEmpty()) {
    media_asset_metadata_.remove(normalized_asset_id);
  }
  setDirty(true);
  emit mediaMetadataChanged();
  setStatus(QStringLiteral("Updated notes and %1 custom metadata field%2.")
                .arg(normalized_fields.size())
                .arg(normalized_fields.size() == 1 ? QString{} : QStringLiteral("s")));
  return true;
}

QVariantMap TimelineDocumentController::searchMediaAsset(
    const QString& asset_id,
    const QString& query,
    const QStringList& scopes,
    const QVariantMap& catalog_metadata) const {
  const auto normalized_asset_id = asset_id.trimmed();
  const auto normalized_query = query.simplified().toCaseFolded();
  if (normalized_query.isEmpty()) {
    return {
        {QStringLiteral("matches"), true},
        {QStringLiteral("matchedScopes"), QStringList{}},
        {QStringLiteral("matchSummary"), QString{}},
    };
  }

  const QStringList supported_scopes{
      QStringLiteral("filename"), QStringLiteral("metadata"), QStringLiteral("tags"),
      QStringLiteral("transcript"), QStringLiteral("captions"), QStringLiteral("markers"),
      QStringLiteral("text"),
  };
  QSet<QString> active_scopes;
  for (const auto& scope_value : scopes) {
    const auto scope = scope_value.trimmed().toLower();
    if (scope == QStringLiteral("all")) {
      active_scopes = QSet<QString>(supported_scopes.cbegin(), supported_scopes.cend());
      break;
    }
    if (supported_scopes.contains(scope)) {
      active_scopes.insert(scope);
    }
  }
  if (active_scopes.isEmpty()) {
    active_scopes = QSet<QString>(supported_scopes.cbegin(), supported_scopes.cend());
  }

  QHash<QString, QStringList> indexed_values;
  const auto add_value = [&indexed_values](const QString& scope, const QString& value) {
    const auto normalized = value.simplified();
    if (!normalized.isEmpty()) {
      indexed_values[scope].push_back(normalized);
    }
  };
  add_value(QStringLiteral("filename"), normalized_asset_id);
  add_value(QStringLiteral("filename"),
            QFileInfo(catalog_metadata.value(QStringLiteral("filePath")).toString()).fileName());
  add_value(QStringLiteral("filename"),
            catalog_metadata.value(QStringLiteral("cameraLabel")).toString());
  const QStringList catalog_metadata_keys{
      QStringLiteral("captureDate"), QStringLiteral("lensModel"),
      QStringLiteral("locationPath"), QStringLiteral("projectSummary"),
      QStringLiteral("mediaType"), QStringLiteral("durationText"),
      QStringLiteral("importedAt"),
  };
  for (const auto& key : catalog_metadata_keys) {
    add_value(QStringLiteral("metadata"), catalog_metadata.value(key).toString());
  }
  for (const auto& project :
       catalog_metadata.value(QStringLiteral("projectNames")).toStringList()) {
    add_value(QStringLiteral("metadata"), project);
  }

  const auto metadata = media_asset_metadata_.value(normalized_asset_id);
  for (const auto& tag : metadata.tags) {
    add_value(QStringLiteral("tags"), tag);
  }
  add_value(QStringLiteral("metadata"), metadata.disposition);
  add_value(QStringLiteral("metadata"), metadata.color_label);
  if (metadata.rating > 0) {
    add_value(QStringLiteral("metadata"),
              QStringLiteral("%1 star rating").arg(metadata.rating));
  }
  for (const auto& detected_text : metadata.detected_on_screen_text) {
    add_value(QStringLiteral("text"), detected_text);
  }
  add_value(QStringLiteral("metadata"), metadata.notes);
  for (auto field = metadata.custom_fields.constBegin();
       field != metadata.custom_fields.constEnd(); ++field) {
    add_value(QStringLiteral("metadata"), field.key());
    add_value(QStringLiteral("metadata"), field.value().toString());
  }

  QVector<QPair<double, double>> asset_intervals;
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (clip.asset_id != normalized_asset_id) {
        continue;
      }
      add_value(QStringLiteral("filename"), QFileInfo(clip.file_path).fileName());
      add_value(QStringLiteral("filename"), clip.display_label);
      add_value(QStringLiteral("metadata"), clip.file_path);
      for (const auto& word : clip.caption_words) {
        add_value(QStringLiteral("transcript"), word.text);
        add_value(QStringLiteral("transcript"), word.speaker);
      }
      if (clip.media_type != QStringLiteral("caption")) {
        asset_intervals.push_back({clip.start_seconds, clipEndSeconds(clip)});
      }
    }
  }
  const auto overlaps_asset = [&asset_intervals](double start_seconds, double end_seconds) {
    return std::any_of(
        asset_intervals.cbegin(), asset_intervals.cend(),
        [start_seconds, end_seconds](const auto& interval) {
          return start_seconds < interval.second - kBoundaryEpsilon &&
                 end_seconds > interval.first + kBoundaryEpsilon;
        });
  };
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (clip.media_type != QStringLiteral("caption") ||
          !overlaps_asset(clip.start_seconds, clipEndSeconds(clip))) {
        continue;
      }
      add_value(QStringLiteral("captions"), clip.title_text);
      for (const auto& word : clip.caption_words) {
        add_value(QStringLiteral("transcript"), word.text);
        add_value(QStringLiteral("transcript"), word.speaker);
      }
    }
  }
  for (const auto& marker : markers_) {
    if (overlaps_asset(marker.seconds, marker.seconds + kBoundaryEpsilon * 2.0)) {
      add_value(QStringLiteral("markers"), marker.label);
      add_value(QStringLiteral("markers"), marker.note);
      add_value(QStringLiteral("markers"), marker.assignee);
      add_value(QStringLiteral("markers"), marker.status);
    }
  }

  QStringList terms;
  const QRegularExpression term_expression(
      QStringLiteral("\\\"([^\\\"]+)\\\"|(\\S+)"));
  auto term_match = term_expression.globalMatch(normalized_query);
  while (term_match.hasNext()) {
    const auto match = term_match.next();
    const auto term = !match.captured(1).isEmpty() ? match.captured(1) : match.captured(2);
    if (!term.isEmpty()) {
      terms.push_back(term);
    }
  }

  QStringList matched_scopes;
  for (const auto& scope : supported_scopes) {
    if (!active_scopes.contains(scope)) {
      continue;
    }
    const auto haystack = indexed_values.value(scope).join(QLatin1Char(' ')).toCaseFolded();
    if (std::any_of(terms.cbegin(), terms.cend(), [&haystack](const QString& term) {
          return haystack.contains(term);
        })) {
      matched_scopes.push_back(scope);
    }
  }
  const auto combined_haystack = [&]() {
    QStringList values;
    for (const auto& scope : supported_scopes) {
      if (active_scopes.contains(scope)) {
        values.append(indexed_values.value(scope));
      }
    }
    return values.join(QLatin1Char(' ')).toCaseFolded();
  }();
  const auto matches = !terms.isEmpty() &&
                       std::all_of(terms.cbegin(), terms.cend(),
                                   [&combined_haystack](const QString& term) {
                                     return combined_haystack.contains(term);
                                   });
  const QHash<QString, QString> labels{
      {QStringLiteral("filename"), QStringLiteral("Filename")},
      {QStringLiteral("metadata"), QStringLiteral("Metadata")},
      {QStringLiteral("tags"), QStringLiteral("Tags")},
      {QStringLiteral("transcript"), QStringLiteral("Transcript")},
      {QStringLiteral("captions"), QStringLiteral("Captions")},
      {QStringLiteral("markers"), QStringLiteral("Markers")},
      {QStringLiteral("text"), QStringLiteral("On-screen text")},
  };
  QStringList matched_labels;
  for (const auto& scope : matched_scopes) {
    matched_labels.push_back(labels.value(scope, scope));
  }
  return {
      {QStringLiteral("matches"), matches},
      {QStringLiteral("matchedScopes"), matched_scopes},
      {QStringLiteral("matchSummary"), matched_labels.join(QStringLiteral(" · "))},
  };
}

QVariantMap TimelineDocumentController::analyzeMediaUsage(
    const QVariantList& catalog_assets) const {
  QHash<QString, int> usage_counts;
  QHash<QString, double> first_use_seconds;
  QSet<QString> proxy_assets;
  QSet<QString> picture_linked_groups;
  for (const auto& track : tracks_) {
    if (track.kind != TrackKind::Video) {
      continue;
    }
    for (const auto& clip : track.clips) {
      if (!clip.linked_group_id.isEmpty()) {
        picture_linked_groups.insert(clip.linked_group_id);
      }
    }
  }
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (clip.asset_id.isEmpty() || clip.media_type == QStringLiteral("caption") ||
          clip.media_type == QStringLiteral("title") ||
          clip.media_type == QStringLiteral("adjustment") ||
          (track.kind == TrackKind::Audio &&
           picture_linked_groups.contains(clip.linked_group_id))) {
        continue;
      }
      ++usage_counts[clip.asset_id];
      if (!first_use_seconds.contains(clip.asset_id) ||
          clip.start_seconds < first_use_seconds.value(clip.asset_id)) {
        first_use_seconds.insert(clip.asset_id, clip.start_seconds);
      }
      if (!clip.proxy_path.isEmpty()) {
        proxy_assets.insert(clip.asset_id);
      }
    }
  }

  QHash<QString, int> duplicate_group_sizes;
  for (const auto& value : catalog_assets) {
    const auto asset = value.toMap();
    const auto asset_id = asset.value(QStringLiteral("assetId")).toString().trimmed();
    const auto group_key =
        asset.value(QStringLiteral("duplicateGroupKey")).toString().trimmed();
    if (!asset_id.isEmpty() && !removed_media_asset_ids_.contains(asset_id) &&
        !group_key.isEmpty()) {
      ++duplicate_group_sizes[group_key];
    }
  }

  QVariantList items;
  QVariantMap summary{
      {QStringLiteral("used"), 0}, {QStringLiteral("unused"), 0},
      {QStringLiteral("duplicate"), 0}, {QStringLiteral("offline"), 0},
      {QStringLiteral("derivative"), 0},
  };
  for (const auto& value : catalog_assets) {
    const auto asset = value.toMap();
    const auto asset_id = asset.value(QStringLiteral("assetId")).toString().trimmed();
    if (asset_id.isEmpty() || removed_media_asset_ids_.contains(asset_id)) {
      continue;
    }
    const auto file_path = asset.value(QStringLiteral("filePath")).toString();
    const auto group_key =
        asset.value(QStringLiteral("duplicateGroupKey")).toString().trimmed();
    const auto used_count = usage_counts.value(asset_id);
    const auto used = used_count > 0;
    const auto duplicate = !group_key.isEmpty() && duplicate_group_sizes.value(group_key) > 1;
    const auto offline = !asset.value(QStringLiteral("online"), true).toBool() ||
                         (!file_path.isEmpty() && !QFileInfo(file_path).isReadable());
    const auto derivative = asset.value(QStringLiteral("virtualCopy")).toBool() ||
                            !asset.value(QStringLiteral("sourceAssetId")).toString().isEmpty() ||
                            proxy_assets.contains(asset_id);
    summary.insert(used ? QStringLiteral("used") : QStringLiteral("unused"),
                   summary.value(used ? QStringLiteral("used") : QStringLiteral("unused")).toInt() + 1);
    if (duplicate) {
      summary.insert(QStringLiteral("duplicate"),
                     summary.value(QStringLiteral("duplicate")).toInt() + 1);
    }
    if (offline) {
      summary.insert(QStringLiteral("offline"),
                     summary.value(QStringLiteral("offline")).toInt() + 1);
    }
    if (derivative) {
      summary.insert(QStringLiteral("derivative"),
                     summary.value(QStringLiteral("derivative")).toInt() + 1);
    }
    QVariantMap item = asset;
    item.insert(QStringLiteral("used"), used);
    item.insert(QStringLiteral("unused"), !used);
    item.insert(QStringLiteral("usedCount"), used_count);
    item.insert(QStringLiteral("firstUseSeconds"), first_use_seconds.value(asset_id, -1.0));
    item.insert(QStringLiteral("duplicate"), duplicate);
    item.insert(QStringLiteral("duplicateGroupKey"), group_key);
    item.insert(QStringLiteral("offline"), offline);
    item.insert(QStringLiteral("derivative"), derivative);
    items.push_back(item);
  }
  std::sort(items.begin(), items.end(), [](const QVariant& left_value, const QVariant& right_value) {
    const auto left = left_value.toMap();
    const auto right = right_value.toMap();
    if (left.value(QStringLiteral("used")).toBool() !=
        right.value(QStringLiteral("used")).toBool()) {
      return left.value(QStringLiteral("used")).toBool();
    }
    return left.value(QStringLiteral("cameraLabel")).toString().localeAwareCompare(
               right.value(QStringLiteral("cameraLabel")).toString()) < 0;
  });
  return {
      {QStringLiteral("schema"), QStringLiteral("timeline-media-usage:v1")},
      {QStringLiteral("summary"), summary},
      {QStringLiteral("items"), items},
      {QStringLiteral("removedCount"), removed_media_asset_ids_.size()},
  };
}

QVariantMap TimelineDocumentController::revealMediaUsage(const QString& asset_id) {
  const auto normalized_asset_id = asset_id.trimmed();
  ClipRef best_ref;
  const Clip* best_clip = nullptr;
  for (int track_index = 0; track_index < tracks_.size(); ++track_index) {
    const auto& track = tracks_.at(track_index);
    for (int clip_index = 0; clip_index < track.clips.size(); ++clip_index) {
      const auto& clip = track.clips.at(clip_index);
      if (clip.asset_id == normalized_asset_id &&
          (best_clip == nullptr || clip.start_seconds < best_clip->start_seconds)) {
        best_ref = {track_index, clip_index};
        best_clip = &clip;
      }
    }
  }
  if (best_clip == nullptr) {
    setStatus(QStringLiteral("That media item is not used in this sequence."));
    return {{QStringLiteral("timelineUsed"), false}};
  }
  selected_clip_id_ = best_clip->clip_id;
  selected_clip_ids_ = {best_clip->clip_id};
  sequence_playhead_seconds_ = best_clip->start_seconds;
  sequence_playing_ = false;
  updateCurrentIndexFromSelection();
  emit selectionChanged();
  emit playbackStateChanged();
  emit clipsChanged();
  setStatus(QStringLiteral("Revealed the first sequence use of '%1'.")
                .arg(best_clip->display_label));
  return {
      {QStringLiteral("timelineUsed"), true},
      {QStringLiteral("clipId"), best_clip->clip_id},
      {QStringLiteral("trackId"), tracks_.at(best_ref.track_index).track_id},
      {QStringLiteral("sequenceSeconds"), best_clip->start_seconds},
  };
}

int TimelineDocumentController::removeUnusedMediaFromProject(
    const QStringList& asset_ids) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  QSet<QString> normalized_ids;
  for (const auto& value : asset_ids) {
    if (!value.trimmed().isEmpty()) {
      normalized_ids.insert(value.trimmed());
    }
  }
  if (normalized_ids.isEmpty()) {
    return 0;
  }
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (normalized_ids.contains(clip.asset_id)) {
        setStatus(QStringLiteral("Remove was cancelled because at least one selected item is used in the sequence."));
        return 0;
      }
    }
  }
  pushUndoSnapshot();
  for (const auto& asset_id : normalized_ids) {
    removed_media_asset_ids_.insert(asset_id);
    media_asset_bins_.remove(asset_id);
    media_asset_metadata_.remove(asset_id);
  }
  setDirty(true);
  emit mediaBinsChanged();
  emit mediaMetadataChanged();
  setStatus(QStringLiteral("Removed %1 unused media item%2 from this project. Undo is available.")
                .arg(normalized_ids.size())
                .arg(normalized_ids.size() == 1 ? QString{} : QStringLiteral("s")));
  return static_cast<int>(normalized_ids.size());
}

int TimelineDocumentController::consolidateDuplicateMedia(
    const QVariantMap& canonical_asset,
    const QVariantList& duplicate_assets) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto canonical_id =
      canonical_asset.value(QStringLiteral("assetId")).toString().trimmed();
  const auto canonical_group =
      canonical_asset.value(QStringLiteral("duplicateGroupKey")).toString().trimmed();
  const auto canonical_path =
      normalized_path(canonical_asset.value(QStringLiteral("filePath")).toString());
  const auto canonical_duration =
      canonical_asset.value(QStringLiteral("durationSeconds")).toDouble();
  if (canonical_id.isEmpty() || canonical_group.isEmpty() ||
      !QFileInfo(canonical_path).isReadable()) {
    setStatus(QStringLiteral("Choose one online duplicate-group member as the canonical media."));
    return 0;
  }
  QSet<QString> duplicate_ids;
  for (const auto& value : duplicate_assets) {
    const auto duplicate = value.toMap();
    const auto duplicate_id = duplicate.value(QStringLiteral("assetId")).toString().trimmed();
    if (duplicate_id.isEmpty() || duplicate_id == canonical_id ||
        duplicate.value(QStringLiteral("duplicateGroupKey")).toString().trimmed() !=
            canonical_group) {
      setStatus(QStringLiteral("Consolidation was cancelled because the selected media are not one verified duplicate group."));
      return 0;
    }
    duplicate_ids.insert(duplicate_id);
  }
  if (duplicate_ids.isEmpty()) {
    return 0;
  }
  for (const auto& track : tracks_) {
    for (const auto& clip : track.clips) {
      if (!duplicate_ids.contains(clip.asset_id)) {
        continue;
      }
      if (track.locked ||
          (canonical_duration > 0.0 &&
           clip.trim_end_seconds > canonical_duration + kBoundaryEpsilon)) {
        setStatus(track.locked
                      ? QStringLiteral("Unlock every affected track before consolidating duplicates.")
                      : QStringLiteral("The canonical source is too short for an existing edit; nothing changed."));
        return 0;
      }
    }
  }
  pushUndoSnapshot();
  QSet<QString> replaced_logical_uses;
  for (auto& track : tracks_) {
    for (auto& clip : track.clips) {
      if (!duplicate_ids.contains(clip.asset_id)) {
        continue;
      }
      clip.asset_id = canonical_id;
      clip.file_path = canonical_path;
      const auto canonical_label =
          canonical_asset.value(QStringLiteral("cameraLabel")).toString().trimmed();
      const auto canonical_poster =
          canonical_asset.value(QStringLiteral("thumbnailSource")).toString().trimmed();
      if (!canonical_label.isEmpty()) {
        clip.display_label = canonical_label;
      }
      if (!canonical_poster.isEmpty()) {
        clip.poster_source = canonical_poster;
      }
      clip.source_file_size = QFileInfo(canonical_path).size();
      clip.source_identity_signature = media_identity_signature(canonical_path);
      clip.source_content_sha256.clear();
      clip.source_integrity_status = QStringLiteral("pending");
      replaced_logical_uses.insert(
          clip.linked_group_id.isEmpty() ? clip.clip_id : clip.linked_group_id);
    }
  }
  for (const auto& duplicate_id : duplicate_ids) {
    removed_media_asset_ids_.insert(duplicate_id);
    media_asset_bins_.remove(duplicate_id);
    media_asset_metadata_.remove(duplicate_id);
  }
  syncAudioTracks();
  source_integrity_completed_revisions_.remove(media_revision_key(canonical_path));
  requestMediaAnalysis(canonical_path);
  emitAllState();
  emit mediaBinsChanged();
  emit mediaMetadataChanged();
  setDirty(true);
  const auto replaced_count = static_cast<int>(replaced_logical_uses.size());
  setStatus(QStringLiteral("Consolidated %1 sequence use%2 into '%3'; duplicate project entries were removed. Undo is available.")
                .arg(replaced_count)
                .arg(replaced_count == 1 ? QString{} : QStringLiteral("s"))
                .arg(canonical_asset.value(QStringLiteral("cameraLabel")).toString().isEmpty()
                         ? canonical_id
                         : canonical_asset.value(QStringLiteral("cameraLabel")).toString()));
  return replaced_count;
}

bool TimelineDocumentController::setMediaAssetDetectedOnScreenText(
    const QString& asset_id,
    const QStringList& detected_text) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized_asset_id = asset_id.trimmed();
  if (normalized_asset_id.isEmpty()) {
    return false;
  }
  QStringList normalized_values;
  QSet<QString> folded_values;
  for (const auto& value : detected_text) {
    const auto normalized = value.simplified().left(160);
    const auto folded = normalized.toCaseFolded();
    if (normalized.isEmpty() || folded_values.contains(folded)) {
      continue;
    }
    folded_values.insert(folded);
    normalized_values.push_back(normalized);
    if (normalized_values.size() >= 128) {
      break;
    }
  }
  if (media_asset_metadata_.value(normalized_asset_id).detected_on_screen_text ==
      normalized_values) {
    return true;
  }
  pushUndoSnapshot();
  auto& metadata = media_asset_metadata_[normalized_asset_id];
  metadata.detected_on_screen_text = normalized_values;
  if (metadata.rating == 0 && metadata.disposition == QStringLiteral("none") &&
      metadata.color_label == QStringLiteral("none") && metadata.tags.isEmpty() &&
      metadata.detected_on_screen_text.isEmpty() && metadata.notes.isEmpty() &&
      metadata.custom_fields.isEmpty()) {
    media_asset_metadata_.remove(normalized_asset_id);
  }
  setDirty(true);
  emit mediaMetadataChanged();
  setStatus(QStringLiteral("Updated searchable on-screen text for one media item."));
  return true;
}

QString TimelineDocumentController::requestMediaHoverFrame(
    const QString& asset_id,
    const QString& file_path,
    double source_seconds) {
  const auto normalized_asset_id = asset_id.trimmed();
  const auto normalized_file_path = normalized_path(file_path);
  if (normalized_asset_id.isEmpty() || !isVideoFile(normalized_file_path) ||
      !QFileInfo(normalized_file_path).isReadable()) {
    return {};
  }
  source_seconds = qBound(0.0, source_seconds, 21600.0);
  source_seconds = std::round(source_seconds * 1000.0) / 1000.0;
  const auto revision_key = media_revision_key(normalized_file_path);
  const auto request_key = QStringLiteral("%1|%2")
                               .arg(revision_key,
                                    QString::number(source_seconds, 'f', 3));
  const auto cache_root = QDir(poster_cache_root()).filePath(QStringLiteral("hover"));
  const auto cache_name = QString::fromLatin1(
      QCryptographicHash::hash(request_key.toUtf8(), QCryptographicHash::Sha256)
          .toHex()) + QStringLiteral(".jpg");
  const auto output_path = QDir(cache_root).filePath(cache_name);
  if (QFileInfo(output_path).isReadable()) {
    return QUrl::fromLocalFile(output_path).toString();
  }
  if (media_hover_frame_requests_in_flight_.contains(request_key)) {
    return {};
  }

  // Pointer motion should favor the latest position for an asset. Remove its
  // obsolete queued requests, while never interrupting the frame currently
  // decoding and never allowing the queue to grow without bound.
  for (auto request = media_hover_frame_queue_.begin();
       request != media_hover_frame_queue_.end();) {
    if (request->asset_id == normalized_asset_id) {
      media_hover_frame_requests_in_flight_.remove(request->request_key);
      request = media_hover_frame_queue_.erase(request);
    } else {
      ++request;
    }
  }
  while (media_hover_frame_queue_.size() >= 24) {
    media_hover_frame_requests_in_flight_.remove(
        media_hover_frame_queue_.constFirst().request_key);
    media_hover_frame_queue_.removeFirst();
  }
  media_hover_frame_requests_in_flight_.insert(request_key);
  media_hover_frame_queue_.push_back({
      normalized_asset_id,
      normalized_file_path,
      revision_key,
      request_key,
      output_path,
      source_seconds,
  });
  startNextMediaHoverFrame();
  return {};
}

bool TimelineDocumentController::setMediaAssetRating(
    const QStringList& asset_ids,
    int rating) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  rating = qBound(0, rating, 5);
  QSet<QString> unique_ids;
  for (const auto& value : asset_ids) {
    if (!value.trimmed().isEmpty()) {
      unique_ids.insert(value.trimmed());
    }
  }
  auto changed = false;
  for (const auto& asset_id : unique_ids) {
    if (media_asset_metadata_.value(asset_id).rating != rating) {
      changed = true;
      break;
    }
  }
  if (!changed) {
    return !unique_ids.isEmpty();
  }
  pushUndoSnapshot();
  for (const auto& asset_id : unique_ids) {
    auto& metadata = media_asset_metadata_[asset_id];
    metadata.rating = rating;
    if (metadata.rating == 0 && metadata.disposition == QStringLiteral("none") &&
        metadata.color_label == QStringLiteral("none") && metadata.tags.isEmpty() &&
        metadata.detected_on_screen_text.isEmpty() && metadata.notes.isEmpty() &&
        metadata.custom_fields.isEmpty()) {
      media_asset_metadata_.remove(asset_id);
    }
  }
  setDirty(true);
  emit mediaMetadataChanged();
  setStatus(QStringLiteral("Rated %1 media item%2 %3 star%4.")
                .arg(unique_ids.size())
                .arg(unique_ids.size() == 1 ? QString{} : QStringLiteral("s"))
                .arg(rating)
                .arg(rating == 1 ? QString{} : QStringLiteral("s")));
  return true;
}

