bool TimelineDocumentController::setSelectedClipAudioChannelMapping(
    const QString& mode,
    bool swap_channels,
    bool invert_left_phase,
    bool invert_right_phase) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto selected_ref = selectedClipRef();
  const auto* selected = clipAt(selected_ref);
  if (selected == nullptr ||
      (!selected->has_audio && selected->media_type != QStringLiteral("audio"))) {
    setStatus(QStringLiteral("Select a clip with audio before changing source channels."));
    return false;
  }
  const auto normalized_mode = normalized_audio_channel_mode(mode);
  if (selected->audio_channel_mode == normalized_mode &&
      selected->audio_swap_channels == swap_channels &&
      selected->audio_invert_left_phase == invert_left_phase &&
      selected->audio_invert_right_phase == invert_right_phase) {
    return false;
  }

  const auto selected_clip_id = selected->clip_id;
  const auto selected_label = selected->display_label;
  pushUndoSnapshot();
  for (auto& track : tracks_) {
    for (auto& clip : track.clips) {
      if (clip.clip_id != selected_clip_id) {
        continue;
      }
      clip.audio_channel_mode = normalized_mode;
      clip.audio_swap_channels = swap_channels;
      clip.audio_invert_left_phase = invert_left_phase;
      clip.audio_invert_right_phase = invert_right_phase;
    }
  }
  syncAudioTracks();
  emitAllState();
  setDirty(true);
  setStatus(QStringLiteral("Updated source-channel mapping for %1.").arg(selected_label));
  return true;
}

void TimelineDocumentController::setSelectedClipFadeInSeconds(double seconds) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  auto* clip = clipAt(selectedClipRef());
  if (clip == nullptr) {
    return;
  }

  const auto bounded = qBound(0.0, seconds, qMax(0.0, clipTrimmedDuration(*clip) - 0.01));
  if (qAbs(clip->fade_in_seconds - bounded) <= kBoundaryEpsilon) {
    return;
  }
  if (!continuous_edit_active_) {
    pushUndoSnapshot();
  }
  clip->fade_in_seconds = bounded;
  if (clip->fade_out_seconds > qMax(0.0, clipTrimmedDuration(*clip) - clip->fade_in_seconds)) {
    clip->fade_out_seconds = qMax(0.0, clipTrimmedDuration(*clip) - clip->fade_in_seconds);
  }
  syncAudioTracks();
  emitAllState();
  setDirty(true);
}

