bool TimelineDocumentController::updateSequenceMarkerReview(
    const QString& marker_id,
    const QString& label,
    const QString& note,
    const QString& status,
    const QString& assignee,
    const QString& approval_state,
    bool completed) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  for (auto index = 0; index < markers_.size(); ++index) {
    const auto& marker = markers_.at(index);
    if (marker.marker_id != marker_id) {
      continue;
    }
    const auto next_label = label.simplified().isEmpty()
                                ? marker.label
                                : label.simplified().left(160);
    const auto next_note = note.trimmed().left(4000);
    const auto next_status = normalized_marker_status(status);
    const auto next_assignee = assignee.simplified().left(120);
    const auto next_approval = normalized_review_approval_state(approval_state);
    if (marker.label == next_label && marker.note == next_note &&
        marker.status == next_status && marker.assignee == next_assignee &&
        marker.approval_state == next_approval && marker.completed == completed) {
      return false;
    }
    const auto is_review_note = marker.review_note;
    pushUndoSnapshot();
    markers_[index].label = next_label;
    markers_[index].note = next_note;
    markers_[index].status = next_status;
    markers_[index].assignee = next_assignee;
    markers_[index].approval_state = next_approval;
    markers_[index].completed = completed;
    emitMarkersState();
    setDirty(true);
    setStatus(is_review_note
                  ? QStringLiteral("Updated the review note as one edit.")
                  : QStringLiteral("Updated the marker as one edit."));
    return true;
  }
  return false;
}

QString TimelineDocumentController::exportReviewNotes(const QString& requested_file_path) {
  const auto notes = reviewNotes();
  if (notes.isEmpty()) {
    setStatus(QStringLiteral("Add a review note before exporting a review package."));
    return {};
  }
  auto output_path = requested_file_path.trimmed();
  const auto requested_url = QUrl(output_path);
  if (requested_url.isLocalFile()) {
    output_path = requested_url.toLocalFile();
  }
  if (output_path.isEmpty()) {
    auto base_path = saved_document_path_;
    if (base_path.isEmpty()) {
      const auto export_root =
          QDir(timelineDocumentsRootPath()).filePath(QStringLiteral("review-exports"));
      if (!QDir().mkpath(export_root)) {
        setStatus(QStringLiteral("Unable to create the review export folder."));
        return {};
      }
      base_path = QDir(export_root).filePath(
          timeline_id_.isEmpty() ? QStringLiteral("untitled") : timeline_id_);
    }
    const QFileInfo base_info(base_path);
    output_path = QDir(base_info.absolutePath()).filePath(
        QStringLiteral("%1-review.json").arg(base_info.completeBaseName()));
  } else {
    output_path = normalized_path(output_path);
    if (!output_path.endsWith(QStringLiteral(".json"), Qt::CaseInsensitive)) {
      output_path += QStringLiteral(".json");
    }
    if (!QDir().mkpath(QFileInfo(output_path).absolutePath())) {
      setStatus(QStringLiteral("Unable to create the review package folder."));
      return {};
    }
  }

  QJsonArray note_array;
  const auto fps = framesPerSecond();
  for (const auto& marker : markers_) {
    if (!marker.review_note) {
      continue;
    }
    QJsonObject object;
    object.insert(QStringLiteral("exchangeId"), marker.marker_id);
    object.insert(QStringLiteral("frame"), qRound64(marker.seconds * fps));
    object.insert(QStringLiteral("seconds"), marker.seconds);
    object.insert(QStringLiteral("timecode"), formatDurationText(marker.seconds));
    object.insert(QStringLiteral("label"), marker.label);
    object.insert(QStringLiteral("note"), marker.note);
    object.insert(QStringLiteral("assignee"), marker.assignee);
    object.insert(QStringLiteral("approvalState"), marker.approval_state);
    object.insert(QStringLiteral("status"), marker.status);
    object.insert(QStringLiteral("resolved"), marker.completed);
    object.insert(QStringLiteral("color"), marker.color);
    note_array.push_back(object);
  }
  QJsonObject root;
  root.insert(QStringLiteral("format"), QStringLiteral("framehouse-review-notes"));
  root.insert(QStringLiteral("version"), 1);
  root.insert(QStringLiteral("timelineId"), timeline_id_);
  root.insert(QStringLiteral("timelineName"), timeline_name_);
  root.insert(QStringLiteral("frameRate"), fps);
  root.insert(QStringLiteral("sequenceWidth"), sequence_size_.width());
  root.insert(QStringLiteral("sequenceHeight"), sequence_size_.height());
  root.insert(QStringLiteral("exportedAt"), QDateTime::currentDateTimeUtc().toString(Qt::ISODate));
  root.insert(QStringLiteral("notes"), note_array);

  QSaveFile file(output_path);
  const auto bytes = QJsonDocument(root).toJson(QJsonDocument::Indented);
  if (!file.open(QIODevice::WriteOnly) || file.write(bytes) != bytes.size() || !file.commit()) {
    setStatus(QStringLiteral("Unable to write the review package."));
    return {};
  }
  setStatus(QStringLiteral("Exported %1 review note%2 to %3.")
                .arg(note_array.size())
                .arg(note_array.size() == 1 ? QString{} : QStringLiteral("s"))
                .arg(QDir::toNativeSeparators(output_path)));
  return output_path;
}

int TimelineDocumentController::importReviewNotes(const QString& requested_file_path) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  auto input_path = requested_file_path.trimmed();
  const auto requested_url = QUrl(input_path);
  if (requested_url.isLocalFile()) {
    input_path = requested_url.toLocalFile();
  }
  QFile file(normalized_path(input_path));
  if (!file.open(QIODevice::ReadOnly)) {
    setStatus(QStringLiteral("Unable to open the review package."));
    return 0;
  }
  QJsonParseError parse_error;
  const auto document = QJsonDocument::fromJson(file.readAll(), &parse_error);
  const auto root = document.object();
  const auto package_format = root.value(QStringLiteral("format")).toString();
  if (parse_error.error != QJsonParseError::NoError || !document.isObject() ||
      (package_format != QStringLiteral("framehouse-review-notes") &&
       package_format != QStringLiteral("stillfold-review-notes")) ||
      root.value(QStringLiteral("version")).toInt() != 1) {
    setStatus(QStringLiteral("The selected file is not a supported Looksy review package."));
    return 0;
  }
  const auto package_fps = root.value(QStringLiteral("frameRate")).toDouble();
  if (qAbs(package_fps - framesPerSecond()) > 0.001) {
    setStatus(QStringLiteral("Review package frame rate %1 does not match this timeline's %2 fps.")
                  .arg(QString::number(package_fps, 'f', 3),
                       QString::number(framesPerSecond(), 'f', 3)));
    return 0;
  }
  const auto values = root.value(QStringLiteral("notes")).toArray();
  if (values.isEmpty()) {
    setStatus(QStringLiteral("The review package contains no notes."));
    return 0;
  }
  auto next_markers = markers_;
  auto changed_count = 0;
  for (const auto& value : values) {
    const auto object = value.toObject();
    auto exchange_id = object.value(QStringLiteral("exchangeId")).toString().trimmed();
    if (exchange_id.isEmpty()) {
      exchange_id = QUuid::createUuid().toString(QUuid::WithoutBraces);
    }
    auto marker_index = -1;
    for (auto index = 0; index < next_markers.size(); ++index) {
      if (next_markers.at(index).marker_id == exchange_id) {
        marker_index = index;
        break;
      }
    }
    Marker marker = marker_index >= 0 ? next_markers.at(marker_index) : Marker{};
    marker.marker_id = exchange_id;
    marker.label = object.value(QStringLiteral("label")).toString().simplified().left(160);
    if (marker.label.isEmpty()) {
      marker.label = QStringLiteral("Imported review note");
    }
    marker.note = object.value(QStringLiteral("note")).toString().trimmed().left(4000);
    marker.assignee = object.value(QStringLiteral("assignee")).toString().simplified().left(120);
    marker.approval_state = normalized_review_approval_state(
        object.value(QStringLiteral("approvalState")).toString());
    marker.status = normalized_marker_status(object.value(QStringLiteral("status")).toString());
    marker.completed = object.value(QStringLiteral("resolved")).toBool(false);
    marker.review_note = true;
    const auto parsed_color = QColor(object.value(QStringLiteral("color")).toString());
    marker.color = parsed_color.isValid() ? parsed_color.name() : QStringLiteral("#58a9c4");
    const auto frame = qMax<qint64>(0, object.value(QStringLiteral("frame")).toInteger());
    marker.seconds = qBound(
        0.0, static_cast<double>(frame) / framesPerSecond(), totalDurationSeconds());
    if (marker_index >= 0) {
      next_markers[marker_index] = marker;
    } else {
      next_markers.push_back(marker);
    }
    ++changed_count;
  }
  if (changed_count == 0) {
    return 0;
  }
  pushUndoSnapshot();
  markers_ = next_markers;
  std::sort(
      markers_.begin(), markers_.end(),
      [](const auto& left, const auto& right) { return left.seconds < right.seconds; });
  emitMarkersState();
  setDirty(true);
  setStatus(QStringLiteral("Imported or updated %1 frame-accurate review note%2 as one edit.")
                .arg(changed_count)
                .arg(changed_count == 1 ? QString{} : QStringLiteral("s")));
  return changed_count;
}

void TimelineDocumentController::seekSequenceMarker(const QString& marker_id) {
  for (const auto& marker : markers_) {
    if (marker.marker_id != marker_id) {
      continue;
    }
    seekSequenceSeconds(marker.seconds);
    return;
  }
}

bool TimelineDocumentController::seekNextSequenceMarker() {
  for (const auto& marker : markers_) {
    if (marker.seconds > sequence_playhead_seconds_ + kBoundaryEpsilon) {
      seekSequenceSeconds(marker.seconds);
      return true;
    }
  }
  return false;
}

bool TimelineDocumentController::seekPreviousSequenceMarker() {
  for (auto index = markers_.size() - 1; index >= 0; --index) {
    const auto& marker = markers_.at(index);
    if (marker.seconds < sequence_playhead_seconds_ - kBoundaryEpsilon) {
      seekSequenceSeconds(marker.seconds);
      return true;
    }
  }
  return false;
}

bool TimelineDocumentController::seekNextEditPoint() {
  QVector<double> boundaries;
  for (const auto& track : tracks_) {
    if (track.kind != TrackKind::Video) {
      continue;
    }
    for (const auto& clip : track.clips) {
      boundaries.push_back(qMax(0.0, clip.start_seconds));
      boundaries.push_back(qMax(0.0, clipEndSeconds(clip)));
    }
  }
  if (boundaries.isEmpty()) {
    return false;
  }

  std::sort(boundaries.begin(), boundaries.end());
  double previous_value = -1.0;
  for (const auto value : boundaries) {
    if (previous_value >= 0.0 && qAbs(value - previous_value) <= kBoundaryEpsilon) {
      continue;
    }
    previous_value = value;
    if (value > sequence_playhead_seconds_ + kBoundaryEpsilon) {
      seekSequenceSeconds(value);
      return true;
    }
  }
  return false;
}

bool TimelineDocumentController::seekPreviousEditPoint() {
  QVector<double> boundaries;
  for (const auto& track : tracks_) {
    if (track.kind != TrackKind::Video) {
      continue;
    }
    for (const auto& clip : track.clips) {
      boundaries.push_back(qMax(0.0, clip.start_seconds));
      boundaries.push_back(qMax(0.0, clipEndSeconds(clip)));
    }
  }
  if (boundaries.isEmpty()) {
    return false;
  }

  std::sort(boundaries.begin(), boundaries.end());
  double previous_value = -1.0;
  auto candidate = -1.0;
  for (const auto value : boundaries) {
    if (previous_value >= 0.0 && qAbs(value - previous_value) <= kBoundaryEpsilon) {
      continue;
    }
    previous_value = value;
    if (value < sequence_playhead_seconds_ - kBoundaryEpsilon) {
      candidate = value;
    }
  }
  if (candidate < 0.0) {
    return false;
  }
  seekSequenceSeconds(candidate);
  return true;
}

void TimelineDocumentController::removeSequenceMarker(const QString& marker_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  for (int index = 0; index < markers_.size(); ++index) {
    if (markers_.at(index).marker_id != marker_id) {
      continue;
    }
    pushUndoSnapshot();
    markers_.removeAt(index);
    emitMarkersState();
    setDirty(true);
    return;
  }
}

void TimelineDocumentController::playSequence() {
  if (clipCount() == 0) {
    return;
  }

  if (sequence_playhead_seconds_ >= totalDurationSeconds() - kBoundaryEpsilon) {
    seekSequenceSeconds(0.0);
  }
  sequence_playing_ = true;
  setBackgroundWorkIntent(
      background_work_workspace_visible_,
      background_work_interaction_active_,
      background_work_visible_clip_ids_.values());
  emit playbackStateChanged();
}

void TimelineDocumentController::pauseSequence() {
  if (!sequence_playing_) {
    return;
  }

  sequence_playing_ = false;
  setBackgroundWorkIntent(
      background_work_workspace_visible_,
      background_work_interaction_active_,
      background_work_visible_clip_ids_.values());
  emit playbackStateChanged();
}

void TimelineDocumentController::seekSequenceSeconds(double seconds) {
  sequence_playhead_seconds_ = qBound(0.0, seconds, totalDurationSeconds());
  sequence_playing_ = false;
  setBackgroundWorkIntent(
      background_work_workspace_visible_,
      background_work_interaction_active_,
      background_work_visible_clip_ids_.values());

  const auto selected_ref = selectedClipRef();
  const auto* selected_clip = clipAt(selected_ref);
  const auto selection_remains_under_playhead =
      selected_clip != nullptr &&
      sequence_playhead_seconds_ + kBoundaryEpsilon >= selected_clip->start_seconds &&
      sequence_playhead_seconds_ < clipEndSeconds(*selected_clip) + kBoundaryEpsilon;
  const auto active_ref = selection_remains_under_playhead
                              ? selected_ref
                              : activeVideoClipRefForTime(sequence_playhead_seconds_);
  const auto* active_clip = clipAt(active_ref);
  if (active_clip == nullptr) {
    selected_clip_id_.clear();
    selected_clip_ids_.clear();
    current_index_ = -1;
    current_clip_playhead_seconds_ = 0.0;
    preview_source_.clear();
    emit selectionChanged();
    emit previewSourceChanged();
    emit playbackStateChanged();
    return;
  }

  selected_clip_id_ = active_clip->clip_id;
  updateCurrentIndexFromSelection();
  current_clip_playhead_seconds_ = clipLocalSecondsForSequenceTime(*active_clip, sequence_playhead_seconds_);
  preview_source_ = active_clip->poster_source;
  emit selectionChanged();
  emit previewSourceChanged();
  emit playbackStateChanged();
}

bool TimelineDocumentController::applyTimecodeEntry(
    const QString& operation,
    const QString& value) {
  const auto normalized_operation = operation.trimmed().toLower();
  auto timecode_value = value.trimmed();
  auto relative = false;
  auto relative_sign = 1.0;
  if (timecode_value.startsWith(QLatin1Char('+')) ||
      timecode_value.startsWith(QLatin1Char('-'))) {
    relative = true;
    relative_sign = timecode_value.startsWith(QLatin1Char('-')) ? -1.0 : 1.0;
    timecode_value.remove(0, 1);
  }
  const auto parsed = parsed_editor_timecode_seconds(
      timecode_value, framesPerSecond());
  if (!parsed.has_value()) {
    setStatus(QStringLiteral("Enter HH:MM:SS:FF, MM:SS:FF, or seconds; prefix + or - for an offset."));
    return false;
  }

  const auto ref = selectedClipRef();
  const auto* clip = clipAt(ref);
  const auto requires_clip =
      normalized_operation == QStringLiteral("place") ||
      normalized_operation == QStringLiteral("trim-start") ||
      normalized_operation == QStringLiteral("trim-end") ||
      normalized_operation == QStringLiteral("duration");
  if (requires_clip && clip == nullptr) {
    setStatus(QStringLiteral("Select a clip before applying that timecode operation."));
    return false;
  }

  auto base_seconds = sequence_playhead_seconds_;
  if (clip != nullptr) {
    if (normalized_operation == QStringLiteral("place") ||
        normalized_operation == QStringLiteral("trim-start")) {
      base_seconds = clip->start_seconds;
    } else if (normalized_operation == QStringLiteral("trim-end")) {
      base_seconds = clipEndSeconds(*clip);
    } else if (normalized_operation == QStringLiteral("duration")) {
      base_seconds = clipTrimmedDuration(*clip);
    }
  }
  auto target_seconds = relative
                            ? base_seconds + relative_sign * *parsed
                            : *parsed;
  target_seconds = static_cast<double>(qRound64(target_seconds * framesPerSecond())) /
                   framesPerSecond();
  if (target_seconds < 0.0) {
    setStatus(QStringLiteral("That timecode offset would move before sequence start."));
    return false;
  }

  if (normalized_operation == QStringLiteral("seek")) {
    seekSequenceSeconds(target_seconds);
    setStatus(QStringLiteral("Playhead set from timecode."));
    return true;
  }
  if (normalized_operation == QStringLiteral("marker")) {
    seekSequenceSeconds(target_seconds);
    const auto marker_id = addSequenceMarker(QStringLiteral("Marker"));
    if (marker_id.isEmpty()) {
      return false;
    }
    setStatus(QStringLiteral("Marker placed from timecode."));
    return true;
  }
  if (clip == nullptr) {
    return false;
  }

  const auto before_start = clip->start_seconds;
  const auto before_end = clipEndSeconds(*clip);
  if (normalized_operation == QStringLiteral("place")) {
    moveSelectedClipToTrackRow(ref.track_index, target_seconds);
  } else if (normalized_operation == QStringLiteral("trim-start")) {
    trimSelectedClipStartToSequenceSeconds(target_seconds, false);
  } else if (normalized_operation == QStringLiteral("trim-end")) {
    trimSelectedClipEndToSequenceSeconds(target_seconds, false);
  } else if (normalized_operation == QStringLiteral("duration")) {
    if (target_seconds < 1.0 / framesPerSecond()) {
      setStatus(QStringLiteral("Clip duration must be at least one frame."));
      return false;
    }
    trimSelectedClipEndToSequenceSeconds(before_start + target_seconds, false);
  } else {
    setStatus(QStringLiteral("Choose Seek, Place, Trim In, Trim Out, Duration, or Marker."));
    return false;
  }

  const auto* updated = clipAt(selectedClipRef());
  if (updated == nullptr) {
    return false;
  }
  const auto changed = qAbs(updated->start_seconds - before_start) > kBoundaryEpsilon ||
                       qAbs(clipEndSeconds(*updated) - before_end) > kBoundaryEpsilon;
  if (!changed) {
    setStatus(QStringLiteral("The clip is already at that timecode or has no source handle there."));
    return false;
  }
  setStatus(QStringLiteral("Applied %1 from timecode.").arg(normalized_operation));
  return true;
}

void TimelineDocumentController::seekCurrentClipSeconds(double seconds) {
  const auto* clip = clipAt(selectedClipRef());
  if (clip == nullptr) {
    return;
  }

  current_clip_playhead_seconds_ = qBound(clip->trim_start_seconds, seconds, clip->trim_end_seconds);
  sequence_playhead_seconds_ =
      clip->start_seconds +
      clipTimelineSecondsForSourceTime(
          *clip,
          current_clip_playhead_seconds_,
          sequence_playhead_seconds_ - clip->start_seconds);
  sequence_playing_ = false;
  emit playbackStateChanged();
}

void TimelineDocumentController::stepSequenceFrames(int direction) {
  if (direction == 0) {
    return;
  }

  seekSequenceSeconds(sequence_playhead_seconds_ + (static_cast<double>(direction) / framesPerSecond()));
}

void TimelineDocumentController::syncPlaybackPosition(double clip_seconds) {
  const auto* clip = clipAt(selectedClipRef());
  if (clip == nullptr) {
    return;
  }

  current_clip_playhead_seconds_ = qBound(clip->trim_start_seconds, clip_seconds, clip->trim_end_seconds);
  sequence_playhead_seconds_ =
      clip->start_seconds +
      clipTimelineSecondsForSourceTime(
          *clip,
          current_clip_playhead_seconds_,
          sequence_playhead_seconds_ - clip->start_seconds);
  emit playbackStateChanged();
}

void TimelineDocumentController::syncGapPlaybackPosition(double sequence_seconds) {
  if (!sequence_playing_) {
    return;
  }

  const auto previous_selected_clip_id = selected_clip_id_;
  const auto previous_preview_source = preview_source_;
  sequence_playhead_seconds_ = qBound(0.0, sequence_seconds, totalDurationSeconds());

  const auto active_ref = activeVideoClipRefForTime(sequence_playhead_seconds_);
  const auto* active_clip = clipAt(active_ref);
  if (active_clip != nullptr) {
    selected_clip_id_ = active_clip->clip_id;
    selected_clip_ids_.clear();
    selected_clip_ids_.append(active_clip->clip_id);
    updateCurrentIndexFromSelection();
    current_clip_playhead_seconds_ = clipLocalSecondsForSequenceTime(*active_clip, sequence_playhead_seconds_);
    preview_source_ = active_clip->poster_source;
  } else {
    selected_clip_id_.clear();
    selected_clip_ids_.clear();
    current_index_ = -1;
    current_clip_playhead_seconds_ = 0.0;
    preview_source_.clear();
    if (sequence_playhead_seconds_ >= totalDurationSeconds() - kBoundaryEpsilon) {
      sequence_playing_ = false;
    }
  }

  if (previous_selected_clip_id != selected_clip_id_) {
    emit selectionChanged();
  }
  if (previous_preview_source != preview_source_) {
    emit previewSourceChanged();
  }
  emit playbackStateChanged();
}

bool TimelineDocumentController::advancePlaybackAfterClipEnd() {
  if (clipCount() == 0) {
    return false;
  }

  const auto* current_clip = clipAt(selectedClipRef());
  if (current_clip == nullptr) {
    sequence_playing_ = false;
    clampPlaybackState();
    emit playbackStateChanged();
    return false;
  }

  const auto current_clip_end = clipEndSeconds(*current_clip);
  const auto next_ref = nextActiveVideoClipRefAfter(current_clip_end + kBoundaryEpsilon);
  const auto* next_clip = clipAt(next_ref);
  if (next_clip == nullptr) {
    sequence_playing_ = false;
    clampPlaybackState();
    emit playbackStateChanged();
    return false;
  }

  if (next_clip->start_seconds > current_clip_end + kBoundaryEpsilon) {
    selected_clip_id_.clear();
    selected_clip_ids_.clear();
    current_index_ = -1;
    current_clip_playhead_seconds_ = 0.0;
    sequence_playhead_seconds_ = current_clip_end;
    preview_source_.clear();
    emit selectionChanged();
    emit previewSourceChanged();
    emit playbackStateChanged();
    return true;
  }

  const auto target_time = current_clip_end;
  selected_clip_id_ = next_clip->clip_id;
  updateCurrentIndexFromSelection();
  current_clip_playhead_seconds_ = clipLocalSecondsForSequenceTime(*next_clip, target_time);
  sequence_playhead_seconds_ = target_time;
  preview_source_ = next_clip->poster_source;
  emit selectionChanged();
  emit previewSourceChanged();
  emit playbackStateChanged();
  return true;
}

QVariantMap TimelineDocumentController::effectiveTrackGroupTransform(const Track& track) const {
  struct GroupTransformNode final {
    QString parent_id;
    double scale = 1.0;
    double offset_x = 0.0;
    double offset_y = 0.0;
    double rotation_degrees = 0.0;
  };
  QHash<QString, GroupTransformNode> nodes;
  for (const auto& candidate : tracks_) {
    if (!candidate.group_id.isEmpty() && !nodes.contains(candidate.group_id)) {
      nodes.insert(candidate.group_id, GroupTransformNode{
          candidate.group_parent_id,
          candidate.group_transform_scale,
          candidate.group_transform_offset_x,
          candidate.group_transform_offset_y,
          candidate.group_transform_rotation_degrees,
      });
    }
  }

  const auto frame_width = qMax(1, sequence_size_.width());
  const auto frame_height = qMax(1, sequence_size_.height());
  auto scale = 1.0;
  auto offset_x_pixels = 0.0;
  auto offset_y_pixels = 0.0;
  auto rotation_degrees = 0.0;
  auto has_transform = false;
  auto group_id = track.group_id;
  QSet<QString> visited;
  while (!group_id.isEmpty() && nodes.contains(group_id) && !visited.contains(group_id)) {
    visited.insert(group_id);
    const auto node = nodes.value(group_id);
    const auto angle = node.rotation_degrees * std::numbers::pi / 180.0;
    const auto cosine = std::cos(angle);
    const auto sine = std::sin(angle);
    const auto node_x_pixels = node.offset_x * frame_width;
    const auto node_y_pixels = node.offset_y * frame_height;
    if (!has_transform) {
      scale = node.scale;
      offset_x_pixels = node_x_pixels;
      offset_y_pixels = node_y_pixels;
      rotation_degrees = node.rotation_degrees;
      has_transform = true;
    } else {
      const auto child_x_pixels = offset_x_pixels;
      const auto child_y_pixels = offset_y_pixels;
      offset_x_pixels = node_x_pixels + node.scale *
          (cosine * child_x_pixels - sine * child_y_pixels);
      offset_y_pixels = node_y_pixels + node.scale *
          (sine * child_x_pixels + cosine * child_y_pixels);
      scale *= node.scale;
      rotation_degrees += node.rotation_degrees;
    }
    group_id = node.parent_id;
  }

  QVariantMap result;
  result.insert(QStringLiteral("scale"), qBound(0.25, scale, 2.0));
  result.insert(QStringLiteral("offsetX"),
                 qBound(-0.5, offset_x_pixels / frame_width, 0.5));
  result.insert(QStringLiteral("offsetY"),
                 qBound(-0.5, offset_y_pixels / frame_height, 0.5));
  result.insert(QStringLiteral("rotationDegrees"), std::remainder(rotation_degrees, 360.0));
  return result;
}

